window.STUDY_DATA = {"generatedAt":"2026-08-17","authors":[{"id":"junsoo","displayName":"김준수"},{"id":"chanung","displayName":"안찬웅"},{"id":"seongil","displayName":"이성일"},{"id":"seungjoo","displayName":"이승주"}],"tags":[{"id":"logic-edge-case","group":"correctness","label":"엣지 케이스에서 오답"},{"id":"off-by-one","group":"correctness","label":"경계값 하나 차이"},{"id":"wrong-algorithm","group":"correctness","label":"접근 자체가 문제 조건에 안 맞음"},{"id":"overflow","group":"correctness","label":"int 범위 초과 / 자료형 선택"},{"id":"uninitialized-state","group":"correctness","label":"초기화 누락, 테스트케이스 간 상태 오염"},{"id":"missing-return","group":"correctness","label":"반환 누락 / 컴파일 실패"},{"id":"time-complexity","group":"efficiency","label":"시간복잡도가 제약을 못 맞춤"},{"id":"space-complexity","group":"efficiency","label":"불필요하게 큰 메모리"},{"id":"redundant-loop","group":"efficiency","label":"중복 순회 / 합칠 수 있는 반복"},{"id":"redundant-collection","group":"efficiency","label":"불필요한 자료구조·조회 반복"},{"id":"collection-choice","group":"efficiency","label":"자료구조 선택이 부적절"},{"id":"io-performance","group":"efficiency","label":"Scanner 등 느린 입출력"},{"id":"string-concat-in-loop","group":"efficiency","label":"반복문 안 문자열 + 연결"},{"id":"boxing-cost","group":"efficiency","label":"불필요한 오토박싱"},{"id":"magic-branch","group":"structure","label":"합칠 수 있는 분기 나열"},{"id":"magic-number","group":"structure","label":"설명 없는 상수"},{"id":"duplicate-code","group":"structure","label":"복붙된 중복 코드"},{"id":"long-method","group":"structure","label":"한 메서드가 너무 많은 일을 함"},{"id":"dead-code","group":"structure","label":"쓰이지 않는 코드 / 주석 처리된 코드"},{"id":"nonstatic-inner-class","group":"structure","label":"static 이어야 할 중첩 클래스"},{"id":"naming","group":"style","label":"이름이 값을 설명하지 못함"},{"id":"comment-noise","group":"style","label":"코드를 그대로 옮긴 주석 / 오래된 주석"},{"id":"good-decomposition","group":"praise","label":"역할 분리가 좋음"},{"id":"good-complexity","group":"praise","label":"복잡도 선택이 정확함"},{"id":"good-readability","group":"praise","label":"읽기 쉬움"}],"rotation":{"order":["junsoo","chanung","seongil","seungjoo"],"cadence":{"note":"README 기준. 화·목 오전 8:30 + 월/수/금 중 1회","days":["tue","thu","one-of-mon-wed-fri"]},"assignments":[]},"problems":[{"key":"programmers/12904","platform":"programmers","problemId":"12904","title":"가장 긴 팰린드롬","url":"https://school.programmers.co.kr/learn/courses/30/lessons/12904","weeks":[3],"entries":[{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/가장 긴 팰린드롬.java","lines":44,"code":"import java.util.*;\n/*\n    뒤집어도 같은 수중에 가장 긴 것 구하기\n    \n    시간복잡도: n <= 2500 이므로 O(n^2)\n    \n    1. 길이 idx를 n부터 1까지 줄여가며\n    2. 각 시작 위치 i에서 길이 idx짜리가 팰린드롬인지 판정\n    3. 처음 찾은 순간이 가장 긴 것이므로 종료\n*/\nclass Solution {\n    static int maxLen;\n    public int solution(String s) {\n        maxLen = 1;\n\n        int n = s.length();\n        int idx = n;\n        while(idx > 1) {\n            boolean flag = false;\n            for(int i=0; i<n-idx+1; i++) {\n                if(isPalindrome(s, i, i+idx-1)) { \n                    maxLen = idx;\n                    flag = true;\n                    break;\n                }\n            }\n            if(flag) break;\n            idx--;\n        }\n\n        return maxLen;\n    }\n    static boolean isPalindrome(String s, int left, int right) {\n        while(left < right) {\n            if(s.charAt(left) != s.charAt(right)) {\n                return false;\n            }\n            left++;\n            right--;\n        }\n        return true;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":3,"variant":null,"source":"이승주/week3/가장 긴 펠린드롬 길이.java","lines":54,"code":"import java.util.*;\nclass Solution\n    \n    /*\n        각 인덱스의 문자가 중심이 된다고 가정하여 검사,\n        나를 중심으로 양옆을 검사하는 경우 -> 펠린드롬길이가 홀수\n        나와 오른쪽부터 검사해서 넓혀나가는 경우 -> 길이가 짝수\n    */\n{\n    public int solution(String s)\n    {\n        int answer = 0;\n        int max = 0;\n        \n        for(int i = 0; i < s.length(); i++){\n            \n            int oddCnt = PaildromeCnt(s, i-1, i+1);\n            int evenCnt = PaildromeCnt(s,i,i+1);\n            \n            max = Math.max(oddCnt, evenCnt);\n            answer = Math.max(max,answer);\n        }\n        \n        return answer;\n\n        \n    }\n    \n    \n    static int PaildromeCnt(String s, int left, int right){\n        \n        \n        int cnt = 0;\n        \n        if(right-left > 1){   // 나를 중심으로 양 옆을 조사하는 경우에 초기 길이가 1임\n            cnt = 1;\n        }\n        \n        while(left >=0 && right <= s.length()-1){\n            if(s.charAt(left) == s.charAt(right)){\n                cnt += 2;\n                left--;\n                right++;\n            }else{\n                break;\n            }\n        }\n        \n        return cnt;\n    }\n    \n    \n}","review":null}],"teamFeedback":null},{"key":"programmers/17678","platform":"programmers","problemId":"17678","title":"[1차] 셔틀버스","url":"https://school.programmers.co.kr/learn/courses/30/lessons/17678","weeks":[3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/셔틀버스.java","lines":67,"code":"\n/*\n전략\n- 시뮬레이션\n- 각 버스에 대해, 버스에 탄 사람의 시각을 담은 2차원 리스트 초기화\n    - 우선순위 큐로 먼저 도착한 사람이 버스 탈 수 있게 함\n- 결과값은 마지막 버스의 상태만 보면 됨\n    - 마지막 버스에 자리가 있으면 버스 도착 시간에 줄 서면 됨\n    - 마지막 버스에 자리가 없으면 마지막에 탄 사람보다 1분 빠르면 됨\n- 출력 시 fString 사용\n*/\nimport java.util.*;\n\nclass Solution {\n    public String solution(int n, int t, int m, String[] timetable) {\n        List<List<Integer>> people = new ArrayList<>(); // 각 셔틀에 탄 사람의 시간\n        for(int i = 0; i < n; i++){\n            people.add(new ArrayList<>());\n        }\n        \n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for(String time : timetable){\n            pq.offer(timeToNum(time));\n        }\n        \n        for(int num = 0; num < n; num++){\n            int time = 540 + t * num; // 이번 셔틀의 도착 시간\n            Queue<Integer> left = new ArrayDeque<>();\n            \n            while(!pq.isEmpty()){\n                int curr = pq.poll();\n                \n                // 시간, 자리 상 탈 수 있는 경우 타기\n                if(curr <= time && people.get(num).size() < m){\n                    people.get(num).add(curr);\n                }\n                // 못탄 경우 다시 추가\n                else{\n                    left.offer(curr);\n                }\n            }\n            \n            // 남은 사람들을 다시 pq에 추가\n            while(!left.isEmpty()){\n                pq.offer(left.poll());\n            }\n            \n        }        \n        \n        int result = -1;\n        // 맨 마지막 차에 자리가 있으면 도착 시간에 줄서면 됨\n        if(people.get(n - 1).size() < m){\n            result = 540 + (n - 1) * t;\n        }\n        // 맨 마지막 차에 자리가 없으면 마지막에 탄 사람보다 1분 빠르면 됨\n        else{\n            result = people.get(n - 1).get(people.get(n - 1).size() - 1) - 1;\n        }\n        \n        return String.format(\"%02d:%02d\", result / 60, result % 60);\n    }\n    \n    private int timeToNum(String time){\n        return Integer.parseInt(time.substring(0, 2)) * 60 \n            + Integer.parseInt(time.substring(3, 5));\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/셔틀버스.java","lines":66,"code":"import java.util.*;\n/*\n    콘이 정류장에 도착해야 하는 시각중 가장 늦은 시간 구하기\n    :콘은 크루 중 제일 뒤에서 기다림\n    \n    셔틀 운행 횟수: n\n    셔틀 운행 간격: t\n    한 셔틀에 탈 수 있는 최대 크루 수: m\n    크루가 버스 정류장에 도착한 시간: timetable\n    \n    1. 분으로 시간 저장하기\n    2. crew 배열에 시간 저장해서 오름차순\n    3. 콘 없이 크루만 태워본다\n    4. 마지막 버스 상태로 답 결정\n    5. 시간 문자열 변환 \n*/\nclass Solution { \n    public String solution(int n, int t, int m, String[] timetable) {\n        int[] crew = new int[timetable.length];\n        int[] bus = new int[n];\n        \n        for(int i=0; i<timetable.length; i++) {\n            String[] str = timetable[i].split(\":\");\n            int hour = Integer.parseInt(str[0]);\n            int min = Integer.parseInt(str[1]);\n            int total = hour * 60 + min;\n            crew[i] = total;\n        }\n        \n        Arrays.sort(crew);\n        \n        for(int i=0; i<n; i++) {\n            bus[i] = 540 + t * i;\n        }\n        \n        int result = 0;\n        int idx = 0;\n        int cnt = 0;\n        for(int i=0; i<n; i++) {\n            cnt = 0;\n            while(idx < crew.length && crew[idx] <= bus[i] && cnt < m) {\n                idx++;\n                cnt++;\n            }\n        }\n        \n        // 자리가 남으면 막차를 타고, 만석이면 마지막 탑승\n        if(cnt < m) {\n            result = bus[n-1];\n        } else {\n            result = crew[idx-1] - 1;\n        }\n        \n        int hour = result / 60;\n        int min = result % 60;\n\n        StringBuilder sb = new StringBuilder();\n        if(hour < 10) sb.append(\"0\");\n        sb.append(hour).append(\":\");\n        if(min < 10) sb.append(\"0\");\n        sb.append(min);\n\n        return sb.toString();\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":null,"source":"이성일/week3/셔틀버스.java","lines":106,"code":"import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\nclass Solution {\n    static class Time implements Comparable<Time> {\n        int hour;\n        int minute;\n\n        Time(String time) {\n            String[] timeString = time.split(\":\");\n            this.hour = Integer.parseInt(timeString[0]);\n            this.minute = Integer.parseInt(timeString[1]);\n        }\n\n        Time(int hour, int minute) {\n            this.hour = hour;\n            this.minute = minute;\n        }\n\n        @Override\n        public int compareTo(Solution.Time o) {\n            return (this.hour == o.hour) ? Integer.compare(this.minute, o.minute)\n                    : Integer.compare(this.hour, o.hour);\n        }\n    }\n\n    public String solution(int n, int t, int m, String[] timetable) {\n        String answer = \"\";\n\n        // 1. n,t를 활용하여 버스 도착 타임테이블 구성하기\n        List<Time> busTimeTable = new ArrayList<>();\n        int hour = 9, minute = 0;\n        busTimeTable.add(new Time(\"09:00\"));\n        for (int i = 0; i < n - 1; i++) {\n            minute += t;\n            if (minute >= 60) {\n                hour += (minute / 60);\n                minute = (minute % 60);\n            }\n            busTimeTable.add(new Time(hour, minute));\n        }\n\n        List<Time> crewTable = new ArrayList<>();\n        for (String tt : timetable) {\n            crewTable.add(new Time(tt));\n        }\n        Collections.sort(crewTable);\n\n        // 2. 버스테이블을 돌면서 크루테이블에서 m명씩 태우기 (버스 시간 안쪽이어야 함) (크루테이블 정렬)\n        Time cone;\n        int coneHour = busTimeTable.get(busTimeTable.size() - 1).hour;\n        int coneMinute = busTimeTable.get(busTimeTable.size() - 1).minute;\n        cone = new Time(coneHour, coneMinute);\n\n        int nextCrewIdx = 0;\n        int lastBusPassengers = 0;\n        for (int i = 0; i < busTimeTable.size(); i++) {\n            int cnt = 0;\n            for (int j = nextCrewIdx; j < crewTable.size(); j++) {\n                if (cnt == m)\n                    break;\n                if (crewTable.get(j).compareTo(busTimeTable.get(i)) <= 0) {\n                    // 버스시간보다 일찍 온 승객\n                    cnt++;\n                } else\n                    break;\n            }\n            if (i == busTimeTable.size() - 1)\n                lastBusPassengers = cnt;\n            nextCrewIdx += cnt;\n        }\n\n        // 3. 콘은 마지막 버스도착 시간에 도착한다\n        // 3-1 이 때, 마지막 버스 도착 시간 기준 이전에 온 대기열이 m명 이상이면 m번째 사람보다 1분전에는 와야함\n\n        // 마지막 차가 꽉찼다\n        if (lastBusPassengers == m) {\n            cone = crewTable.get(nextCrewIdx - 1);\n            cone.minute -= 1;\n            if (cone.minute < 0) {\n                cone.minute = 59;\n                cone.hour -= 1;\n            }\n        }\n\n        if (cone.hour >= 10 && cone.minute >= 10) {\n            answer = String.format(\"%d:%d\", cone.hour, cone.minute);\n        } else if (cone.hour >= 10 && cone.minute < 10) {\n            answer = String.format(\"%d:%d%d\", cone.hour, 0, cone.minute);\n        } else if (cone.hour < 10 && cone.minute >= 10) {\n            answer = String.format(\"%d%d:%d\", 0, cone.hour, cone.minute);\n        } else {\n            answer = String.format(\"%d%d:%d%d\", 0, cone.hour, 0, cone.minute);\n        }\n\n        return answer;\n    }\n\n    public static void main(String[] args) {\n        Solution s = new Solution();\n        s.solution(0, 0, 0, new String[] { \"hello\", \"java\" });\n\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":3,"variant":null,"source":"이승주/week3/셔틀버스.java","lines":60,"code":"import java.util.*;\n\nclass Solution {\n\n    public String solution(int n, int t, int m, String[] timetable) {\n\n        int[] crew = new int[timetable.length];\n\n        // 시간을 분으로 변환\n        for (int i = 0; i < timetable.length; i++) {\n            String[] s = timetable[i].split(\":\");\n            crew[i] = Integer.parseInt(s[0]) * 60 + Integer.parseInt(s[1]);\n        }\n\n        Arrays.sort(crew);\n\n        int idx = 0;\n        int shuttleTime = 9 * 60;\n\n        for (int bus = 0; bus < n; bus++) {\n\n            int count = 0;\n            int lastCrewTime = 0;\n\n            while (idx < crew.length\n                    && crew[idx] <= shuttleTime\n                    && count < m) {\n\n                lastCrewTime = crew[idx];\n                idx++;\n                count++;\n            }\n\n            // 마지막 셔틀\n            if (bus == n - 1) {\n\n                // 자리 남음\n                if (count < m) {\n                    return format(shuttleTime);\n                }\n\n                // 꽉 참\n                return format(lastCrewTime - 1);\n            }\n\n            shuttleTime += t;\n        }\n\n        return \"\";\n    }\n\n    private String format(int time) {\n\n        int h = time / 60;\n        int m = time % 60;\n\n        return String.format(\"%02d:%02d\", h, m);\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/42579","platform":"programmers","problemId":"42579","title":"베스트앨범","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42579","weeks":[4],"entries":[{"author":"chanung","authorName":"안찬웅","week":4,"variant":null,"source":"안찬웅/week4/베스트앨범.java","lines":107,"code":"import java.util.*;\n/*\n    장르 별 가장 많이 재생된 노래를 두개씩 모으기\n    \n    노래 수록 기준\n    1. 많이 재생된 장르\n    2. 많이 재싱된 노래\n    3. 고유 번호가 낮은 노래\n    \n    genres: 노래 장르\n    plays: 노래별 재생 횟수\n    \n    많이 재생된 장르: classic -> pop\n    : play[3] -> play[0] -> play[1] => 3, 0\n    : play[4] -> play[1] => 4, 1\n    \n    1. 장르별 전체 재생횟수를 구합니다.\n    2. 많이 재생된 장르, 많이재싱된 노래, 고유번호가 낮은 노래 순으로 정렬합니다.\n*/\nclass Solution {\n    class Node implements Comparable<Node> {\n        int genresCount; // 장르별 노래횟수\n        int playsCount; // 노래별 횟수\n        int idx; // 인덱스=고유번호\n        String genres; // 장르이름\n        \n        public Node(int genresCount, int playsCount, int idx, String genres) {\n            this.genresCount = genresCount;\n            this.playsCount = playsCount;\n            this.idx = idx;\n            this.genres = genres;\n        }\n        \n        @Override\n        public int compareTo(Node o) {\n            if(this.genresCount != o.genresCount) { // 장르별 노래횟수내림차순\n                return Integer.compare(o.genresCount, this.genresCount);\n            }\n            if(this.playsCount != o.playsCount) { // 노래별 횟수\n                return Integer.compare(o.playsCount, this.playsCount);\n            }\n            return Integer.compare(this.idx, o.idx);\n        }\n        \n        @Override\n        public String toString() {\n            return genresCount + \" \" + playsCount + \" \" + idx + \" \" + genres;\n        }\n    }  \n    public int[] solution(String[] genres, int[] plays) {\n        HashMap<String, Integer> sing = new HashMap<>(); // 장르별 전체재생횟수\n        PriorityQueue<Node> pq = new PriorityQueue<>();\n        ArrayList<Integer> list = new ArrayList<>();\n        \n        // 1. 장르별 전체 재생횟수를 구합니다.\n        for(int i=0; i<genres.length; i++) {\n            if(!sing.containsKey(genres[i])) {\n                sing.put(genres[i], plays[i]);    \n            } else {\n                sing.put(genres[i], sing.get(genres[i]) + plays[i]);\n            }\n        }\n        \n        // 장르별 노래횟수, 노래별 횟수, 인덱스=고유번호, 장르이름\n        for(int i=0; i<genres.length; i++) {\n            int singCnt = 0; // 장르별 노래횟수\n            if(sing.containsKey(genres[i])) {\n                singCnt = sing.get(genres[i]);\n            }    \n            pq.add(new Node(singCnt, plays[i], i, genres[i]));\n        }\n        \n        int cnt = 0;\n        String str = \"\";\n        while(!pq.isEmpty()) {\n            Node n = pq.poll();\n            // 처음일때\n            if(str.equals(\"\")) {\n                str = n.genres;\n                cnt++;\n                list.add(n.idx);\n                continue;\n            }\n            \n            // 문자열이 같고 한번 이하일 때\n            if(str.equals(n.genres) && cnt <= 1) {\n                cnt++;\n                list.add(n.idx);\n            // 문자열이 같고 두번 이상일 때\n            } else if (str.equals(n.genres) && cnt >= 2) {\n                cnt++;\n            } else { // 문자열이 다를때\n                str = n.genres;\n                list.add(n.idx);\n                cnt = 1;\n            }\n        }\n        \n        int[] res = new int[list.size()];\n        for(int i=0; i<list.size(); i++) {\n            res[i] = list.get(i);\n        }\n        \n        return res;\n    }\n}","review":{"platform":"programmers","problemId":"42579","author":"chanung","source":"안찬웅/week4/베스트앨범.java","week":"4","compiles":"true","verdict":"needs-fix","tags":["logic-edge-case","redundant-collection","magic-branch"],"generatedBy":"claude-opus-5","generatedAt":"2026-08-16","complexity":{"time":"O(N log N)","space":"O(N)"},"body":"# 베스트앨범 (programmers/42579) — chanung\n\n## 접근\n\n장르별 총 재생수를 `HashMap`에 모으고, `(장르총합 desc, 재생수 desc, 고유번호 asc)` 로 `compareTo` 를\n구현한 `Node` 를 우선순위 큐에 전부 넣은 뒤, 하나씩 꺼내며 장르가 바뀌는 순간을 감지해 장르당 2곡씩만 담는다.\n\n정렬 기준 3개를 `compareTo` 하나에 몰아넣은 건 좋다. 문제 조건이 그대로 코드에 드러난다.\n\n## 개선점\n\n### 1. (치명) 장르 총합이 동점이면 장르가 섞여서 3곡 이상 담긴다 — `logic-edge-case`\n\n`while` 루프는 \"직전 장르 `str` 과 다르면 새 장르가 시작됐다\"고 가정한다.\n이 가정은 **같은 장르의 노래가 큐에서 반드시 연달아 나올 때만** 성립한다.\n그런데 `compareTo` 의 1순위는 장르 총합이라, 총합이 같은 장르가 둘이면 2순위인 재생수로 섞여 나온다.\n\n실제로 돌려본 반례:\n\n```java\ngenres = {\"a\",\"a\",\"a\",\"b\",\"b\"}\nplays  = {5,4,1,6,4}       // a 총합 10, b 총합 10 (동점)\n```\n\n큐에서 꺼내지는 순서는 `b3, a0, a1, b4, a2` 가 되고, `b4` 에서 장르가 바뀌었다고 판단해 `cnt` 가 1로 리셋된다.\n그 뒤 `a2` 도 새 장르로 취급돼 담긴다.\n\n```\n실제 출력: [3, 0, 1, 4, 2]   (5곡, a 장르가 3곡)\n기대 출력: 장르당 최대 2곡이므로 4곡\n```\n\n`str`/`cnt` 라는 \"직전 상태\" 대신 **장르별 카운터**를 쓰면 순서 가정 자체가 사라진다.\n\n```java\nMap<String, Integer> picked = new HashMap<>();\nwhile (!pq.isEmpty()) {\n    Node n = pq.poll();\n    int c = picked.getOrDefault(n.genres, 0);\n    if (c < 2) {\n        list.add(n.idx);\n        picked.put(n.genres, c + 1);\n    }\n}\n```\n\n### 2. `cnt <= 1` / `cnt >= 2` 3분기는 카운터 하나면 사라진다 — `magic-branch`\n\n`if (str.equals(\"\")) / else if (같고 cnt<=1) / else if (같고 cnt>=2) / else` 4갈래는\n위 1번 수정본에서 `if (c < 2)` 한 줄이 된다. 첫 진입을 위한 `str.equals(\"\")` 특수 처리도 필요 없어진다.\n빈 문자열을 \"아직 없음\"의 표식으로 쓰는 건 장르 이름이 `\"\"` 인 입력이 오면 깨지기도 한다.\n\n### 3. `sing` 채우는 루프는 `merge` 한 줄 — `redundant-collection`\n\n```java\nsing.merge(genres[i], plays[i], Integer::sum);\n```\n\n`containsKey` → `get` → `put` 은 해시 조회를 3번 한다. `merge` 는 1번이다.\n\n### 4. `Node.genres` 필드명이 단수/복수 혼동을 부른다 — `naming`\n\n파라미터 `genres` 는 배열 전체, 필드 `genres` 는 장르 하나다. 필드는 `genre` 가 맞다.\n같은 이유로 `genresCount` 는 실제로는 \"장르 노래 수\"가 아니라 **장르 총 재생수**다 (주석과 값이 다르다).\n`genreTotalPlays` 처럼 값이 뭔지 드러나는 이름을 권한다.\n\n### 5. `Node` 는 `static` 중첩 클래스로 — `inner-class`\n\n현재 `Node` 는 내부 클래스라 인스턴스마다 바깥 `Solution` 참조를 들고 다닌다.\n`solution` 이 인스턴스 메서드라 컴파일은 되지만, `static class Node` 가 의도에 맞고 메모리도 덜 쓴다.\n\n## 복잡도\n\n- 시간: `O(N log N)` — 전체 노래를 PQ에 넣고 빼는 비용이 지배적. 적정하다.\n- 공간: `O(N)` — PQ + list. 적정하다.\n\n## 요약\n\n정렬 기준을 `compareTo` 로 표현한 뼈대는 좋다. 다만 \"같은 장르는 연달아 나온다\"는 암묵적 가정이\n장르 총합 동점에서 무너져 오답이 된다. 상태 변수(`str`, `cnt`) 대신 장르별 카운터 맵으로 바꾸면\n버그와 4갈래 분기가 동시에 없어진다."}}],"teamFeedback":null},{"key":"programmers/42627","platform":"programmers","problemId":"42627","title":"디스크 컨트롤러","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42627","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/디스크 컨트롤러.java","lines":103,"code":"/*\n로직\n- 우선순위 큐\n- 각 초마다 우선순위 큐에서 우선순위대로 뽑으면서 실행 가능한지 검사\n- 실행 가능하면 소요시간만큼 초 지나고 결과 리스트에 저장\n- 실행 불가능하면 다시 작업들을 우선순위에 넣고 다음 초로 넘어가서 다시 진행\n- 최초 실행 시간을 모든 작업에서 가장 작은 호출 시간으로 시작하면 무의미한 스킵을 막을 수 있음\n*/\n\nimport java.util.*;\n\nclass Solution {\n    class Task implements Comparable<Task>{\n        int taskNum;\n        int call;\n        int spend;\n        int ta;\n        \n        Task(int t, int c, int s){\n            taskNum = t;\n            call = c;\n            spend = s;\n            ta = 0;\n        }\n        \n        @Override\n        public int compareTo(Task t){\n            if(spend < t.spend){\n                return -1;\n            }\n            else if(spend > t.spend){\n                return 1;\n            }\n            else{\n                if(call < t.call){\n                    return -1;\n                }\n                else if(call > t.call){\n                    return 1;\n                }\n                else{\n                    if(taskNum < t.taskNum){\n                        return -1;\n                    }\n                    else if(taskNum > t.taskNum){\n                        return 1;\n                    }\n                    else{\n                        return 0;\n                    }\n                }\n            }\n        }\n    }\n    \n    public int solution(int[][] jobs) {\n        PriorityQueue<Task> pq = new PriorityQueue<>();\n        List<Task> resultList = new ArrayList<>();\n        \n        for(int i = 0; i < jobs.length; i++){\n            pq.offer(new Task(i, jobs[i][0], jobs[i][1]));\n        }\n        \n        int time = 0;\n        \n        while(!pq.isEmpty()){\n            Task curr = pq.poll();\n            \n            // 만약 curr이 아직 호출되지 않았다면 따로 빼서 다시 큐로\n            List<Task> notYet = new ArrayList<>();\n            while(curr.call > time){\n                // 모든 작업이 현 시점에 호출 없으면 다음 초로\n                if(pq.isEmpty()){\n                    notYet.add(curr);\n                    curr = null;\n                    break;\n                }\n                \n                notYet.add(curr);\n                curr = pq.poll();\n            }\n            for(Task t : notYet){\n                pq.offer(t);\n            }\n            if(curr == null){\n                time++;\n                continue;\n            }\n            \n            time += curr.spend;\n            curr.ta = time - curr.call;\n            resultList.add(curr);\n        }\n        \n        // 반환 시간 평균 계산\n        int answer = 0;\n        for(Task t : resultList){\n            answer += t.ta;\n        }\n        return answer / resultList.size();\n    }\n}","review":{"platform":"programmers","problemId":"42627","author":"junsoo","source":"김준수/week2/디스크 컨트롤러.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["magic-branch","redundant-collection","nonstatic-inner-class","comment-noise"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N² log N + T)","space":"O(N)"},"body":"# 디스크 컨트롤러 (programmers/42627) — junsoo\n\n## 접근\n\n우선순위 큐에 전부 넣고, 소요시간이 짧은 것부터 꺼내되 아직 도착 안 한 작업은\n임시 리스트에 빼뒀다가 되돌려 넣는다. 답은 맞다.\n\n`Task` 에 작업번호·요청시각·소요시간·반환시간을 담아 의미를 이름으로 드러낸 건 좋다.\n\n## 개선점\n\n### 1. (중요) `compareTo` 가 20줄이다 — `magic-branch`\n\n```java\nif(spend < t.spend) return -1;\nelse if(spend > t.spend) return 1;\nelse {\n    if(call < t.call) return -1;\n    else if(call > t.call) return 1;\n    else {\n        if(taskNum < t.taskNum) return -1;\n        else if(taskNum > t.taskNum) return 1;\n        else return 0;\n    }\n}\n```\n\n`Integer.compare` 를 쓰면 3줄이다.\n\n```java\npublic int compareTo(Task t) {\n    if (spend != t.spend) return Integer.compare(spend, t.spend);\n    if (call != t.call) return Integer.compare(call, t.call);\n    return Integer.compare(taskNum, t.taskNum);\n}\n```\n\n같은 회차 안찬웅 코드가 정확히 이 형태다. 로직은 동일한데 길이가 1/6이고,\n\"세 기준을 순서대로 본다\"가 한눈에 읽힌다. 중첩이 깊어질수록 부호를 잘못 넣을 확률도 올라간다.\n\n### 2. (중요) 매번 큐를 헤집어 되넣는다 — `time-complexity`\n\n```java\nList<Task> notYet = new ArrayList<>();\nwhile(curr.call > time){\n    notYet.add(curr);\n    curr = pq.poll();        // 도착한 게 나올 때까지 계속 뽑고\n}\nfor(Task t : notYet){\n    pq.offer(t);             // 뽑았던 걸 전부 되넣는다\n}\n```\n\n한 작업을 고르려고 큐를 최악 O(N)번 뽑고 O(N)번 되넣는다. 전체 `O(N² log N)` 이다.\n제약이 500이라 통과하지만, 되넣기를 없애는 표준형이 있다.\n\n```java\n// 요청시각순 정렬 + 포인터로 \"도착한 것만\" 큐에 투입\nArrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));\nint idx = 0;\nwhile (done < jobs.length) {\n    while (idx < jobs.length && jobs[idx][0] <= time) {\n        pq.offer(new Task(idx, jobs[idx][0], jobs[idx][1]));\n        idx++;\n    }\n    ...\n}\n```\n\n각 작업이 큐를 한 번만 통과해서 `O(N log N)` 이 된다. `notYet` 리스트도 통째로 사라진다.\n이승주·안찬웅 코드가 이 형태다.\n\n### 3. (사소) `resultList` 와 `ta` 필드는 없어도 된다 — `redundant-collection`\n\n```java\ncurr.ta = time - curr.call;\nresultList.add(curr);\n...\nint answer = 0;\nfor(Task t : resultList){ answer += t.ta; }\nreturn answer / resultList.size();\n```\n\n반환 시간을 **필드에 저장해뒀다가 마지막에 다시 순회해서 더한다.**\n합만 필요하므로 그 자리에서 누적하면 리스트도 필드도 필요 없다.\n\n```java\ntotal += time - curr.call;      // 처리하면서 바로 누적\n...\nreturn total / jobs.length;\n```\n\n### 4. (사소) `Task` 는 `static` 중첩 클래스여야 한다 — `nonstatic-inner-class`\n\n```java\nclass Solution {\n    class Task implements Comparable<Task>{   // static 누락\n```\n\n`Task` 는 `Solution` 의 상태를 쓰지 않으므로 `static class Task` 가 맞다.\n안찬웅은 같은 문제에서 `static class Node` 로 선언했다.\n\n### 5. (사소) 주석이 코드와 다르다 — `comment-noise`\n\n```java\n- 최초 실행 시간을 모든 작업에서 가장 작은 호출 시간으로 시작하면 무의미한 스킵을 막을 수 있음\n```\n\n좋은 최적화인데 **실제 코드는 `int time = 0;` 으로 시작한다.** 적용하지 않았다.\n\"할 수 있다\"로 적어둔 메모라면 `TODO` 로 표시하거나, 적용하고 나서 남기는 게 좋다.\n읽는 사람은 주석대로 되어 있다고 믿는다.\n\n## 복잡도\n\n- 시간: `O(N² log N + T)` — 되넣기 때문. 2번을 적용하면 `O(N log N)`.\n- 공간: `O(N)` — 큐 + `notYet` + `resultList`. 3번을 적용하면 큐만 남는다.\n\n## 요약\n\n동작은 맞고 `Task` 로 의미를 드러낸 것도 좋다.\n다만 `compareTo` 20줄과 큐 되넣기가 둘 다 \"표준형을 몰라서\" 생긴 길이다.\n`Integer.compare` 3줄, 그리고 요청시각순 정렬 + 포인터 투입 —\n이 두 가지만 알면 코드가 절반으로 줄고 복잡도도 한 단계 내려간다."}},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/디스크 컨트롤러.java","lines":62,"code":"import java.util.*;\n/*\n    디스크 컨트롤러에서 모든 요청 작업의 반환 시간의 평균 구하기\n\n    1. 우선순위큐 초기화\n    2. 큐가 비어있지 않을 때\n    2.1 소요시간 짧은것, 요청 시각 빠른것, 작업번호 작은 것순으로 정렬\n    2.2 작업 수행 (동시에 작업 수행 불가)\n    3. 큐가 비어있을 때 -> (여기서 조건처리 생각은 못함)\n\n    알고리즘: 우선순위큐\n*/\nclass Solution {\n    static class Node implements Comparable<Node> {\n        int number;\n        int requestTime;\n        int spendTime;\n        \n        Node(int number, int requestTime, int spendTime) {\n            this.number = number;\n            this.requestTime = requestTime;\n            this.spendTime = spendTime;\n        }\n        \n        public int compareTo(Node o) {\n            if(this.spendTime != o.spendTime) {\n                return Integer.compare(this.spendTime, o.spendTime);\n            }\n            if(this.requestTime != o.requestTime) {\n                return Integer.compare(this.requestTime, o.requestTime);\n            }\n            return Integer.compare(this.number, o.number);\n        }\n    }\n    public int solution(int[][] jobs) { // [요청되는 시점, 작업의 소요시간]\n        Arrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));\n      \n        PriorityQueue<Node> pq = new PriorityQueue<>();\n        \n        int idx = 0;\n        int total = 0; // 반환 시간\n        int done = 0; // 하드디스크 작업 완료 건수\n        int time = 0; // 작업 종료 시각\n        while(done < jobs.length) {\n            while(idx < jobs.length && time >= jobs[idx][0]) {\n                pq.add(new Node(idx, jobs[idx][0], jobs[idx][1]));\n                idx++;\n            }\n            if(!pq.isEmpty()) {\n                Node n = pq.poll();\n                time += n.spendTime;\n                total += time - n.requestTime;\n                done++;\n            } else {\n                time++;\n                //time = jobs[idx][0];\n            }\n        }\n        return total / jobs.length;\n    }\n}","review":{"platform":"programmers","problemId":"42627","author":"chanung","source":"안찬웅/week2/디스크 컨트롤러.java","week":"2","compiles":"true","verdict":"good","tags":["redundant-loop","good-readability","good-complexity"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N log N + T)","space":"O(N)"},"body":"# 디스크 컨트롤러 (programmers/42627) — chanung\n\n## 접근\n\n요청 시각순 정렬 + 포인터로 도착한 작업만 큐에 넣고, 소요시간이 짧은 것부터 처리한다.\n이승주와 같은 정석 구조이고 답도 맞다.\n\n`Node` 를 만들어 `compareTo` 에 정렬 기준 세 개를 순서대로 넣은 게 읽기 좋다.\n\n```java\npublic int compareTo(Node o) {\n    if(this.spendTime != o.spendTime) return Integer.compare(this.spendTime, o.spendTime);\n    if(this.requestTime != o.requestTime) return Integer.compare(this.requestTime, o.requestTime);\n    return Integer.compare(this.number, o.number);\n}\n```\n\n`Integer.compare` 를 쓴 것도 정확하다. 같은 회차 `베스트앨범` 에서도 이 형태를 썼는데,\n그때 지적받은 건 비교자가 아니라 그 뒤의 순회 로직이었다. 비교자 작성은 안정적으로 잘한다.\n\n`static class Node` 로 선언한 것도 맞다 — 김준수는 여기서 `static` 을 빠뜨렸다.\n\n## 개선점\n\n### 1. (사소) 유휴 시간을 1씩 올린다 — `redundant-loop`\n\n```java\n} else {\n    time++;\n    //time = jobs[idx][0];      // 주석으로만 남아 있다\n}\n```\n\n큐가 비었다는 건 \"다음 작업이 아직 도착 안 했다\"는 뜻이므로,\n`jobs[idx][0]` 로 **바로 점프**하면 된다. 주석에 이미 정답이 적혀 있다.\n\n이 문제는 요청 시각이 1,000 이하라 최악에도 1,000번 헛도는 정도이고 통과한다.\n다만 시각 범위가 큰 문제(예: 10⁹)에서는 이 한 줄이 시간 초과를 가른다.\n상단 주석에서 스스로 짚은 부분이기도 하다.\n\n> 3. 큐가 비어있을 때 -> (여기서 조건처리 생각은 못함)\n\n주석 처리된 줄을 살리면 된다. `idx < jobs.length` 는 이 분기에 들어온 시점에서 이미 보장된다\n(`done < jobs.length` 이고 큐가 비어 있으므로 아직 안 넣은 작업이 남아 있다).\n\n### 2. (사소) 동점 처리는 없어도 답이 같다\n\n`compareTo` 의 2·3순위(요청시각, 작업번호)는 정확하지만 **이 문제에서는 결과에 영향이 없다.**\n소요시간이 같은 두 작업은 이미 둘 다 큐에 있으므로 순서를 바꿔도 반환 시간 총합이 같다.\n\n- A 먼저: `(t+d-a₀) + (t+2d-b₀)`\n- B 먼저: `(t+d-b₀) + (t+2d-a₀)`\n\n이승주는 소요시간 하나만 비교했고 같은 답이 나온다.\n넣어도 틀리지 않으니 그대로 둬도 되지만, \"왜 필요한가\"를 한 번 따져보면 좋다.\n\n### 3. (사소) `Node.number` 는 동점 처리용으로만 쓰인다\n\n2번대로 동점 처리가 불필요하다면 `number` 필드도 같이 사라진다.\n그러면 `Node` 는 `(requestTime, spendTime)` 두 개짜리가 되어 `int[]` 로도 충분해진다.\n\n## 복잡도\n\n- 시간: `O(N log N + T)` — T는 유휴 구간 길이(최대 1,000). 1번을 고치면 `O(N log N)`.\n- 공간: `O(N)` — 큐. 적정하다.\n\n## 요약\n\n구조와 비교자 모두 정석이다. `static class` 도 정확히 붙였다.\n고칠 건 주석으로 이미 적어둔 한 줄을 살리는 것뿐이다."}},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/디스크컨트롤러.java","lines":50,"code":"package codetest;\n\nimport java.util.PriorityQueue;\n\nclass Solution {\n    \n    public static int answer = 0;\n    \n    public int solution(int[][] jobs) {\n        \n        // 시간에 도달해야 작업을 처리할 수 있다\n            // 가능한 작업 현시간과 동일 또는 이전에 들어온 작업 중 가장 우선순위가 높은 작업\n        \n        PriorityQueue<int[]> pq = new PriorityQueue<>((o1,o2) -> {\n            return (o1[0] == o2[0]) ? Integer.compare(o1[1], o2[1]) : Integer.compare(o1[0], o2[0]);\n        });\n        \n        for (int[] j : jobs){\n            pq.offer(j);\n        }\n        \n        \n        int t = 0;\n        int turnAround = 0;\n        while (!pq.isEmpty()){\n            int[] v = pq.poll();\n            if (v[0] > t) {\n                // 미래에 시작할 수 있는 작업\n                pq.offer(v);\n                // 다시 넣기\n                t = v[0];\n                // 시간 초기화 하기\n            } else if (v[0] < t) {\n                // 묵혀있던 작업\n                // 시간 최신화 시키고 다시 비교\n                pq.offer(new int[]{t, v[1]});\n                turnAround += (t - v[0]);\n            }\n            else {\n                t += v[1];\n                turnAround += (t - v[0]);\n            }\n        }\n        \n        answer = turnAround /jobs.length;\n        \n        \n        return answer;\n    }\n}","review":{"platform":"programmers","problemId":"42627","author":"seongil","source":"이성일/week2/디스크컨트롤러.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["time-complexity","uninitialized-state","dead-code"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N² log N)","space":"O(N)"},"body":"# 디스크 컨트롤러 (programmers/42627) — seongil\n\n## 접근\n\n**네 명 중 유일하게 다른 방식이다.** 정렬용 배열과 대기 큐를 나누지 않고,\n우선순위 큐 하나에 전부 넣은 뒤 요청시각을 현재 시각으로 \"갱신\"해가며 되넣는다.\n\n```java\n} else if (v[0] < t) {                  // 이미 도착해 기다리던 작업\n    pq.offer(new int[]{t, v[1]});       // 요청시각을 t 로 갱신해서 다시 넣고\n    turnAround += (t - v[0]);           // 그동안 기다린 시간을 먼저 적립\n}\n```\n\n대기 시간을 **미리 쪼개서 적립**하고, 요청시각을 현재로 당겨 재삽입한다.\n그러면 큐의 1순위(요청시각)가 같아진 것들끼리 2순위(소요시간)로 겨루게 되어\n결과적으로 \"도착한 것 중 가장 짧은 작업\"이 뽑힌다.\n\n발상이 좋다. 실제로 `[[0,3],[1,9],[2,6]]` 을 넣어보면 정확히 9가 나온다.\n직접 손으로 굴려봤을 때 답이 맞는 것도 확인했다.\n\n## 개선점\n\n### 1. (중요) 되넣기 때문에 작업이 큐를 여러 번 통과한다 — `time-complexity`\n\n각 작업은 시각 `t` 가 바뀔 때마다 한 번씩 \"갱신 후 재삽입\"될 수 있다.\n`t` 가 바뀌는 횟수가 O(N)이므로 큐 연산이 최악 **O(N²)**, 전체 `O(N² log N)` 이다.\n\n제약이 `jobs` 길이 500이라 500² × log ≈ 450만으로 **통과한다.**\n다만 같은 문제를 이승주·안찬웅은 `O(N log N)` 으로 푼다. 차이는 구조 하나다.\n\n```java\n// 요청시각순으로 정렬해두고, 포인터로 \"도착한 것만\" 큐에 넣는다\nArrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));\nint idx = 0;\nwhile (done < jobs.length) {\n    while (idx < jobs.length && jobs[idx][0] <= t) pq.offer(jobs[idx++]);\n    ...\n}\n```\n\n이러면 각 작업이 큐를 딱 한 번 통과한다. 되넣기가 아예 사라지고,\n`v[0] > t` / `v[0] < t` / `v[0] == t` 세 갈래도 없어진다.\n\n지금 방식은 대기 시간을 조각내서 적립하는 만큼 **머릿속으로 검증하기 어렵다.**\n답이 맞는지 확인하려면 예제를 손으로 끝까지 굴려야 하는데, 그건 나중에 이 코드를 볼 사람에게도 마찬가지다.\n\n### 2. (중요) `answer` 가 `static` 이다 — `uninitialized-state`\n\n```java\npublic static int answer = 0;\n...\nanswer = turnAround / jobs.length;\nreturn answer;\n```\n\n`answer` 는 이 메서드 안에서만 쓰이는 값인데 클래스 전체가 공유하는 필드로 잡혀 있다.\n채점기가 같은 JVM에서 여러 번 호출하면 이전 값이 남는다.\n지금은 항상 대입 후 반환해서 안전하지만, 지역 변수로 두면 그 위험 자체가 없다.\n\n```java\nreturn turnAround / jobs.length;   // 필드 불필요\n```\n\n`입국심사` 에서도 `static answer` 로 결과를 넘겼다. 반복되는 패턴이니 한 번에 고쳐두면 좋다.\n\n### 3. (사소) `package codetest;` 가 또 남아 있다 — `dead-code`\n\n`SWEA1249.java`, `다단계칫솔판매.java` 에 이어 세 번째다.\nIDE에서 파일을 만들 때 자동으로 붙는 줄이니, 제출·커밋 전에 지우는 걸 습관으로 만들면 된다.\n\n## 복잡도\n\n- 시간: `O(N² log N)` — 되넣기 때문. 1번을 적용하면 `O(N log N)`.\n- 공간: `O(N)` — 큐. 적정하다.\n\n## 요약\n\n접근이 독창적이고 실제로 맞다. 대기 시간을 조각내 적립한다는 발상은 설명할 가치가 있다.\n다만 되넣기가 복잡도와 가독성을 동시에 깎는다 —\n\"요청시각순 정렬 + 도착한 것만 큐에 투입\" 으로 바꾸면 세 갈래 분기가 통째로 사라진다."}},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/우선순위 컨트롤러.java","lines":33,"code":"import java.util.*;\nclass Solution {\n    public int solution(int[][] jobs) {\n        \n        PriorityQueue<int[]> pq = new PriorityQueue<>((a,b) -> (a[1] - b[1]));\n        int answer = 0;\n        int time = 0; //현재 시간\n        int count = 0; //현재까지 처리한 작업 수\n        int index = 0;\n        \n        Arrays.sort(jobs, (a,b) -> a[0] - b[0]); //들어온 시간대로 정렬\n        \n        while(count < jobs.length){\n            \n            while (index < jobs.length && jobs[index][0] <= time) {\n                pq.offer(jobs[index]);\n                index++;\n}\n            \n            if(!pq.isEmpty()){\n                int[] current = pq.poll(); //가장 짧은 시간 작업 가져옴\n                time += current[1];\n                answer += time - current[0];\n                count += 1;\n            }else{\n                time = jobs[index][0]; //작업큐에 없다면 제일 가까운 시간으로 이동\n            }\n        }\n        return answer / jobs.length;\n        \n    }\n}","review":{"platform":"programmers","problemId":"42627","author":"seungjoo","source":"이승주/week2/우선순위 컨트롤러.java","week":"2","compiles":"true","verdict":"good","tags":["good-complexity","good-readability","naming"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N log N)","space":"O(N)"},"body":"# 디스크 컨트롤러 (programmers/42627) — seungjoo\n\n## 접근\n\n요청 시각순으로 정렬해두고 포인터 하나로 훑으면서, 현재 시각까지 도착한 작업만 우선순위 큐에 넣는다.\n큐에서는 소요시간이 짧은 것부터 꺼낸다. **33줄로 네 명 중 가장 짧고, 복잡도도 가장 좋다.**\n\n```java\nwhile (index < jobs.length && jobs[index][0] <= time) {\n    pq.offer(jobs[index]);   // 도착한 것만 큐로\n    index++;\n}\n```\n\n각 작업이 큐에 딱 한 번 들어갔다 한 번 나온다. 되돌려 넣거나 다시 훑는 일이 없어서 `O(N log N)` 이다.\n\n유휴 처리도 정확하다.\n\n```java\n} else {\n    time = jobs[index][0];   // 큐가 비면 다음 작업 도착 시각으로 점프\n}\n```\n\n1씩 올리지 않고 바로 건너뛴다. 이 문제 제약(요청 시각 ≤ 1000)에서는 차이가 작지만,\n시각 범위가 큰 문제에서는 이 한 줄이 시간 초과를 가른다.\n\n## 잘한 점\n\n### 동점 처리를 굳이 안 넣은 게 맞다\n\n우선순위 큐 비교자가 소요시간 하나뿐이다.\n\n```java\nPriorityQueue<int[]> pq = new PriorityQueue<>((a,b) -> (a[1] - b[1]));\n```\n\n소요시간이 같은 두 작업의 순서를 바꿔도 **반환 시간 총합은 변하지 않는다.**\n둘 다 이미 큐에 있으므로, 시작 시각 `t` 기준으로\n\n- A 먼저: `(t+d-a₀) + (t+2d-b₀)`\n- B 먼저: `(t+d-b₀) + (t+2d-a₀)`\n\n두 합이 같다. 다른 두 명은 요청시각·작업번호까지 비교자에 넣었는데, 없어도 답이 같다.\n\n## 개선점\n\n### 1. (사소) 파일명이 문제 이름과 다르다 — `naming`\n\n`우선순위 컨트롤러.java` 인데 문제는 **디스크 컨트롤러**다.\n사이트는 `data/problems.json` 의 alias 로 흡수해서 정상 인식하지만,\n저장소를 직접 훑는 사람에게는 다른 문제로 보인다. 다음부터는 문제 이름 그대로 두는 게 좋다.\n\n### 2. (사소) 비교자를 뺄셈으로 썼다\n\n```java\n(a,b) -> (a[1] - b[1])\nArrays.sort(jobs, (a,b) -> a[0] - b[0]);\n```\n\n이 문제는 값이 1,000 이하라 **터지지 않는다.** 다만 `SWEA1249` 리뷰에서도 같은 지적이 있었으니\n습관을 `Integer.compare(a[1], b[1])` 로 바꿔두면 값이 큰 문제에서 사고를 막을 수 있다.\n\n### 3. (사소) 안쪽 `while` 의 닫는 괄호가 열 0에 있다\n\n```java\n            while (index < jobs.length && jobs[index][0] <= time) {\n                pq.offer(jobs[index]);\n                index++;\n}\n```\n\n동작에는 영향이 없지만 블록 구조가 눈으로 안 잡힌다. IDE 자동 정렬(`Ctrl+Alt+L`)이면 끝난다.\n\n## 복잡도\n\n- 시간: `O(N log N)` — 정렬 + 각 작업이 큐를 한 번씩 통과. 네 명 중 유일하게 이 복잡도다.\n- 공간: `O(N)` — 큐. 적정하다.\n\n## 요약\n\n교과서적인 형태다. 각 작업이 큐를 한 번만 통과하고, 유휴 시간은 점프로 건너뛴다.\n지적할 게 파일명과 뺄셈 비교자뿐이고 둘 다 로직 밖의 문제다."}}],"teamFeedback":null},{"key":"programmers/42861","platform":"programmers","problemId":"42861","title":"섬 연결하기","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42861","weeks":[4],"entries":[{"author":"junsoo","authorName":"김준수","week":4,"variant":null,"source":"김준수/week4/섬 연결하기.java","lines":79,"code":"/*\n전략\n- MST = 최소 비용으로 모든 섬이 다 연결되게, 무방향 가중치 그래프\n- 유니온 파인드 구현, 크루스칼 구현 템플릿 코드를 아직 못외움\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static int[] parent;\n    \n    class Edge implements Comparable<Edge>{\n        int u;\n        int v;\n        int cost;\n        \n        Edge(int u, int v, int cost){\n            this.u = u;\n            this.v = v;\n            this.cost = cost;\n        }\n        \n        @Override\n        public int compareTo(Edge e){\n            return this.cost - e.cost;\n        }\n    }\n    \n    public int solution(int n, int[][] costs) {\n        // Makeset 초기화\n        parent = new int[n + 1];\n        for(int i = 1; i <= n; i++){\n            parent[i] = i;\n        }\n        \n        // 간선 초기화 및 정렬\n        List<Edge> edges = new ArrayList<>();\n        for(int[] c : costs){\n            edges.add(new Edge(c[0], c[1], c[2]));\n        }\n        Collections.sort(edges);\n\n        int totalCost = 0; // 최소 비용 저장\n        int edgeCnt = 0; // 간선 개수 저장(종료 조건)\n        \n        // 크루스칼\n        for(Edge e : edges){\n            // 두 정점이 같은 그래프가 아니면 합치고 비용, 간선 수 갱신\n            if(find(e.u) != find(e.v)){\n                union(e.u, e.v);\n                totalCost += e.cost;\n                edgeCnt++;\n            }\n            \n            // 최소 연결하려면 간선 개수가 n-1개여야 함\n            if(edgeCnt == n - 1){\n                break;\n            }\n        }\n        \n        return totalCost;\n    }\n    \n    public int find(int x){\n        if(parent[x] == x){\n            return x;\n        }\n        return parent[x] = find(parent[x]);\n    }\n    \n    public void union(int x, int y){\n        x = find(x);\n        y = find(y);\n        \n        if(x != y){\n            parent[x] = y;\n        }\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/42884","platform":"programmers","problemId":"42884","title":"단속카메라","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42884","weeks":[3],"entries":[{"author":"seongil","authorName":"이성일","week":3,"variant":null,"source":"이성일/week3/연습/단속카메라.java","lines":31,"code":"import java.util.Arrays;\n\nclass Solution {\n    public int solution(int[][] routes) {\n        // 1. 정렬\n        Arrays.sort(routes,\n                (o1, o2) -> (o1[0] == o2[0] ? Integer.compare(o1[1], o2[1]) : Integer.compare(o1[0], o2[0])));\n\n        // 1.1 정렬 기준은 출발지점, 같으면 도착지점\n        // 2. 설치 구역 설정 후 루프 돌면서 현재 설치 구역 도착지점과 출발지점 비교\n        int[] area = Arrays.copyOf(routes[0], 2);\n        int camera = 1;\n        for (int[] route : routes) {\n            // 2.2 비교 후 같거나 작으면 구역을 현재 차량 출발지점과 기존 차량 도착지점으로 변경\n            // 2.3 더 크면, 새 구역으로 현재 차량의 경로를 설치\n            // 새 구역이 하나 생길 때마다 설치 카메라 개수 + 1\n            if (route[0] <= area[1]) {\n                area[0] = route[0];\n                area[1] = Math.min(route[1], area[1]);\n            } else {\n                camera++;\n                area[0] = route[0];\n                area[1] = route[1];\n            }\n\n        }\n\n        return camera;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/42892","platform":"programmers","problemId":"42892","title":"길 찾기 게임","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42892","weeks":[3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/길 찾기 게임.java","lines":146,"code":"/*\n전략\n- 이진 탐색 트리 구현\n    - 각 노드들을 y 기준 내림차순으로 정렬하고 이진 탐색 트리에 하나씩 넣기\n    - 새 노드를 넣었을 때 현재 노드의 x 값과 비교해서 왼쪽 오른쪽을 분류\n        - 루트 노드부터 시작\n    - 해당 방향의 자식이 비었으면 넣고, 안 비었으면 다음 자식으로 이동해서 다시 x값 비교\n- dfsPre : 이진트리를 전위순회 ⇒ 루트 → 왼쪽 → 오른쪽 순으로 결과 리스트에 추가\n    - 전위순회는 현재 노드를 먼저 결과에 추가하고 왼쪽 호출 → 오른쪽 호출\n- dfsPost : 이진트리를 후위순회 ⇒ 왼쪽 → 오른쪽 → 루트 순으로 결과 리스트에 추가\n    - 후위순회는 왼쪽 호출 → 오른쪽 호출 한 후 현재 노드 추가\n\n시행착오\n- 이진 탐색 트리 문제임을 늦게 파악하고 순수 그래프로 구현 시도\n  중간에 그래프에 노드 추가할 때 조건 탐색 과정이 너무 복잡해서 포기하고 이진 탐색 트리로 선회\n- 이진 탐색 트리 구현 템플릿이 있을 것 같은데, 생각나는 대로 구현해서 코드가 더러울 듯\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static Node[] nodes;\n    static List<Integer> preList;\n    static List<Integer> postList;\n    \n    class Node {\n        int x;\n        int y;\n        int left;\n        int right;\n        int value;\n        \n        Node(int x, int y, int value){\n            this.x = x;\n            this.y = y;\n            this.value = value;\n            left = -1;\n            right = -1;\n        }\n    }\n    \n    class BST{\n        Node root;\n        int size;\n        \n        BST(Node root){\n            this.root = root;\n            size = 1;\n        }\n        \n        public void add(Node child){\n            size++;\n            Node curr = root;\n            \n            while(true){\n                // child가 왼쪽일지 오른쪽일지\n                if(child.x < curr.x){\n                    // -1이면 왼쪽 자식에 삽입 후 종료 \n                    if(curr.left == -1){\n                        curr.left = child.value;\n                        break;  \n                    }\n                    // -1이 아니면 다음 왼쪽 자식으로\n                    else{\n                        curr = nodes[curr.left];\n                    }\n                }\n                else{\n                    // -1이면 오른쪽 자식에 삽입 후 종료\n                    if(curr.right == -1){\n                        curr.right = child.value;\n                        break;\n                    }\n                    // -1이 아니면 다음 오른쪽 자식으로\n                    else{\n                        curr = nodes[curr.right]; \n                    }\n                }\n            }\n        }\n    }\n    \n    public int[][] solution(int[][] nodeinfo) {\n        preList = new ArrayList<>();\n        postList = new ArrayList<>();\n        \n        nodes = new Node[nodeinfo.length];\n        for(int i = 0; i < nodeinfo.length; i++){\n            nodes[i] = new Node(nodeinfo[i][0], nodeinfo[i][1], i);\n        }\n        // y를 기준으로 내림차순 정렬\n        Node[] sortedNodes = Arrays.copyOf(nodes, nodes.length);\n        \n        Arrays.sort(sortedNodes, (a, b) -> b.y - a.y);\n        \n        // 루트 노드 삽입\n        BST bst = new BST(sortedNodes[0]);\n        // 정렬 순서대로 노드 삽입\n        for(int i = 1; i < sortedNodes.length; i++){\n            bst.add(sortedNodes[i]);\n        }\n        \n        dfsPre(sortedNodes[0]);\n        dfsPost(sortedNodes[0]);\n        \n        int[][] answer = new int[2][nodes.length];\n        for(int i = 0; i < preList.size(); i++){\n            answer[0][i] = preList.get(i);\n            answer[1][i] = postList.get(i);\n        }\n        \n        return answer;\n    }\n    \n    private void dfsPre(Node curr){\n        if(preList.size() == nodes.length){\n            return;\n        }\n        \n        preList.add(curr.value + 1);\n        \n        if(curr.left != -1){\n            dfsPre(nodes[curr.left]);\n        }\n        \n        if(curr.right != -1){\n            dfsPre(nodes[curr.right]);\n        }\n    }\n    \n    private void dfsPost(Node curr){\n        if(postList.size() == nodes.length){\n            return;\n        }\n        \n        if(curr.left != -1){\n            dfsPost(nodes[curr.left]);\n        }\n        \n        if(curr.right != -1){\n            dfsPost(nodes[curr.right]);\n        }\n        \n        postList.add(curr.value + 1);\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/42895","platform":"programmers","problemId":"42895","title":"N으로 표현","url":"https://school.programmers.co.kr/learn/courses/30/lessons/42895","weeks":[3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/N으로 표현.java","lines":74,"code":"/*\n전략\n- DP\n- dp[i] : i를 만드는데 필요한 최소한의 N 사용 횟수\n    - dp[N], dp[NN], dp[NNN], dp[NNNN], dp[NNNNN]으로 시작\n- BFS처럼 가능한 숫자들을 큐에 넣고, 하나씩 꺼내서 다음 가능한 경우의 수들을 만들어서 큐에 넣음\n    - N, NN, NNN, NNNN, NNNNN 을 사칙연산 가능. 이 경우 N의 개수만큼 count 추가\n    - 1, 11, 111, 1111, 11111을 사칙연산 가능. 이 경우 1의 개수 + 1만큼 count 추가\n        - N / N = 1 ⇒ count : 2\n        - NN / N = 11 ⇒ count : 3\n    - 총 10개의 숫자를 사칙연산하므로 하나의 숫자 당 40개의 숫자를 추가 가능\n*/\n\nimport java.util.*;\n\nclass Solution {    \n    public int solution(int N, int number) {\n        int[] dp = new int[32001];\n        for(int i = 0; i < 32001; i++){\n            dp[i] = 9; // count의 최대치 8\n        }\n        \n        int NN = Integer.parseInt(String.format(\"%d%d\", N, N));\n        int NNN = Integer.parseInt(String.format(\"%d%d%d\", N, N, N));\n        int NNNN = Integer.parseInt(String.format(\"%d%d%d%d\", N, N, N, N));\n        int NNNNN = Integer.parseInt(String.format(\"%d%d%d%d\", N, N, N, N));\n        int[] NList = new int[]{N, NN, NNN, NNNN, NNNNN};\n        int[] oneList = new int[]{1, 11, 111, 1111, 11111};\n            \n        Queue<int[]> queue = new ArrayDeque<>();\n        for(int num : NList){\n            // (int) Math.log10(num) + 1 : num의 자릿수 계산 방법\n            queue.offer(new int[]{num, (int) Math.log10(num) + 1});\n        }\n        \n        \n        while(!queue.isEmpty()){\n            int[] curr = queue.poll();\n            int num = curr[0];\n            int count = curr[1];\n            \n            // 스킵 조건\n            if(count > 8 || num > 32000 || num <= 0){\n                continue;\n            }\n            \n            // 더 작은 쪽으로 갱신\n            dp[num] = Math.min(dp[num], count);\n            \n            // N 연산\n            for(int next : NList){\n                queue.offer(new int[]{num + next, count + (int) Math.log10(next) + 1});\n                queue.offer(new int[]{num - next, count + (int) Math.log10(next) + 1});\n                queue.offer(new int[]{num * next, count + (int) Math.log10(next) + 1});\n                queue.offer(new int[]{num / next, count + (int) Math.log10(next) + 1});\n            }\n            \n            // 1 연산\n            for(int next : oneList){\n                queue.offer(new int[]{num + next, count + (int) Math.log10(next) + 2});\n                queue.offer(new int[]{num - next, count + (int) Math.log10(next) + 2});\n                queue.offer(new int[]{num * next, count + (int) Math.log10(next) + 2});\n                queue.offer(new int[]{num / next, count + (int) Math.log10(next) + 2});\n            }\n        }\n        \n        if(dp[number] == 9){\n            return -1;\n        }\n        else{\n            return dp[number];\n        }\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/N으로 표현.java","lines":42,"code":"import java.util.*;\n\nclass Solution {\n    public int solution(int N, int number) {\n        if (N == number) return 1;\n\n        List<Set<Integer>> dp = new ArrayList<>();\n        for (int i=0; i<=8; i++) {\n            dp.add(new HashSet<>());\n        }\n\n        dp.get(1).add(N);\n\n        for (int i=2; i<=8; i++) {\n            StringBuilder sb = new StringBuilder().append(N);\n            for (int j = 1; j < i; j++) {\n                sb.append(N);\n            }\n            dp.get(i).add(Integer.parseInt(sb.toString()));\n \n            for(int j = 1; j < i; j++) {\n                int k = i - j;\n                for(int num1 : dp.get(j)) {\n                    for(int num2 : dp.get(k)) {\n                        dp.get(i).add(num1 + num2);\n                        dp.get(i).add(num1 - num2);\n                        dp.get(i).add(num1 * num2);\n                        if (num2 != 0) {\n                            dp.get(i).add(num1 / num2);\n                        }\n                    }\n                }\n            }\n \n            if (dp.get(i).contains(number)) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":null,"source":"이성일/week3/N으로표현.java","lines":55,"code":"import java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n\n    static Set<Integer>[] dp = new HashSet[9];\n\n    static void amplify(int left, int right, int len, int number) {\n\n        for (int n : dp[left]) {\n            for (int m : dp[right]) {\n                int[] ops = { n + m, Math.abs(n - m), n * m, (Math.max(n, m) / Math.min(n, m)) };\n                for (int opResult : ops) {\n                    if (opResult > 32000 || opResult <= 0)\n                        continue;\n                    dp[len].add(opResult);\n                }\n            }\n        }\n\n    }\n\n    public int solution(int N, int number) {\n        int answer = -1;\n        for (int i = 0; i < dp.length; i++) {\n            dp[i] = new HashSet<>();\n        }\n        dp[1].add(N);\n\n        int len = 1;\n        while (len < 9) {\n            int left = 1, right = len - 1;\n\n            int concatNum = 0;\n            for (int i = 0; i < len; i++) {\n                concatNum += N * (int) (Math.pow(10, i));\n            }\n            dp[len].add(concatNum);\n\n            while (left <= right) {\n                amplify(left, right, len, number);\n                left++;\n                right--;\n            }\n\n            if (dp[len].contains(number)) {\n                return len;\n            }\n            len++;\n        }\n        // 2.3 새로운 수가 number이면 answer값 저장 및 종료\n        return answer;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":"failed","source":"이성일/week3/N으로표현FailVersion.java","lines":79,"code":"\nimport java.util.Arrays;\nimport java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n\n    // 1. N의 개수에 따라 만들 수 있는 수 리스트 관리\n    // 1.1 N의 개수는 최대 8\n    static Set<Integer>[] list = new HashSet[9];\n    // 1.2 number 사이즈의 N의 개수를 저장하는 배열 생성\n    static int[] nums = new int[32001];\n\n    static boolean amplify(int left, int right, int len, int number) {\n\n        for (int n : list[left]) {\n            for (int m : list[right]) {\n                int[] ops = { n + m, Math.abs(n - m), n * m, (Math.max(n, m) / Math.min(n, m)) };\n                for (int opResult : ops) {\n                    if (opResult > 32000 || opResult <= 0)\n                        continue;\n                    if (opResult == number) {\n                        nums[number] = left + right;\n                        return true;\n                    }\n                    if (nums[opResult] < left + right)\n                        continue;\n                    nums[opResult] = left + right;\n                    list[len].add(opResult);\n                }\n            }\n        }\n\n        return false;\n    }\n\n    public int solution(int N, int number) {\n        int answer = -1;\n        for (int i = 0; i < list.length; i++) {\n            list[i] = new HashSet<>();\n        }\n        list[1].add(N);\n        Arrays.fill(nums, Integer.MAX_VALUE);\n        nums[N] = 1;\n        if (N == number)\n            return 1;\n        // 2. 리스트 빌드\n        // 2.1 2개부터 시작, 이전 개수들의 조합으로 리스트 관리\n        int len = 2;\n        while (len < 9) {\n            int left = 1, right = len - 1;\n            boolean flag = false;\n            int concatNum = 0;\n            for (int i = 0; i < len; i++) {\n                concatNum += N * (int) (Math.pow(10, i));\n            }\n            list[len].add(concatNum);\n            if (concatNum == number)\n                return len;\n            // 2.2 이중루프를 돌며 이전 개수 조합간의 새로운 수 생성\n            // 2.2.1 더하기 빼기 곱하기 나누기 숫자 이어붙이기는 마지막에\n            while (left <= right) {\n                if (amplify(left, right, len, number)) {\n                    flag = true;\n                    break;\n                }\n                left++;\n                right--;\n            }\n            if (flag) {\n                return len;\n            }\n            len++;\n        }\n        // 2.3 새로운 수가 number이면 answer값 저장 및 종료\n        return answer;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":3,"variant":null,"source":"이승주/week3/N으로 표현.java","lines":46,"code":"import java.util.*;\n\nclass Solution {\n    \n    static int answer = Integer.MAX_VALUE;\n    static int N;\n    static int target;\n\n    public int solution(int N, int number) {\n        this.N = N;\n        this.target = number;\n\n        dfs(0, 0);\n\n        return answer == Integer.MAX_VALUE ? -1 : answer;\n    }\n\nstatic void dfs(int cnt, int value) {\n    \n\n        if (value == target) {\n          \n            answer = Math.min(answer, cnt);\n            return;\n        }\n\n        int num = 0;\n\n        for (int i = 1; cnt + i <= 8; i++) {\n            \n            num = num * 10 + N;\n\n            dfs(cnt + i, value + num);\n            \n            dfs(cnt + i, value - num);\n            \n            dfs(cnt + i, value * num);\n\n            if (num != 0) {\n                dfs(cnt + i, value / num);\n            }\n            \n        }\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/43164","platform":"programmers","problemId":"43164","title":"여행경로","url":"https://school.programmers.co.kr/learn/courses/30/lessons/43164","weeks":[4],"entries":[{"author":"junsoo","authorName":"김준수","week":4,"variant":null,"source":"김준수/week4/여행 경로.java","lines":92,"code":"/*\n전략\n- 백트래킹\n- 도시 이름을 담은 String 배열 생성. 해당 배열의 인덱스로 도시 구분(String 비교는 너무 비용이 크니)\n- 위 배열을 활용해 tickets 배열을 String에서 int로 바꿔서 배열 생성. ⇒ List<List<int[]> graph 생성\n    - graph는 출발지 → [도착지, 사용가능여부(0/1] 로 저장\n    - graph 생성 완료 후 각 요소를 정렬해줘야 알파벳 순서 return 가능\n- ICN의 인덱스 찾아서 dfs 시작\n    - 경로 리스트 List<Integer>를 파라미터로 받아서 관리\n- 경로 리스트를 int에서 String으로 변환해서 반환\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static List<String> cities;\n    static int[][] ticket;\n    static List<List<int[]>> graph;\n    static List<Integer> result;\n    \n    public String[] solution(String[][] tickets) {\n        result = null;\n        cities = new ArrayList<>();\n        for(String[] t : tickets){\n            if(!cities.contains(t[0])){\n                cities.add(t[0]);\n            }\n            if(!cities.contains(t[1])){\n                cities.add(t[1]);\n            }\n        }\n        Collections.sort(cities);\n    \n        // tickets를 int로 변환한 ticket\n        ticket = new int[tickets.length][2];\n        for(int i = 0; i < tickets.length; i++){\n            ticket[i][0] = cities.indexOf(tickets[i][0]);\n            ticket[i][1] = cities.indexOf(tickets[i][1]);\n        }\n        \n        graph = new ArrayList<>();\n        for(int i = 0; i < cities.size(); i++){\n            graph.add(new ArrayList<>());\n        }\n        for(int[] t : ticket){\n            // 출발지 -> [도착지, 사용가능여부(0/1)]\n            graph.get(t[0]).add(new int[]{t[1], 1});\n        }\n        // 그래프 정렬(알파벳 순으로 먼저 가기 위해)\n        for(int i = 0; i < graph.size(); i++){\n            graph.get(i).sort((a, b) -> a[0] - b[0]);\n        }\n        \n        dfs(0, cities.indexOf(\"ICN\"), new ArrayList<>(Arrays.asList(cities.indexOf(\"ICN\"))));\n        \n        String[] answer = new String[result.size()];\n        for(int i = 0; i < result.size(); i++){\n            answer[i] = cities.get(result.get(i));\n        }\n        \n        return answer;\n    }\n    \n    private void dfs(int depth, int curr, List<Integer> course){\n        // 종료 조건 : 모든 티켓 다 썼을 때\n        if(depth == ticket.length){\n            if(result == null){\n                // 깊은 복사\n                result = new ArrayList<>();\n                for(int c : course){\n                    result.add(c);\n                }\n            }\n        }\n        \n        for(int i = 0; i < graph.get(curr).size(); i++){\n            int[] next = graph.get(curr).get(i);\n            \n            if(next[1] != 1){\n                continue;\n            }\n            \n            next[1] = 0;\n            course.add(next[0]);\n            \n            dfs(depth + 1, next[0], course);\n            \n            next[1] = 1;\n            course.remove(course.size() - 1);\n        }\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":4,"variant":null,"source":"안찬웅/week4/여행경로.java","lines":43,"code":"import java.util.*;\n/*\n    ICN에서 출발해서 여행경로 짜기\n    \n    알고리즘: DFS 조합 백트래킹\n    \n    ICN에서 출발해서 tickets[0][1]로 이동 -> tickets[i][0]로 계속 이동하면서 record 배열에 여행경로 저장\n*/\nclass Solution {\n    static String[] order;\n    static boolean[] vis;\n    static String[] res;\n    public String[] solution(String[][] tickets) {\n        order = new String[tickets.length+1];\n        vis = new boolean[tickets.length];\n        \n        Arrays.sort(tickets, (a, b) -> a[1].compareTo(b[1]));\n\n        order[0] = \"ICN\";\n        dfs(\"ICN\", tickets, 1);\n        \n        return res;\n    }\n    static void dfs(String start, String[][] tickets, int depth) {\n        if(depth == tickets.length + 1) {\n            res = order;\n            return;\n        }\n        \n        for(int i=0; i<tickets.length; i++) {\n            if(res != null) return;\n            if(!vis[i]) {\n                vis[i] = true;\n                if(tickets[i][0].equals(start)) {\n                    order[depth] = tickets[i][1];\n                    dfs(tickets[i][1], tickets, depth+1);\n                }\n                vis[i] = false;\n            }\n        }\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/43238","platform":"programmers","problemId":"43238","title":"입국심사","url":"https://school.programmers.co.kr/learn/courses/30/lessons/43238","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/입국심사.java","lines":65,"code":"/*\n전략\n- 매개변수 탐색\n- 시간이 T, 각 심사관의 시간이 a, b일때 각 심사관이 해당 시간에 담당할 수 있는 사람 수는 N / a, N / b\n- 시간을 매개변수로 두고 탐색해서, 특정 시간 T일 때 각 심사관이 담당할 수 있는 사람의 수가 n 이상이면 입국심사 가능 = isValid\n- 입국심사 가능이면 더 작은 시간을 시도, 입국심사 불가능이면 더 큰 시간을 시도\n- 시간이 가장 작은 경계를 찾기 위해 start ≤ end일때까지 반복 후 start가 결과값\n\n시행착오\n- end의 최적 값은 가장 오래 걸리는 심사관이 모든 사람을 담당하는 것인데, 그 과정에서 times 배열이 int인데 long인 end에 저장하려고 하니 오버플로우가 발생했음. 명시적 형변환을 추가해서 해결\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static int n;\n    static int[] times;\n    \n    public long solution(int n, int[] times) {\n        this.n = n;\n        this.times = times;\n        long answer = 0;\n        \n        Arrays.sort(times);\n        long start = 0;\n        // times가 int[] 형이라 명시적 형변환 하지 않으면 오버플로우 발생 \n        // 가능한 최대 시간 = 가장 오래 걸리는 심사관이 n명을 모두 담당\n        long end = (long) times[times.length - 1] * n;\n        long mid = 0;\n        \n        while(start <= end){\n            mid = (start + end) / 2;\n            \n            // 입국 심사가 가능하면 더 작은 시간을 시도\n            if(isValid(mid)){\n                end = mid - 1;\n            }\n            // 입국 심사가 불가능하면 더 큰 시간을 시도\n            else{\n                start = mid + 1;\n            }\n        }\n        \n        return start;\n    }\n    \n\n    private boolean isValid(long time){\n        long result = 0;\n\t\t\t\t\n\t\t\t\t// 각 심사관이 time 내에 담당할 수 있는 사람의 수를 더함        \n        for(int t : times){\n            result += time / t;\n        }\n        \n        // 전체 심사관이 담당할 수 있는 사람 수가 n 이상이면 통과\n        if(result >= n){\n            return true;\n        }\n        else{\n            return false;\n        }\n    }\n}","review":{"platform":"programmers","problemId":"43238","author":"junsoo","source":"김준수/week2/입국심사.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["overflow","uninitialized-state","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(M log(max·n))","space":"O(1)"},"body":"# 입국심사 (programmers/43238) — junsoo\n\n## 접근\n\n시간을 매개변수로 둔 파라메트릭 서치. 판정을 `isValid(time)` 로 분리해서\n\"이 시간이면 되는가\"와 \"구간을 어떻게 좁히는가\"가 코드에서 따로 읽힌다. 좋은 분리다.\n\n상단 주석의 시행착오 기록도 정확하다.\n\n> end의 최적 값은 가장 오래 걸리는 심사관이 모든 사람을 담당하는 것인데,\n> times 배열이 int인데 long인 end에 저장하려고 하니 오버플로우가 발생했음\n\n`(long) times[...] * n` 캐스팅을 스스로 찾아낸 부분이다. **다만 오버플로는 여기만이 아니다.**\n\n## 개선점\n\n### 1. (중요) 캐스팅으로 막은 건 상한 계산뿐, 누적 합은 그대로다 — `overflow`\n\n```java\nlong end = (long) times[times.length - 1] * n;   // 여기는 막았다\n...\nprivate boolean isValid(long time){\n    long result = 0;\n    for(int t : times){\n        result += time / t;                       // 여기는 안 막혔다\n    }\n```\n\n제약은 `n ≤ 10⁹`, `times.length ≤ 10⁵`, `times[i] ≤ 10⁹` 다.\n\n| | 값 |\n|---|---|\n| `end = max·n` | `10¹⁸` |\n| 첫 `mid` | 약 `5 × 10¹⁷` |\n| 소요시간 1분 심사관 10만 명이면 `result` | `5 × 10²²` |\n| `long` 최대 | `9.2 × 10¹⁸` |\n\n`result` 가 음수로 뒤집히면 `result >= n` 이 거짓이 되어 탐색이 반대 방향으로 간다.\n예외 없이 답만 틀리므로 디버깅이 어렵다.\n\n주석에서 짚은 것과 **같은 성격의 문제이고 같은 배열에서 나온다.**\n\"곱셈만 조심하면 된다\"가 아니라 \"누적도 조심해야 한다\"까지 확장하면 된다.\n\n```java\nfor(int t : times){\n    result += time / t;\n    if (result >= n) return true;   // 필요한 만큼만 세고 멈춘다\n}\nreturn false;\n```\n\n이러면 `result` 가 `n` 을 크게 넘길 일이 없다.\n\n### 2. (중요) `n` 과 `times` 를 `static` 으로 들고 있다 — `uninitialized-state`\n\n```java\nstatic int n;\nstatic int[] times;\n\npublic long solution(int n, int[] times) {\n    this.n = n;              // static 필드를 this 로 대입\n    this.times = times;\n```\n\n`static` 필드를 `this.` 로 대입하고 있다. 컴파일은 되지만 \"인스턴스마다 따로\"라는 오해를 부른다.\n실제로는 클래스 전체가 공유하므로, 채점기가 같은 JVM에서 여러 번 호출하면\n초기화를 한 번만 빠뜨려도 **이전 테스트케이스 값이 남는다.**\n\n`isValid` 가 쓰는 건 `n` 과 `times` 뿐이니 인자로 넘기면 필드 자체가 필요 없다.\n\n```java\nprivate boolean isValid(long time, int n, int[] times) { ... }\n```\n\n### 3. (사소) `if/else` 로 `boolean` 을 만들 필요는 없다\n\n```java\nif(result >= n){\n    return true;\n}\nelse{\n    return false;\n}\n```\n\n`return result >= n;` 한 줄이면 같다.\n\n### 4. (사소) `isValid` 안에 탭과 스페이스가 섞여 있다\n\n```java\n        long result = 0;\n\t\t\t\t\n\t\t\t\t// 각 심사관이 time 내에 담당할 수 있는 사람의 수를 더함        \n```\n\n주석 줄이 탭으로 들여쓰기돼 있어 에디터 설정에 따라 위치가 흔들린다.\nIDE의 \"탭을 스페이스로\" 설정을 켜두면 자동으로 정리된다.\n\n## 복잡도\n\n- 시간: `O(M log(max·n))` — M은 심사관 수. 상한을 `times[0] * n` 으로 좁히면 `log` 안이 줄어든다\n  (가장 빠른 심사관 혼자 n명을 처리하는 시간이므로 상한으로 유효하다).\n- 공간: `O(1)` — 적정하다.\n\n## 요약\n\n`isValid` 분리와 상한 캐스팅 모두 정확하고, 시행착오를 기록해둔 것도 좋다.\n정작 같은 종류의 오버플로가 누적 합에 남아 있는 게 아쉽다 — `break` 한 줄이면 막힌다."}},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/입국심사.java","lines":31,"code":"import java.util.*;\n\nclass Solution {\n    public long solution(int n, int[] times) {\n        \n        Arrays.sort(times);\n        \n        long time = 1;\n        long high = (long) times[times.length-1] * n;\n        long low = 0;\n        long sum;\n        \n        while(low <= high) {\n            long mid = (low + high) / 2;\n            sum = 0;\n            \n            for(int x : times) {\n                sum += mid / x;\n            }\n            \n            if(sum >= n) {\n                high = mid - 1;\n                time = mid;\n            } else {\n                low = mid + 1;\n            }\n        }\n        return time;\n    }\n}","review":{"platform":"programmers","problemId":"43238","author":"chanung","source":"안찬웅/week2/입국심사.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["overflow","good-readability","good-complexity"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(M log(max·n))","space":"O(1)"},"body":"# 입국심사 (programmers/43238) — chanung\n\n## 접근\n\n시간을 매개변수로 둔 파라메트릭 서치. **31줄로 네 명 중 가장 짧다.**\n군더더기 없이 이분탐색 한 덩어리로 끝냈고, 읽는 데 걸림이 없다.\n\n```java\nif(sum >= n) {\n    high = mid - 1;\n    time = mid;      // 정답 후보 갱신\n} else {\n    low = mid + 1;\n}\n```\n\n\"가능하면 답으로 찍어두고 더 줄여본다\"는 파라메트릭 서치의 표준형이다.\n`(long)` 캐스팅으로 상한 계산의 오버플로를 막은 것도 정확하다.\n\n## 개선점\n\n### 1. (중요) 누적 합이 `long` 을 넘길 수 있다 — `overflow`\n\n```java\nlong high = (long) times[times.length-1] * n;   // 가장 느린 심사관 기준\n...\nfor(int x : times) {\n    sum += mid / x;                              // 끝까지 다 더한다\n}\n```\n\n문제 제약은 `n ≤ 10⁹`, `times.length ≤ 10⁵`, `times[i] ≤ 10⁹` 다.\n이 조합이 동시에 들어오면 터진다.\n\n| | 값 |\n|---|---|\n| `high = max·n` | `10⁹ × 10⁹ = 10¹⁸` |\n| 첫 `mid` | 약 `5 × 10¹⁷` |\n| 소요시간 1분 심사관이 10만 명이면 `sum` | `10⁵ × 5×10¹⁷ = 5 × 10²²` |\n| `long` 최대 | `9.2 × 10¹⁸` |\n\n`sum` 이 음수로 뒤집히면 `sum >= n` 이 거짓이 되어 탐색이 반대로 간다.\n예외가 안 나고 답만 조용히 틀리는 종류다.\n\n**지금 채점을 통과한 건 테스트 데이터가 이 조합까지 안 갔기 때문**이지 코드가 안전해서가 아니다.\n\n고치는 방법은 두 가지고, 둘 다 한 줄이다.\n\n```java\n// (a) 필요한 만큼만 세고 멈춘다\nfor(int x : times) {\n    sum += mid / x;\n    if (sum >= n) break;\n}\n\n// (b) 상한을 가장 '빠른' 심사관 기준으로 좁힌다\nlong high = (long) times[0] * n;   // 정렬 후 times[0] 이 최소\n```\n\n(b) 가 유효한 이유는 시간 `min·n` 이면 가장 빠른 심사관 혼자 `n` 명을 처리하기 때문이다.\n상한으로 성립하면서 구간이 `max/min` 배 좁아지고, 각 항이 `n` 이하로 눌려 오버플로도 사라진다.\n\n같은 회차 이승주가 (a)와 (b)를 둘 다 썼다. 비교해보면 좋다.\n\n### 2. (사소) `time` 대신 `low` 를 반환하면 변수 하나가 준다\n\n```java\nlong time = 1;          // 초기값 1은 근거가 없다\n...\nif(sum >= n) { high = mid - 1; time = mid; }\n...\nreturn time;\n```\n\n이분탐색이 끝나면 `low` 가 곧 \"조건을 만족하는 가장 작은 값\"이다.\n`time` 을 따로 들고 다니지 않아도 `return low;` 로 끝난다.\n\n지금은 `high` 가 항상 유효한 시간이라 `time` 이 반드시 갱신되지만,\n초기값 `1` 은 \"갱신이 안 되면 1을 반환한다\"는 뜻이 되어 근거 없는 값이 답으로 나갈 여지를 남긴다.\n\n### 3. (사소) `sum` 은 루프 안에서 선언하면 된다\n\n```java\nlong sum;              // 밖에서 선언\nwhile(low <= high) {\n    sum = 0;           // 매번 리셋\n```\n\n`while` 안에서 `long sum = 0;` 으로 두면 리셋을 잊을 일 자체가 없어진다.\n\n## 복잡도\n\n- 시간: `O(M log(max·n))` — M은 심사관 수. 상한을 `min·n` 으로 바꾸면 `log` 안이 좁아진다.\n- 공간: `O(1)` — 적정하다.\n\n## 요약\n\n가장 짧고 구조가 깔끔하다. 파라메트릭 서치 형태를 정확히 알고 있다.\n누적 합 오버플로 하나만 막으면 되고, `break` 한 줄이나 상한 조정 한 줄 중 아무거나면 된다."}},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/입국심사.java","lines":53,"code":"import java.util.Arrays;\n/**\n* 시행착오\n1. 문제 조건을 명확히 인지 하지 못했음\n    1-1. 시간을 심사위원 소요 시간별로 나누어서 더하는 게 n값인데\n    1-2. 기다렸다가 대기한다는 상황제시를 무작위적인 배치로 생각했고\n    1-3 최대 소요 심사위원이 있다는 생각으로 빠지게되었음\n    1-4 샘플 케이스를 명확하게 시뮬레이션하는 게 좋겠음\n2. gpt 힌트를 받아서, 탐색 변수를 시간으로 설정했음\n    2-1. 최소 시간이 아님에도 인원은 충족할 수 있음\n    2-2. 단지, 탐색 시 만족하는 값이 있다면 일단 값을 저장 후, 더 탐색하면서 갱신하면 되는데\n    2-3. 코드 템플릿을 생각하고 구현을 어려워했음\n3. 구현력이 떨어진다\n    3-1. 템플릿에 의존적임\n    3-2. 사고를 코드로 구현하는 연습이 필요함\n*/\n\nclass Solution {\n    \n    public static long people;\n    public static long answer;\n    \n    public static void binarySearch(long minTime, long maxTime, int[] times){\n        while (minTime <= maxTime) {\n            long midTime = (minTime+maxTime) / 2l;\n            long cnt = 0;\n            for (int t: times){\n                cnt += (midTime) / (long) t;\n            }\n            if (cnt >= people) {\n                // 시간이 대기인원에 비해 많다.\n                // 일단 정답 후보지만, t = 9, times = [2,4]  -> t = 8가 최적인 반례가 있다.\n                // 따라서, 정답으로 정해두고, 한번 더 탐색한다.\n                answer = midTime;\n                maxTime = midTime - 1l;\n            } else {\n                // 시간이 대기 인원에 비해 부족하다\n                minTime = midTime + 1l;\n            }\n        }\n    }\n    \n    public long solution(int n, int[] times) {\n        int judges = times.length;\n        Arrays.sort(times);\n        long longestTime = times[judges-1];\n        long worstTime = longestTime * (long) n;\n        people = n;\n        binarySearch(1, worstTime, times);\n        \n        return answer;\n    }\n}","review":{"platform":"programmers","problemId":"43238","author":"seongil","source":"이성일/week2/입국심사.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["overflow","uninitialized-state","naming","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(M log(max·n))","space":"O(1)"},"body":"# 입국심사 (programmers/43238) — seongil\n\n## 접근\n\n시간을 매개변수로 둔 파라메트릭 서치. 답은 맞다.\n\n주석의 반례가 이 문제의 핵심을 정확히 짚었다.\n\n```java\n// 일단 정답 후보지만, t = 9, times = [2,4]  -> t = 8가 최적인 반례가 있다.\n// 따라서, 정답으로 정해두고, 한번 더 탐색한다.\n```\n\n실제로 `times = [2,4]`, `n = 6` 일 때 `t = 9` 도 `t = 8` 도 6명을 처리한다.\n\"조건을 만족하는 값을 찾았다고 멈추면 안 되고, 더 작은 값이 있는지 계속 봐야 한다\"는\n파라메트릭 서치의 함정을 반례로 못박아둔 게 좋다.\n\n시행착오 기록도 솔직하다. 다만 한 가지만 짚자면 — `3. 구현력이 떨어진다` 는 과한 자평이다.\n이 코드는 상한·하한·갱신 조건이 모두 맞다. 틀린 건 아래 하나뿐이고, 그건 나머지 두 명도 똑같이 틀렸다.\n\n## 개선점\n\n### 1. (중요) 누적 합이 `long` 을 넘길 수 있다 — `overflow`\n\n```java\nlong worstTime = longestTime * (long) n;    // 가장 느린 심사관 기준\nbinarySearch(1, worstTime, times);\n...\nfor (int t: times){\n    cnt += (midTime) / (long) t;             // 끝까지 다 더한다\n}\n```\n\n제약은 `n ≤ 10⁹`, `times.length ≤ 10⁵`, `times[i] ≤ 10⁹` 다.\n\n| | 값 |\n|---|---|\n| `worstTime = max·n` | `10¹⁸` |\n| 첫 `midTime` | 약 `5 × 10¹⁷` |\n| 소요시간 1분 심사관 10만 명이면 `cnt` | `5 × 10²²` |\n| `long` 최대 | `9.2 × 10¹⁸` |\n\n`cnt` 가 음수로 뒤집히면 `cnt >= people` 이 거짓이 되어 탐색이 반대로 간다.\n예외 없이 답만 틀린다.\n\n```java\nfor (int t : times) {\n    cnt += midTime / t;\n    if (cnt >= people) break;   // 필요한 만큼만 세고 멈춘다\n}\n```\n\n같은 회차에서 이승주는 이 `break` 를 넣었고, 상한도 `times[0] * n` 으로 잡았다.\n가장 빠른 심사관 혼자 n명을 처리하는 시간이라 상한으로 유효하면서 구간이 훨씬 좁다.\n\n### 2. (중요) `answer` 와 `people` 이 `static` 이다 — `uninitialized-state`\n\n```java\npublic static long people;\npublic static long answer;\n\npublic static void binarySearch(long minTime, long maxTime, int[] times){\n    ...\n    answer = midTime;      // 반환하지 않고 static 에 써둔다\n}\n```\n\n`binarySearch` 가 `void` 라서 결과를 `static` 필드로 흘려보내고 있다.\n채점기가 같은 JVM에서 여러 번 호출하면 **`answer` 의 이전 값이 남는다.**\n지금은 항상 갱신되니 우연히 안전하지만, 조건이 한 번이라도 안 걸리면 앞 케이스의 답이 그대로 나간다.\n\n값을 반환하게 바꾸면 이 위험이 통째로 사라진다.\n\n```java\npublic static long binarySearch(long minTime, long maxTime, int[] times, long people) {\n    long answer = maxTime;\n    while (minTime <= maxTime) { ... }\n    return answer;\n}\n```\n\n### 3. (사소) `2l`, `1l` 은 대문자 `L` 로 — `naming`\n\n```java\nlong midTime = (minTime+maxTime) / 2l;\nmaxTime = midTime - 1l;\n```\n\n소문자 `l` 은 숫자 `1` 과 거의 구분이 안 된다. `2L`, `1L` 로 쓰는 게 자바 관례다.\n그리고 `minTime`/`maxTime` 이 이미 `long` 이라 `2` 로만 써도 결과는 같다.\n\n### 4. (사소) `judges` 는 한 번만 쓰인다\n\n```java\nint judges = times.length;\nArrays.sort(times);\nlong longestTime = times[judges-1];\n```\n\n`times[times.length - 1]` 로 바로 쓰면 변수 하나가 준다.\n\n## 복잡도\n\n- 시간: `O(M log(max·n))` — M은 심사관 수. 상한을 `times[0] * n` 으로 좁히면 `log` 안이 줄어든다.\n- 공간: `O(1)` — 적정하다.\n\n## 요약\n\n반례를 직접 만들어 \"찾아도 멈추지 않는다\"를 못박아둔 게 이 코드의 강점이다. 탐색 로직은 정확하다.\n누적 합 오버플로와 `static` 결과 전달 두 가지만 고치면 되고, 둘 다 구조 문제가 아니라 습관 문제다."}},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/입국심사.java","lines":36,"code":"import java.util.*;\n\nclass Solution {\n    public long solution(int n, int[] times) {\n        \n        Arrays.sort(times);\n\n        long left = times[0];\n        long right = (long) times[0] * n;\n\n        while (left <= right) {\n            long mid = (left + right)/ 2;\n\n            long count = 0;\n\n            for (int time : times) {\n                count += mid / time;\n\n                if (count >= n) {\n                    break;\n                }\n            }\n\n            if (count >= n) {  // mid 시간 안에 n명을 심사할 수 있음\n            \n                right = mid - 1;\n            } else {\n \n                left = mid + 1;\n            }\n        }\n\n        return left;\n    }\n}","review":{"platform":"programmers","problemId":"43238","author":"seungjoo","source":"이승주/week2/입국심사.java","week":"2","compiles":"true","verdict":"good","tags":["good-complexity","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(M log(min·n))","space":"O(1)"},"body":"# 입국심사 (programmers/43238) — seungjoo\n\n## 접근\n\n시간을 매개변수로 두는 파라메트릭 서치. **네 명 중 유일하게 탐색 상한을 `times[0] * n` 으로 잡았다.**\n\n```java\nArrays.sort(times);\nlong left  = times[0];\nlong right = (long) times[0] * n;   // 가장 빠른 심사관 * n\n```\n\n나머지 셋은 `times[max] * n` (가장 느린 심사관 기준)을 썼는데, 이쪽이 더 타이트하면서 **여전히 정답을 놓치지 않는다.**\n\n- 시간 `times[0] * n` 이면 가장 빠른 심사관 혼자서 `n` 명을 처리한다 (`min·n / min = n`).\n  즉 이 시간은 항상 \"가능\"하므로 상한으로 유효하다.\n- 하한 `times[0]` 도 정확하다. 최소 한 명을 심사하려면 최소 그만큼은 걸린다.\n\n이 선택 덕분에 얻는 게 하나 더 있는데, 아래에서 설명한다.\n\n## 잘한 점\n\n### 1. 탐색 상한이 오버플로까지 막아준다\n\n`count += mid / time` 은 심사관 수만큼 누적된다. 문제 제약은\n`n ≤ 10⁹`, `times.length ≤ 10⁵`, `times[i] ≤ 10⁹` 다.\n\n상한을 `max·n` 으로 잡으면 `mid` 가 최대 `10¹⁸` 까지 간다. 여기에 소요시간 1분짜리 심사관이\n여럿 섞여 있으면 한 항이 그대로 `10¹⁸` 이 되고, 10만 명분을 더하면 `long` (약 9.2×10¹⁸) 을 넘긴다.\n\n이 코드는 `mid ≤ min·n` 이므로 각 항이\n`mid / times[i] ≤ (min·n) / min = n ≤ 10⁹` 로 눌린다. 전부 더해도 `10⁵ × 10⁹ = 10¹⁴` 이라 안전하다.\n\n### 2. 조기 `break` 가 한 겹 더 막아준다\n\n```java\nfor (int time : times) {\n    count += mid / time;\n    if (count >= n) break;      // 필요한 만큼 넘으면 그만\n}\n```\n\n판정에 필요한 건 \"n 이상인가\" 뿐이라 정확한 총합은 필요 없다.\n불필요한 순회를 줄이면서, 누적값이 커질 여지도 같이 없앤다.\n\n같은 회차 나머지 세 명은 이 `break` 가 없다. 비교해보면 좋다.\n\n## 개선점\n\n### 1. (사소) `right` 의 근거를 한 줄 적어두면 좋겠다\n\n`times[0] * n` 이 상한으로 유효한 이유(가장 빠른 심사관 혼자 n명 처리)는\n코드만 봐서는 바로 안 보인다. 오히려 \"가장 느린 심사관을 써야 하는 것 아닌가?\" 하고\n잘못된 지적을 받기 쉬운 부분이다. 주석 한 줄이면 리뷰 시간이 절약된다.\n\n### 2. (사소) 빈 줄이 많다\n\n`while` 안팎으로 빈 줄이 2~3줄씩 들어가 있어 36줄 중 실질 코드는 20줄 남짓이다.\n로직이 짧고 명확한 만큼 붙여두면 한눈에 들어온다.\n\n## 복잡도\n\n- 시간: `O(M log(min·n))` — M은 심사관 수. 탐색 구간이 다른 셋보다 `max/min` 배 좁다.\n- 공간: `O(1)` — 정렬 외 추가 메모리 없음.\n\n## 요약\n\n네 명 중 가장 정확한 코드다. 탐색 상한을 `min·n` 으로 잡은 것이 핵심이고,\n그게 성능뿐 아니라 오버플로 안전성까지 가져왔다.\n근거를 주석으로 남겨두면 다음에 볼 사람이 헷갈리지 않는다."}}],"teamFeedback":null},{"key":"programmers/49189","platform":"programmers","problemId":"49189","title":"가장 먼 노드","url":"https://school.programmers.co.kr/learn/courses/30/lessons/49189","weeks":[4],"entries":[{"author":"junsoo","authorName":"김준수","week":4,"variant":null,"source":"김준수/week4/가장 먼 노드.java","lines":58,"code":"/*\n전략\n- BFS\n- 시작점에서 모든 dist에 최단거리 표기. 이때 최대값도 저장\n- 모든 노드의 dist를 돌면서 최대값과 값이 같은 dist의 개수를 세서 리턴\n*/\nimport java.util.*;\n\nclass Solution {\n    static List<List<Integer>> graph;\n    static int[] dist;\n    static int maxN;\n    \n    public int solution(int n, int[][] edge) {\n        maxN = 0; // 가장 멀리 떨어진 노드의 거리\n        \n        dist = new int[n + 1];\n        Arrays.fill(dist, -1);\n        dist[1] = 0; // 시작 지점\n        \n        graph = new ArrayList<>();\n        for(int i = 0; i <= n; i++){\n            graph.add(new ArrayList<>());\n        }\n        \n        for(int[] e : edge){\n            graph.get(e[0]).add(e[1]);\n            graph.get(e[1]).add(e[0]);\n        }\n        \n        bfs(1);\n        \n        // maxN과 값이 같은 dist의 개수 찾기\n        int answer = 0;\n        for(int i = 1; i <= n; i++){\n            if(dist[i] == maxN) answer++;\n        }\n        return answer;\n    }\n    \n    private void bfs(int start){\n        // 모든 노드에 최단거리 갱신\n        Queue<Integer> queue = new ArrayDeque<>();\n        queue.offer(start);\n        \n        while(!queue.isEmpty()){\n            int curr = queue.poll();\n            \n            for(int next : graph.get(curr)){\n                if(dist[next] == -1){\n                    dist[next] = dist[curr] + 1;\n                    maxN = Math.max(maxN, dist[next]);\n                    queue.offer(next);\n                }\n            }\n        }\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":4,"variant":null,"source":"안찬웅/week4/가장 먼 노드.java","lines":58,"code":"import java.util.*;\nclass Solution {\n    static List<Integer>[] graph;\n    static boolean[] vis;\n    static int[] dist;\n    public int solution(int n, int[][] edge) {\n        graph = new List[n+1];\n        \n        for(int i=1; i<=n; i++) {\n            graph[i] = new ArrayList<>();\n        }\n        \n        for(int i=0; i<edge.length; i++) {\n            int a = edge[i][0];\n            int b = edge[i][1];\n            graph[a].add(b);\n            graph[b].add(a);\n        }\n        //System.out.println(Arrays.toString(graph));\n        bfs(1, n);\n        \n        Arrays.sort(dist);\n        \n        //System.out.println(Arrays.toString(dist));\n        \n        int cnt = 1;\n        for(int i=n; i>0; i--) {\n            if(dist[i] == dist[i-1]) {\n                cnt++;\n            } else {\n                break;\n            }\n        }\n        \n        return cnt;\n    }\n    static void bfs(int start, int n) {\n        Deque<Integer> dq = new ArrayDeque<>();\n        vis = new boolean[n+1];\n        dist = new int[n+1];\n        \n        dq.offer(start);\n        vis[start] = true;\n        while(!dq.isEmpty()) {\n            //System.out.println(dq);\n            int cur = dq.poll();\n            for(int next : graph[cur]) {\n                if(!vis[next]) {\n                    vis[next] = true;\n                    //System.out.println(\"next: \" + next + \" dist: \" + dist[next]);\n                    dist[next] = dist[cur] + 1; \n                    dq.offer(next);\n                }\n            }\n        }\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/49191","platform":"programmers","problemId":"49191","title":"순위","url":"https://school.programmers.co.kr/learn/courses/30/lessons/49191","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/순위.java","lines":88,"code":"/*\n전략\n- 키순서와 동일한 문제\n- 모든 정점에 대해, 나보다 강한 사람의 수 찾기\n- 모든 정점에 대해, 나보다 약한 사람의 수 찾기\n- 강한 사람 + 약한 사람 == N - 1이면 자신의 순위를 알 수 있음\n*/\nimport java.util.*;\n\nclass Solution {\n    static List<List<Integer>> strongs; // i보다 센 사람\n    static List<List<Integer>> weaks; // i보다 약한 사람\n    \n    public int solution(int n, int[][] results) {\n        int answer = 0;\n        strongs = new ArrayList<>();\n        weaks = new ArrayList<>();\n        \n        for(int i = 0; i <= n; i++){\n            strongs.add(new ArrayList<>());\n            weaks.add(new ArrayList<>());\n        }\n        \n        for(int[] r : results){\n            strongs.get(r[1]).add(r[0]);\n            weaks.get(r[0]).add(r[1]);\n        }\n        \n        for(int i = 1; i <= n; i++){\n            int cnt = countStrong(i);\n            cnt += countWeak(i);\n            \n            // 위 아래 사람 수가 n - 1이면 자기 순위 알 수 있음\n            if(cnt == n - 1){\n                answer++;\n            }\n        }\n        \n        return answer;\n    }\n    \n    // i보다 센 사람의 수 세기\n    private int countStrong(int i){\n        int result = 0;\n        Queue<Integer> queue = new ArrayDeque<>();\n        Set<Integer> set = new HashSet<>(); // 중복 방지\n        queue.offer(i);\n        set.add(i);\n        \n        while(!queue.isEmpty()){\n            int curr = queue.poll();\n            \n            for(int s : strongs.get(curr)){\n                if(!set.contains(s)){\n                    result++;\n                    queue.offer(s);\n                    set.add(s);\n                }\n            }\n        }\n        \n        return result;\n    }\n    \n    // i보다 약한 사람의 수 세기\n    private int countWeak(int i){\n        int result = 0;\n        Queue<Integer> queue = new ArrayDeque<>();\n        Set<Integer> set = new HashSet<>(); // 중복 방지\n        queue.offer(i);\n        set.add(i);\n        \n        while(!queue.isEmpty()){\n            int curr = queue.poll();\n            \n            for(int w : weaks.get(curr)){\n                if(!set.contains(w)){\n                    result++;\n                    queue.offer(w);\n                    set.add(w);\n                }\n            }\n        }\n        \n        return result;\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/순위.java","lines":63,"code":"import java.util.*;\n/*\n    정확하게 순위를 알 수 있는 사람은 몇명인가\n\n    알고리즘: 그래프 DFS, 인접리스트\n    \n    진사람 수 + 이긴사람 수 == 전체사람수-1 cnt++;\n*/\nclass Solution {\n    static List<Integer>[] win;\n    static List<Integer>[] lose;\n    static boolean[] vis;\n    static int cnt;\n    public int solution(int n, int[][] results) {\n        win  = new List[n+1];\n        lose = new List[n+1];\n        int answer = 0;\n        int total;\n        \n        for(int i=1; i<=n; i++) {\n            win[i] = new ArrayList<>();\n            lose[i] = new ArrayList<>();\n        }\n        \n        for(int i=0; i<results.length; i++) {\n            int winner = results[i][0];\n            int loser = results[i][1];\n            win[winner].add(loser);\n            lose[loser].add(winner);\n        }\n\n        for(int i=1; i<=n; i++) {\n            // win\n            vis = new boolean[n+1];\n            cnt = 0;\n            vis[i] = true;\n            dfs(i, win);\n            total = cnt;\n            \n            // lose\n            vis = new boolean[n+1];\n            cnt = 0;\n            vis[i] = true;\n            dfs(i, lose);\n            total += cnt;\n            \n            // (이긴사람 수 + 진사람 수) == 전체사람수 - 1\n            if(total == n-1) answer++;\n            \n        }\n        return answer;\n    }\n    static void dfs(int node, List<Integer>[] graph) {\n        for(int next : graph[node]) {\n            if(!vis[next]) {\n                vis[next] = true;\n                cnt++;\n                dfs(next, graph);\n            }\n        }\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/순위.java","lines":83,"code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.Collections;\n\nclass Solution {\n    public int solution(int n, int[][] results) {\n        int answer = 0;\n        // 경기 결과를 읽으며 나보다 쎈 약한 선수 리스트 제작\n        List<Node> enroll = new ArrayList<>();\n        for(int i = 1; i <= n; i++) {\n            enroll.add(new Node(i));\n        }\n        \n        for (int[] result: results) {\n            enroll.get(result[0] - 1).weaker.add(enroll.get(result[1] - 1));\n            enroll.get(result[1] - 1).stronger.add(enroll.get(result[0] -1));\n        }\n        \n        \n        \n        // 각 리스트별로 나보다 쎈선수 dfs로 구하고 약한 선수 dfs로 구해\n            // 전체선수 다파악하기\n            // 선수별 리스트 루프 \n            // 이미 파악된 선수 제외\n            // 새로 파악될 때 마다 count\n            // 그 이상의 선수가 없을 때 종료 \n        for (int i = 0; i < n; i++){\n            int scnt = 0, wcnt = 0;\n            boolean[] svisited = new boolean[n];\n            scnt = sdfs(enroll.get(i).stronger, svisited);\n            boolean[] wvisited = new boolean[n];\n            wcnt = wdfs(enroll.get(i).weaker, wvisited);\n            // 전체 선수 수 - 1 이면 answer += 1   \n            if (scnt + wcnt == (n-1)) {\n                answer += 1;\n            }\n        }\n                \n        \n        return answer;\n    }\n    \n    public static int sdfs(List<Node> list, boolean[] visited){\n        int count = 0;\n        for (Node n: list) {\n            if ( visited[n.idx - 1] ) {\n                continue;\n            } else {\n                visited[n.idx -1] = true;\n                count++;\n                count += sdfs(n.stronger, visited);\n            }\n        }\n        \n        return count;\n    }\n    \n    public static int wdfs(List<Node> list, boolean[] visited){\n        int count = 0;\n        for (Node n: list) {\n            if ( visited[n.idx - 1] ) {\n                continue;\n            } else {\n                visited[n.idx -1] = true;\n                count++;\n                count += wdfs(n.weaker, visited);\n            }\n        }\n        \n        return count;\n    }\n    \n    public static class Node {\n        public int idx;\n        public List<Node> stronger = new ArrayList<>();\n        public List<Node> weaker = new ArrayList<>();\n        \n        public Node(int idx) {\n            this.idx = idx;\n        }\n    }\n    \n}","review":null},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/순위.java","lines":66,"code":"import java.util.*;\nclass Solution { //swea 키 순위 문제와 똑같음\n    static int N;\n    static ArrayList<Integer>[] graph;\n    static ArrayList<Integer>[] reverseGraph;\n    public int solution(int n, int[][] results) {\n        this.N = n;\n        \n        graph = new ArrayList[n+1];\n        reverseGraph = new ArrayList[n+1];\n        \n        for(int i = 0; i <= n; i++){\n            graph[i] = new ArrayList<>();\n            reverseGraph[i] = new ArrayList<>();\n        }\n        \n        for(int i = 0; i < results.length; i++){\n            int from = results[i][0];\n            int to = results[i][1];\n            \n            graph[from].add(to);\n            reverseGraph[to].add(from);\n        }\n        int cnt = 0;\n        for(int i = 1; i <= n; i++){\n            int a = bfs(i,graph);\n            int b = bfs(i,reverseGraph);\n            \n            if(a+b == n-1){\n                cnt++;\n            }\n        }\n        \n        return cnt;\n        \n        \n    }\n    \n    static int bfs(int start, ArrayList<Integer>[] currentGraph){\n        \n        ArrayDeque<Integer> q = new ArrayDeque<>();\n        boolean[] visited = new boolean[N+1];\n        visited[start] = true;\n        int cnt = 0;\n        \n        q.offer(start);\n        \n        while(!q.isEmpty()){\n            \n            Integer current = q.poll();\n            \n            for(Integer next : currentGraph[current]){\n                \n                if(!visited[next]){\n                    q.offer(next);\n                    visited[next] = true;\n                    cnt++;\n                }\n                \n            }\n        }\n        \n        return cnt;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/60059","platform":"programmers","problemId":"60059","title":"자물쇠와 열쇠","url":"https://school.programmers.co.kr/learn/courses/30/lessons/60059","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/자물쇠와 열쇠.java","lines":90,"code":"/*\n전략.\n- 완전탐색 백트래킹\n- 격자 최대 크기는 20 - 20 - 20이니까 60x60으로 만들기\n- 열쇠의 [M-1][M-1]이 자물쇠의 [0][0]에 닿는 시점부터 우측으로 열쇠를 옮김\n    - 열쇠의 [M-1][0]이 자물쇠의 [0][N-1]에 닿는 시점까지 옮김\n    - 그 후 자물쇠의 행을 +1 하여 다시 좌→우 이동 반복\n    - 열쇠가 회전 가능한 4 모양에 대해 모두 시도\n- 만약 각 시도 중 fit한 경우가 생기면 즉시 종료 후 true 반환\n- 전체 시도해도 fit한 경우 없었으면 false 반환\n*/\nclass Solution {\n    static int[][][] keys;\n    static int[][] lock;\n    \n    public boolean solution(int[][] key, int[][] l) {\n        boolean answer = false;\n        \n        lock = l;\n        \n        // 키의 회전 모양 초기화\n        keys = new int[4][key.length][key.length];\n        keys[0] = key; \n        for(int i = 1; i < 4; i++){\n            int[][] newKey = new int[key.length][key.length];\n            for(int j = 0; j < key.length; j++){\n                for(int k = 0; k < key.length; k++){\n                    newKey[j][k] = keys[i - 1][k][key.length - j - 1];\n                }\n            }\n            keys[i] = newKey;\n        }\n        \n        // board 초기화\n        int[][] board = new int[60][60];\n        int[][] keyBoard = new int[60][60];\n        for(int i = 20; i < 20 + lock.length; i++){\n            for(int j = 20; j < 20 + lock.length; j++){\n                board[i][j] = lock[i - 20][j - 20];\n                keyBoard[i][j] = lock[i - 20][j - 20];\n            }\n        }\n        \n        // keyboard에 key 배치\n        for(int i = 0; i < 4; i++){\n            for(int j = 20 - key.length; j <= 20 + lock.length; j++){\n                for(int k = 20 - key.length; k <= 20 + lock.length; k++){\n                    // keyBoard에 key 끼워넣기\n                    makeKeyBoard(keyBoard, i, j, k);\n                    \n                    // keyBoard가 lock의 모든 홈을 채우는지 검사\n                    if(isFull(keyBoard)){\n                        answer = true;\n                    }\n                    \n                    // keyBoard 복구\n                    for(int a = 0; a < 60; a++){\n                        for(int b = 0; b < 60; b++){\n                            keyBoard[a][b] = board[a][b];\n                        }\n                    }\n                }\n            }\n        }\n        \n        return answer;\n    }\n    \n    // lock만 있는 keyBoard에 key를 겹쳐서 리턴\n    private void makeKeyBoard(int[][] board, int keyIndex, int x, int y){\n        for(int i = x; i < x + keys[0][0].length; i++){\n            for(int j = y; j < y + keys[0][0].length; j++){\n                board[i][j] += keys[keyIndex][i - x][j - y];\n            }\n        }\n    }\n    \n    // lock의 모든 홈이 채워졌는지\n    private boolean isFull(int[][] board){\n        for(int i = 20; i < 20 + lock.length; i++){\n            for(int j = 20; j < 20 + lock.length; j++){\n                // 홈이 비어있거나, 돌기가 겹쳤거나\n                if(board[i][j] == 0 || board[i][j] == 2){\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/자물쇠와 열쇠.java","lines":98,"code":"import java.util.*;\n/*\n    Key를 회전시키고 이동시켜서 Lock에 넣으면 열린다\n    :열쇠는 회전과 이동이 가능\n\n    알고리즘: 완전탐색\n\n    자물쇠(lock): N * N 격자 형태\n    열쇠(key): M * M 격자 형태\n    \n    홈: 0\n    돌기: 1\n    \n    1. 완전탐색으로 모든 경우의 수에 다음을 대입한다. \n    1.1 key를 90도 회전시키거나 상하좌우로 이동시켜서 Lock에 대입한다.\n    1.2 대입해서 홈에 들어가고, 돌기(1)과 겹치지 않으면 true\n    1.3 홈이(0)이아니고 돌기(1)과 겹치면 false\n    \n    아닌 경우를 코드로 짜고 else true가 더 잘 맞을듯 싶음\n*/\nclass Solution {\n    static boolean answer;\n    static int n, m;\n    public boolean solution(int[][] key, int[][] lock) {\n        answer = false;\n        m = key.length;\n        n = lock.length;\n        \n        // 1.0도 이동 -> 오른쪽 한칸, 왼쪽 한칸, 위로 한칸 아래로 한칸\n        // 1.90도 이동 -> 오른쪽 한칸, 왼쪽 한칸, 위로 한칸 아래로 한칸\n        // 2.180도 이동 -> 오른쪽 한칸, 위쪽 한칸, 위로 한칸, 아래로 한칸\n        // 3.270도 이동 -> 오른쪽 한칸, 위쪽 한칸, 위로 한칸, 아래로 한칸\n        rotate(key, lock, 0);\n        if(answer) return true;\n        rotate(key, lock, 90);\n        if(answer) return true;\n        rotate(key, lock, 180);\n        if(answer) return true;\n        rotate(key, lock, 270);\n        \n        return answer;\n    }\n    static void rotate(int[][] key, int[][] lock, int degree) {\n        int[][] rotate = new int[m][m];\n       \n        for(int i=0; i<m; i++) {\n            for(int j=0; j<m; j++) {\n                switch(degree) {\n                    case 0:\n                        rotate[i][j] = key[i][j];\n                        break;\n                    case 90:\n                        rotate[i][j] = key[m-1-j][i];\n                        break;\n                    case 180:\n                        rotate[i][j] = key[m-1-i][m-1-j];\n                        break;\n                    case 270:\n                        rotate[i][j] = key[j][m-1-i];\n                        break;\n                }\n            }\n        }      \n        // 상하좌우 이동\n        moveKey(rotate, lock);\n    }\n    // 상하좌우 이동하는 함수\n    static void moveKey(int[][] key, int[][] lock) {\n        // 한번에 다같이 이동해야함 \n        // 모두 1인 부분을 오른쪽으로 이동 (왼쪽, 아래, 위)\n        for(int x=-(m-1); x<n; x++) {\n            for(int y=-(m-1); y<n; y++) {\n                keyVerseLock(key, lock, x, y);\n                if(answer) return;\n            }\n        }\n    }\n    \n    // key랑 Lock을 비교하는 함수\n    static void keyVerseLock(int[][] key, int[][] lock, int x, int y) {\n        for(int i=0; i<n; i++) {\n            for(int j=0; j<n; j++) {\n                int dx = i - x;\n                int dy = j - y;\n                int keyVal = 0;\n                if(dx >= 0 && dx < m && dy >= 0 && dy < m) {\n                    keyVal = key[dx][dy];\n                }\n                if(keyVal + lock[i][j] != 1) {\n                    answer = false;\n                    return;\n                }\n            }\n        }\n        answer = true;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/자물쇠와열쇠.java","lines":147,"code":"import java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n\nclass Solution {\n    \n    public static List<int[][]> visited = new ArrayList<>();\n    \n    public static boolean isVisited(int[][] key){\n        for (int[][] v : visited) {\n            boolean flag = false;\n            for (int i = 0; i < v.length; i++){\n                for (int j = 0; j < v.length; j++){\n                    if (v[i][j] != key[i][j]) {\n                        flag = true;\n                        break;\n                    }\n                    if (flag) break;\n                }\n                \n                if (!flag) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n    public static boolean verify(int[][] key, int[][] lock) {\n        \n        for (int i = 0; i <= (lock.length - key.length); i++) {\n            for (int j = 0; j <= (lock.length - key.length); j++) {\n                boolean flag = true;\n                for (int r = i; r < (i + key.length); r++) {\n                    for (int c = j; c < (j + key.length); c++) {\n                        if ((key[r-i][c-j] ^ lock[r][c]) == 0) {\n                            flag = false;\n                            break;\n                        }\n                    }\n                    if (!flag) break;\n                }\n                if (flag) return true;\n            }\n        }\n        return false;\n    }\n    \n    public static void rotate(int[][] key, int t) {\n        for (int i = 0; i < t; i++){\n            for (int r = 0; r < key.length-1; r++){\n                for (int c = r+1; c < key.length; c++){\n                    int temp = key[r][c];\n                    key[r][c] = key[c][r];\n                    key[c][r] = temp;\n                }\n            }\n        \n        }\n    }\n    public static void move(int[][] key, int dir) {\n        switch (dir) {\n            case 0: {\n                for (int i = 0; i < key.length; i++){\n                    if (i == (key.length -1)) Arrays.fill(key[i], 0);\n                    else key[i] = key[i+1];\n                } break;\n            }\n            case 1: {\n                for (int j = key.length-1; j >= 0; j--) {\n                    for (int i = 0; i < key.length; i++){\n                        if (j == 0) key[i][j] = 0;\n                        else key[i][j] = key[i][j-1];\n                    }\n                } break;\n            }\n            case 2: {\n                for (int i = (key.length -1); i >= 0; i--){\n                    if (i == 0) Arrays.fill(key[i], 0);\n                    else key[i] = key[i-1];\n                } break;\n            }\n            case 3: {\n                for (int j = 0; j < (key.length -1); j++) {\n                    for (int i = 0; i < key.length; i++) {\n                        if (j == (key.length - 1)) key[i][j] = 0;\n                        else key[i][j] = key[i][j+1];\n                    }\n                } break;\n            }\n            default: break;\n        }\n    }\n    \n    public static boolean dfs(int[][] key, int[][] lock) {\n        if (verify(key, lock)) {\n            return true;\n        }\n        for (int i = 1; i <= 7; i++){\n            if (i <= 3) {\n                rotate(key, i);\n                if (isVisited(key)) {\n                    rotate(key,3); // 3번더회전하면 원위치,원위치로, 새탐색 시작\n                    continue;\n                } else {\n                    visited.add(key);\n                    if (dfs(key,lock)) return true;\n                    else {\n                        rotate(key,3);\n                        continue;\n                    }\n                    \n                }\n            } else {\n                int[][] temp  = key;\n                move(key, i%4);\n                if (isVisited(key)) {\n                    key = temp; // 이동 전으로\n                    continue;\n                } else {\n                    visited.add(key);\n                    if (dfs(key,lock)) return true;\n                    else {\n                        key = temp;\n                        continue;\n                    }\n                }\n            }\n        }\n        return false;\n    }\n    \n    public boolean solution(int[][] key, int[][] lock) {\n        boolean answer = dfs(key,lock);\n        \n        // DFS 기반 완전 탐색\n            // 1. 회전 4가지, 이동 4가지 총 8가지의 리프\n        \n            // 2. 매 스테이지별로 8가지 탐색 진행\n                // 2.1 탐색 후 이미 방문한 노드면 탐색 종료, 이전 스테이지로\n                // 2-2. 첫 방문일 경우 방문 노드에 기입 후, 검증 \n                    // 2-2-1 자물쇠 사이즈 안을 범위로 순회 \n            // 3. 검증 실패 시, 계속해서 뉴스테이지로\n                // 3-1. 검증 성공 시, 모든 탐색 종료\n        return answer;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/자물쇠와 열쇠.java","lines":128,"code":"/* 풀이 과정\n1. 열쇠가 자물쇠 밖에서도 시작할 수 있으므로 자물쇠를 상하좌우로 M-1칸 확장했다.\n   확장 배열에 자물쇠를 복사하는 과정에서 인덱스 오류가 발생해 범위를 다시 확인했다.(gpt도움)\n\n2. 열쇠를 모든 위치에 놓고 90도씩 회전하며 검사했다.\n   실제 자물쇠 영역의 합이 모두 1이면 열 수 있다고 판단했다.\n\n3. 처음에는 확장 배열 전체를 검사해 오답이 발생했다. 문제에 나온 예시로 실행하면 열쇠와 자물쇠의 돌기부분끼리 더해져 2가되버림 -> 정답인데 정답이 아니도록 나오게 됌\n   자물쇠 밖으로 튀어나온 열쇠는 상관없으므로 실제 N×N 자물쇠 영역만 검사해야 한다.\n*/\n\nclass Solution {\n    static int N;\n    static int M;\n    static int[][] expendedLock;\n    public boolean solution(int[][] key, int[][] lock) {\n        this.M = key.length;\n        this.N = lock.length;\n       \n        expendedLock = new int[N+2*M-2][N+2*M-2];\n        \n        for(int i = 0; i < M-1; i++){\n            for(int j = 0; j < expendedLock[0].length; j++){\n                expendedLock[i][j] = 1;\n            }\n        }\n        \n        for(int i = M-1; i < N+M-1; i++){\n            for(int j = 0; j < expendedLock[0].length; j++){\n                if(j < M-1 || j >= N+M-1){\n                    expendedLock[i][j] = 1;\n                }else{\n                    expendedLock[i][j] = lock[i-(M-1)][j-(M-1)];\n                }\n            }\n        }\n        \n        for(int i = N+M-1; i < expendedLock.length; i++){\n            for(int j = 0; j < expendedLock[0].length; j++){\n                expendedLock[i][j] = 1;\n            }\n        }\n\n        boolean flag = false;\n        for(int i = 0; i < M+N-1; i++){\n            for(int j = 0; j < M+N-1; j++){\n                flag = simulate(i,j,key);\n                    if(flag) return true;\n            }\n        }\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        return false;\n    }\n    \nstatic boolean simulate(int startX, int startY, int[][] key) {\n\n    for (int a = 0; a < 4; a++) {\n\n        // 회전 방향마다 원본 자물쇠 복사\n        int[][] copyMap = copy(expendedLock);\n\n        // 현재 위치에 열쇠를 겹쳐서 값 더하기\n        for (int i = startX; i < startX + M; i++) {\n            for (int j = startY; j < startY + M; j++) {\n                copyMap[i][j] += key[i - startX][j - startY];\n            }\n        }\n        \n        boolean possible = true;\n\n        for (int i = M - 1; i < N + M - 1; i++) {\n            for (int j = M - 1; j < N + M - 1; j++) { //중앙부분만 감사\n\n                if (copyMap[i][j] != 1) {\n                    possible = false;\n                    continue;\n                }\n            }\n        }\n\n        // 현재 회전 방향에서 자물쇠가 열림\n        if (possible) {\n            return true;\n        }\n\n        // 열쇠를 90도 회전\n        key = rotate(key);\n    }\n\n    // 네 가지 방향 모두 실패\n    return false;\n}\n    \n    static int[][] rotate(int[][] key){\n        \n        int[][] copyKey = new int[M][M];\n        \n        for(int i = 0; i < M; i++){\n            for(int j = 0; j < M; j++){\n                copyKey[i][j] = key[M-1-j][i];\n        }\n    }\n        return copyKey;\n    }\n    \n        \n    \n    static int[][] copy(int[][] map){  //맵을 복사하는 메서드\n        \n        int[][] copy = new int[map.length][map[0].length];\n        \n        for(int i = 0; i < copy.length; i++){\n            copy[i] = map[i].clone();\n        }\n        \n        return copy;\n    }\n    \n}","review":null}],"teamFeedback":null},{"key":"programmers/64062","platform":"programmers","problemId":"64062","title":"징검다리 건너기","url":"https://school.programmers.co.kr/learn/courses/30/lessons/64062","weeks":[4],"entries":[{"author":"junsoo","authorName":"김준수","week":4,"variant":null,"source":"김준수/week4/징검다리 건너기.java","lines":85,"code":"/*\n전략\n- 매개변수 탐색\n    - 매개변수 : 징검다리를 건널 수 있는 사람의 수\n        - 가능한 사람수 / 불가능한 사람수 의 경계가 되는 가능한 사람 수를 찾아야 함\n        - 최근에 풀어보니 매개변수 탐색의 매개변수는 정답으로 제시해되는 변수인 경우가 많은듯\n    - isValid : (현재 사람 수)가 징검다리를 건넜을 때 다음 사람이 징검다리를 건널 수 있는가?\n        - 징검다리의 돌에 적힌 수를 전부 현재 사람 수만큼 빼줘서 isValid에 맞는 상태를 만듬\n        - 처음부터 끝까지 징검다리를 돌면서 연속된 0의 개수를 찾음\n        - 연속된 0의 개수가 k보다 같거나 크면 false\n\n시행착오\n- isValid의 로직을 시뮬레이션 형식으로 짰더니 시간초과 발생\n    - 처음부터 끝까지 징검다리를 돌면서 다음 돌이 0 이하면 검증 시작\n    - 다음 1번째 돌부터 k번째 돌까지 전부 돌면서 하나라도 1 이상이 있으면 검증 중지\n    - k번째 돌까지 다 돌았는데 모두 0 이하였으면 false 반환\n    - 모든 돌을 다 돌았는데 검증 완료됐으면 true 반환\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static int[] stones;\n    static int k;\n    \n    public int solution(int[] stones, int k) {\n        this.stones = stones;\n        this.k = k;\n        \n        // 돌이 1개면 해당 돌의 수가 정답\n        if(stones.length == 1){\n            return stones[0];\n        }\n        \n        // 돌 숫자 최대치 찾기\n        int end = 0;\n        for(int i = 0; i < stones.length; i++){\n            end = Math.max(end, stones[i]);\n        }\n        \n        // 매개 변수 탐색(건널 수 있는 사람의 수)\n        int start = 0;\n        while(start <= end){\n            int mid = (start + end) / 2;\n            \n            if(isValid(mid) == true){\n                start = mid + 1;\n            }\n            else{\n                end = mid - 1;\n            }\n        }\n        \n        return start;\n    }\n    \n    private boolean isValid(int people){\n        int[] nextStones = Arrays.copyOf(stones, stones.length);\n        \n        // 연속된 0의 개수 찾기\n        int zeroCnt = 0;\n        int zeroSeqCnt = 0;\n        \n        // 사람 수만큼 디딤돌 수 빼면서 0 탐색\n        for(int i = 0; i < nextStones.length; i++){\n            nextStones[i] -= people;\n            \n            if(nextStones[i] <= 0){\n                zeroCnt++;\n            }\n            else{\n                zeroSeqCnt = Math.max(zeroSeqCnt, zeroCnt);\n                zeroCnt = 0;\n            }\n        }\n        zeroSeqCnt = Math.max(zeroSeqCnt, zeroCnt);\n        \n        if(zeroSeqCnt >= k){\n            return false;\n        }\n        else{\n            return true;\n        }\n    }\n}","review":null},{"author":"junsoo","authorName":"김준수","week":4,"variant":"failed","source":"김준수/week4/징검다리 건너기 실패.java","lines":88,"code":"/*\n실패 코드\n- 정확성 테스트는 다 맞는데 효율성 테스트 3/14\n- 3개는 통과했으니까 매개변수 탐색이라는 접근이 틀린 건 아닌듯\n- isValid의 시간 복잡도를 더 줄여야 할 것 같음\n*/\nimport java.util.*;\n\nclass Solution {\n    static int[] stones;\n    static int k;\n    \n    public int solution(int[] stones, int k) {\n        this.stones = stones;\n        this.k = k;\n        \n        // 돌이 1개면 해당 돌의 수를 리턴\n        if(stones.length == 1){\n            return stones[0];\n        }\n        \n        // 돌 숫자 최대치 찾기\n        int end = 0;\n        for(int i = 0; i < stones.length; i++){\n            end = Math.max(end, stones[i]);\n        }\n        \n        // 매개 변수 탐색(건널 수 있는 사람의 수)\n        int start = 0;\n        while(start <= end){\n            int mid = (start + end) / 2;\n            \n            //System.out.println(start + \" \" + mid + \" \" + end);\n            \n            if(isValid(mid) == true){\n                start = mid + 1;\n            }\n            else{\n                end = mid - 1;\n            }\n        }\n        \n        return start;\n    }\n    \n    private boolean isValid(int people){\n        int[] nextStones = Arrays.copyOf(stones, stones.length);\n        \n        // 사람 수만큼 디딤돌 수 빼기\n        for(int i = 0; i < nextStones.length; i++){\n            nextStones[i] -= people;\n        }\n        \n        // 현재 돌에서 점프가 가능한지 판별\n        // 마지막 돌은 살아서 갈 수만 있으면 무조건 통과니까 스킵\n        for(int i = 0; i < nextStones.length - 1; i++){\n            // 다음 돌이 0 이하면 판별 시작\n            if(nextStones[i + 1] <= 0){\n                for(int j = 1; j <= k; j++){\n                    int nextIdx = i + j;\n                    \n                    //System.out.println(i + \"번째 돌의 다음 \" +  j + \"번째 돌 검증 중\");\n                    // 배열 범위 넘으면 판별 종료\n                    if(nextIdx >= nextStones.length){\n                        //System.out.println(i + \"번째 돌의 다음 \" + j + \"번째 돌 검증 통과(범위초과)\");\n                        break;\n                    }\n                    \n                    // 종료 조건 : k번째 다음 돌까지 전부 0 이하면 false\n                    if(j == k && nextStones[nextIdx] <= 0){\n                        //System.out.println(i + \"번째 돌의 다음 \" + j + \"번째 돌 최종 검증 실패\");\n                        return false;\n                    }\n                    \n                    // 밟을 수 있는 돌이 있으면 판별 종료\n                    if(nextStones[nextIdx] > 0){\n                        //System.out.println(i + \"번째 돌의 다음 \" + j + \"번째 돌 검증 통과(밟을 수 있음)\" + nextStones[nextIdx]);\n                        break;\n                    }\n                    \n                    //System.out.println(i + \"번째 돌의 다음 \" + j + \"번째 돌 검증 실패\");\n                }\n            }\n        }\n        \n        return true;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/67259","platform":"programmers","problemId":"67259","title":"경주로 건설","url":"https://school.programmers.co.kr/learn/courses/30/lessons/67259","weeks":[2,3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/경주로 건설.java","lines":103,"code":"/*\n전략.\n- 완전탐색 DFS\n- 가능한 모든 경로로 (N-1, N-1)에 도달시키고, 그 때의 비용 구하기\n    - 만약 현재 비용이 현재 결과값보다 커지면 프루닝\n- dist 배열을 3차원으로 사용해서 (x좌표, y좌표, 방향)을 저장하고 낮은 값으로 갱신\n    - 같은 좌표여도 바라보는 방향이 다른 경우 다른 결과를 내기 때문\n\n시행착오\n- 2차원 dist 배열을 사용했으나 특정 지점에서는 최소비용이 아니나 \n  결과적으로 최소비용이 되는 반례가 있었음\n- 백트래킹으로 변경했으나 시간초과 발생함\n  프루닝 조건을 여럿 추가해도 시간초과를 피할 수 없음\n*/\n\nclass Solution {\n    static int[] dx = new int[]{-1, 1, 0, 0};\n    static int[] dy = new int[]{0, 0, -1, 1};\n    static int[][] board;\n    static int[][][] dist;\n    \n    class Car{\n        int x;\n        int y;\n        int dir;\n        int cost;\n        \n        Car(int x, int y, int dir){\n            this.x = x;\n            this.y = y;\n            this.dir = dir;\n            cost = 0;\n        }\n    }\n    \n    public int solution(int[][] b) {\n        board = b;\n        dist = new int[board.length][board.length][4];\n        \n        // dist 배열 초기화(x좌표, y좌표, 방향)\n        for(int i = 0; i < board.length; i++){\n            for(int j = 0; j < board.length; j++){\n                for(int k = 0; k < 4; k++){\n                    dist[i][j][k] = Integer.MAX_VALUE;\n                }\n            }\n        }\n        // (0, 0)의 비용을 0으로 초기화(4방향)\n        dist[0][0][0] = 0;\n        dist[0][0][1] = 0;\n        dist[0][0][2] = 0;\n        dist[0][0][3] = 0;\n        \n        dfs(new Car(0, 0, 1)); // 밑 보고 출발\n        dfs(new Car(0, 0, 3)); // 오른쪽 보고 출발\n        \n        // 결과 찾기(목표 지점의 4방향)\n        int answer = Integer.MAX_VALUE;\n        for(int i = 0; i < 4; i++){\n            answer = Math.min(answer, dist[board.length - 1][board.length - 1][i]);\n        }\n        \n        return answer;\n    }\n    \n    private void dfs(Car car){\n        // 4방향 탐색\n        for(int i = 0; i < 4; i++){\n            int nx = car.x + dx[i];\n            int ny = car.y + dy[i];\n            boolean isCurve = (car.dir != i);\n            \n            if(!inRange(nx, ny)){\n                continue;\n            }\n            \n            if(board[nx][ny] == 0){\n                Car next = new Car(nx, ny, i);\n                // 커브면 (커브500 + 직선도로100)으로 600\n                next.cost = (isCurve) ? car.cost + 600 : car.cost + 100;\n                \n                // 종료 조건\n                if(next.x == board.length - 1 && next.y == board.length - 1){\n                    dist[next.x][next.y][next.dir] = Math.min(dist[next.x][next.y][next.dir] , next.cost);\n                    return;\n                }\n                // pruning \n                else if(next.cost > dist[next.x][next.y][next.dir]){\n                    continue;    \n                }\n                // 재귀\n                else{    \n                    dist[next.x][next.y][next.dir] = next.cost;\n                    dfs(next);\n                }\n            }\n        }\n    }\n    \n    private boolean inRange(int x, int y){\n        return (x >= 0 && x < board.length && y >= 0 && y < board.length);\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/경주로 건설.java","lines":84,"code":"import java.util.*;\n/*\n    시작점에서 도착점까지 가는 최소 비용 계산c\n    :(0, 0) -> (n-1, n-1)\n\n    알고리즘: 다익스트라, 우선순위유\n\n    비어있는 칸: 0\n    벽: 1\n    직선도로 개수: 전체칸수에서 -1 (개당 100원)\n    코너: 방향을 튼 개수 (개당 500원)\n    \n    1. 0, 0에서 출발한다\n    2. 다익스트라\n*/\nclass Solution {\n    static int[] dx = {-1, 0, 1, 0};\n    static int[] dy = {0, -1, 0, 1};\n    static int[][][] dist;\n    static int n;\n    static int minTotal;\n    static class Node implements Comparable<Node> {\n        int x;\n        int y;\n        int cost;\n        int direction;\n        \n        Node(int x, int y, int cost, int direction) {\n            this.x = x;\n            this.y = y;\n            this.cost = cost;\n            this.direction = direction;\n        }\n        \n        public int compareTo(Node o) {\n            return Integer.compare(this.cost, o.cost);\n        }\n    }\n    public int solution(int[][] board) {\n        minTotal = Integer.MAX_VALUE;\n        n = board.length;\n        \n        dijkstra(0, 0, board);        \n        \n        for(int i=0; i<4; i++) {\n            minTotal = Math.min(minTotal, dist[n-1][n-1][i]);\n        }\n        \n        return minTotal;\n    }\n    static void dijkstra(int x, int y, int[][] board) {\n        dist = new int[n][n][4];\n        for(int i=0; i<n; i++) {\n            for(int j=0; j<n; j++) { \n                Arrays.fill(dist[i][j], Integer.MAX_VALUE);\n            }\n        }\n        \n        PriorityQueue<Node> pq = new PriorityQueue<>();\n        pq.offer(new Node(x, y, 0, -1));\n        \n        while(!pq.isEmpty()) {\n            Node cur = pq.poll();\n            \n            for(int dir=0; dir<4; dir++) {\n                int nx = cur.x + dx[dir];\n                int ny = cur.y + dy[dir];\n                if(nx < 0 || nx >= n || ny < 0 || ny >= n) continue;\n                if(board[nx][ny] == 1) continue;\n                \n                int nCost = cur.cost + 100;\n                if(cur.direction != -1 && dir != cur.direction) {\n                    nCost += 500;\n                }\n                \n                if(nCost < dist[nx][ny][dir]) {\n                    dist[nx][ny][dir] = nCost; \n                    pq.offer(new Node(nx, ny, nCost, dir));\n                }\n            }\n        }\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/월경주로건설.java","lines":75,"code":"import java.util.ArrayDeque;\nimport java.util.Arrays;\n\nclass Solution {\n    \n    static int[] dx = {-1, 0, 1, 0};\n    static int[] dy = {0, 1, 0, -1};\n    static int[][] costs;\n\n    static class Road {\n        int r;\n        int c;\n        int dir;\n        int cost;\n        Road(int r, int c, int dir) {\n            this.r = r;\n            this.c = c;\n            this.dir = dir;\n        }\n    }\n\n    static boolean inRange(int size, int x, int y) {\n        return ((x>=0 && x < size) && (y >= 0 && y < size)) ? true : false;\n    }\n\n    public int solution(int[][] board) {\n        int answer = Integer.MAX_VALUE;\n\n        int size = board.length;\n        costs = new int[size][size];\n        for (int[] cost: costs) {\n            Arrays.fill(cost,Integer.MAX_VALUE);\n        }\n        \n        ArrayDeque<Road> deq = new ArrayDeque<>();\n\n        Road start = new Road(0, 0, 0);\n  \n        start.cost = 0;\n        costs[0][0] = start.cost;\n        deq.add(start);\n        \n        while (!deq.isEmpty()) {\n            Road road = deq.poll();\n            // 종료 조건: n-1, n-1 칸에 도달했을 경우\n            if (road.r == (size-1) && road.c == (size-1)) {\n                answer = Math.min(answer, road.cost);\n                continue;\n            }\n            \n            for (int i = 0; i < dx.length; i++){\n                int newR = road.r + dx[i], newC = road.c + dy[i];\n                // if (!inRange(size, newR, newC) || visited[i][newR][newC] || (board[newR][newC] == 1)) continue;\n                if (!inRange(size, newR, newC) || (board[newR][newC] == 1)) continue;\n                Road newRoad = new Road(newR, newC, i);\n                if (road.r == 0 && road.c == 0) {\n                    newRoad.cost = 100;\n                    deq.add(newRoad);\n                    costs[newR][newC] = newRoad.cost;\n                    continue;\n                }\n                if (road.dir == newRoad.dir) newRoad.cost = road.cost + 100;\n                else newRoad.cost = road.cost + 600;\n                \n                if (newRoad.cost > costs[newR][newC]) continue;\n\n                deq.add(newRoad);\n                costs[newR][newC] = newRoad.cost;\n\n            }\n        }\n\n        return answer;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":3,"variant":null,"source":"이승주/week3/경주로 건설.java","lines":65,"code":"import java.util.*;\n\nclass Solution {\n    static int N;\n    static int[][] map;\n    static int[] dx = {0,1,-1,0};\n    static int[] dy = {1,0,0,-1};\n    static int[][][] dist;\n    public int solution(int[][] board) {\n        this.N = board.length;\n        this.map = board;\n        \n        bfs(0,0);\n        int min = Integer.MAX_VALUE;\n        for(int i = 0; i < 4; i++){\n            min = Math.min(min, dist[N-1][N-1][i]);\n        }\n        return min;\n    }\n    \n    static void bfs(int x, int y){\n        dist = new int[N][N][4];\n        \n        for (int i = 0; i < N; i++) {\n            for (int j = 0; j < N; j++) {\n                Arrays.fill(dist[i][j], Integer.MAX_VALUE);\n    }\n}\n        dist[0][0][0] = 0;\n        dist[0][0][1] = 0;\n        \n        ArrayDeque<int[]> q = new ArrayDeque<>();\n        q.offer(new int[]{x,y,0});\n         q.offer(new int[]{x,y,1});\n        \n        while(!q.isEmpty()){\n            int[] current = q.poll();\n            \n            for(int dir = 0; dir < 4; dir++){\n                int nx = current[0] + dx[dir];\n                int ny = current[1] + dy[dir];\n                \n                \n                if(!inRange(nx,ny)) continue;\n                if(map[nx][ny] == 1) continue;\n                \n                int cost = dist[current[0]][current[1]][current[2]] + 100;\n\n                if(current[2] != dir){\n                    cost += 500;\n                }\n                \n                if(dist[nx][ny][dir] > cost){\n                    dist[nx][ny][dir] = cost;\n                    q.offer(new int[]{nx,ny,dir}); //dir은 지금 방향, current[2]는 이전 방향\n                }\n                \n            }\n        }\n    }\n    static boolean inRange(int x, int y){\n        return x >=0 && x < N && y >= 0 && y < N;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":3,"variant":"failed","source":"이승주/week3/경주로 건설 잘못된 풀이.java","lines":65,"code":"import java.util.*;\n\n/*\n    처음에 구현하였을 떄 예제 3번에서 에러가 남, 오른쪽 방향으로만 offer를 해서 밑으로 가는 경우에 +500원이 책정이 됨, 이를 막기 위해 밑의 방향도 offer를 해줌\n    처음엔 dist dist[nx][ny] > cost 방식으로 하여 (1,1)에서 700으로 값이 같아서 큐에 들어가지 않아 최적의 경로를 찾지 못함 -> dist업데이트 조건을 >=로 바꾸어 예제 그림과 같이 최적의 경로가 되게함. 이렇게 하니깐 테케 3개 틀리고 테케를 알 수가 없어서  gpt한테 힌트받음..\n*/\n\nclass Solution {\n    static int N;\n    static int[][] map;\n    static int[] dx = {0,1,-1,0};\n    static int[] dy = {1,0,0,-1};\n    static int[][] dist;\n    public int solution(int[][] board) {\n        this.N = board.length;\n        this.map = board;\n        \n        bfs(0,0);\n        \n        \n        return dist[N-1][N-1];\n    }\n    \n    static void bfs(int x, int y){\n        dist = new int[N][N];\n        \n        for(int i = 0; i < N; i++){\n        Arrays.fill(dist[i], Integer.MAX_VALUE);\n        }\n        dist[0][0] = 0;\n        \n        ArrayDeque<int[]> q = new ArrayDeque<>();\n        q.offer(new int[]{x,y,0});\n        q.offer(new int[]{x,y,1});\n        \n        while(!q.isEmpty()){\n            int[] current = q.poll();\n            \n            for(int dir = current[2]; dir < current[2]+4; dir++){\n                int nx = current[0] + dx[dir%4];\n                int ny = current[1] + dy[dir%4];\n                \n                \n                if(!inRange(nx,ny)) continue;\n                if(map[nx][ny] == 1) continue;\n                \n                int cost = dist[current[0]][current[1]] + 100;\n\n                if(current[2] != dir){\n                    cost += 500;\n                }\n                \n                if(dist[nx][ny] >= cost){\n                    dist[nx][ny] = cost;\n                    q.offer(new int[]{nx,ny,dir}); //dir은 지금 방향, current[2]는 이전 방향\n                }\n                \n            }\n        }\n    }\n    static boolean inRange(int x, int y){\n        return x >=0 && x < N && y >= 0 && y < N;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/72413","platform":"programmers","problemId":"72413","title":"합승 택시 요금","url":"https://school.programmers.co.kr/learn/courses/30/lessons/72413","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/합승 택시 요금.java","lines":97,"code":"/*\n전략.\n- 다익스트라 완전탐색\n- s, a, b에서 시작할때의 최단거리 배열을 다익스트라를 3번 돌려 얻음\n    - distS[i] : s → i까지의 최단 거리 == i → s까지의 최단 거리\n- 초기 결과 값은 s→a + s→b == a→s + b→s == distA[s] + distB[s]\n- 모든 합승 가능 지점 i에 대해(s 제외) s→i +i→a + i→b 의 요금을 찾아 결과 값과 비교 갱신\n    - s→i +i→a + i→b == s→i + a→i + b→i == distS[i] + distA[i] + dist[B]\n*/\n\nimport java.util.*;\n\nclass Solution {\n    static List<List<Node>> graph;\n    \n    class Node implements Comparable<Node>{\n        int target;\n        int cost;\n        \n        Node(int target, int cost){\n            this.target = target;\n            this.cost = cost;\n        }\n        \n        @Override\n        public int compareTo(Node n){\n            return Integer.compare(this.cost, n.cost);\n        }\n    }\n    \n    \n    public int solution(int n, int s, int a, int b, int[][] fares) {\n        // 인접 리스트 초기화\n        graph = new ArrayList<>();\n        for(int i = 0; i <= n; i++){\n            graph.add(new ArrayList<>());\n        }\n        for(int[] fee : fares){\n            graph.get(fee[0]).add(new Node(fee[1], fee[2]));\n            graph.get(fee[1]).add(new Node(fee[0], fee[2]));\n        }\n        \n        // s, a, b에서 시작할 때에 대한 최단거리 배열 찾기\n        int[] distS = new int[n + 1];\n        int[] distA = new int[n + 1];\n        int[] distB = new int[n + 1];\n        for(int i = 0; i <= n; i++){\n            distS[i] = Integer.MAX_VALUE;\n            distA[i] = Integer.MAX_VALUE;\n            distB[i] = Integer.MAX_VALUE;\n        }\n        dijkstra(s, distS);\n        dijkstra(a, distA);\n        dijkstra(b, distB);\n        \n        // 초기 결과값 : 합승 없이 각자 진행\n        int answer = distA[s] + distB[s];\n        \n        // 모든 노드 i를 순회\n        // s->i + a->i + b->i = i까지 합승하는 최소요금\n        // ** a->i == i->a 이므로 이렇게 계산해도 가능 **\n        for(int i = 1; i <= n; i++){\n            if(i == s){\n                continue;\n            }\n            int cost = distS[i] + distA[i] + distB[i];\n            answer = Math.min(answer, cost);\n        }\n        \n        return answer;\n    }\n    \n    private void dijkstra(int start, int[] dist){\n        dist[start] = 0;\n        PriorityQueue<Node> pq = new PriorityQueue<>();\n        pq.offer(new Node(start, 0));\n        \n        while(!pq.isEmpty()){\n            Node curr = pq.poll();\n            \n            // curr 노드의 누적 비용이 기존의 dist보다 크면 스킵 \n            if(curr.cost > dist[curr.target]){\n                continue;\n            }\n            \n            // 인접 노드를 순회\n            for(Node next : graph.get(curr.target)){\n                // 도달 비용이 기존보다 작다면 큐에 삽입\n                int cost = curr.cost + next.cost;\n                if(cost < dist[next.target]){\n                    dist[next.target] = cost;\n                    pq.offer(new Node(next.target, cost));\n                }\n            }\n        }\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/합승 택시 요금.java","lines":92,"code":"import java.util.*;\n/*\n    가중치 최단 거리 구하기\n        \n    알고리즘: 다익스트라, 우선순위큐, 인접리스트\n    \n    n: 지점의 개수 (정점의 개수)\n    s: 출발지점\n    a: A의 도착지점\n    b: B의 도착지점\n    fares[i] = {정점1, 정점2, 요금}\n\n    핵심: 갈라지는 지점 k를 정하면 총요금 = (s→k) + (k→a) + (k→b)\n    \n    1. fares로 양방향 가중치 인접리스트 생성\n    2. s, a, b 각각에서 다익스트라 → distS, distA, distB\n    3. k를 1~n 완전탐색하며 세 항 합의 최소 갱신\n*/\nclass Solution {\n    static List<Node>[] list;\n    static int N;\n    static int minNum;\n    static class Node implements Comparable<Node> {\n        int v;\n        int cost;\n        \n        Node(int v, int cost) {\n            this.v = v;\n            this.cost = cost;\n        }\n        \n        public int compareTo(Node o) {\n            return Integer.compare(this.cost, o.cost);\n        }\n    }\n    public int solution(int n, int s, int a, int b, int[][] fares) {\n        N = n;\n        minNum = Integer.MAX_VALUE; // 가중치 최소합\n        \n        list = new List[n+1];\n        for(int i=1; i<=n; i++) {\n            list[i] = new ArrayList<>();\n        }\n            \n        for(int i=0; i<fares.length; i++) {\n            int from = fares[i][0];\n            int to = fares[i][1];\n            int cost = fares[i][2];\n            list[from].add(new Node(to, cost));\n            list[to].add(new Node(from, cost));\n        }\n        \n        int[] distS = dijkstra(s);\n        int[] distA = dijkstra(a);\n        int[] distB = dijkstra(b);\n        \n        for(int k=1; k<=n; k++) {\n            if(minNum > distS[k] + distA[k] + distB[k]) {\n                minNum = distS[k] + distA[k] + distB[k];\n            }\n        }\n        \n        return minNum;\n    }\n    static int[] dijkstra(int start) {\n        int[] dist = new int[N+1];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[start] = 0;\n        \n        PriorityQueue<Node> pq = new PriorityQueue<>();\n        pq.add(new Node(start, 0));\n        \n        while(!pq.isEmpty()) {\n            // 비용이 가장 작은 노드를 꺼낸다\n            Node cur = pq.poll();\n            \n            // 이미 더 짧은 경로를 찾아둔 상태면 건너뜀\n            if(cur.cost > dist[cur.v]) continue;\n            \n            // 인접 노드를 돌면서 현재까지 비용 + 간선 비용이 기존 dist보다 작으면 갱신\n            for(Node next : list[cur.v]) {\n                int nCost = cur.cost + next.cost;\n                if(nCost < dist[next.v]) {\n                    dist[next.v] = nCost;\n                    pq.add(new Node(next.v, nCost));\n                }\n            }\n        }\n        return dist;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/합승택시요금.java","lines":67,"code":"import java.util.Arrays;\nimport java.util.PriorityQueue;\n\nclass Solution {\n\n    public static class Node {\n        int idx;\n        int cost;\n\n        public Node(int idx, int cost) {\n            this.idx = idx;\n            this.cost = cost;\n        }\n    }\n\n    public static int[] djikstra(int n, int s, int[][] imap) {\n        PriorityQueue<Node> pq = new PriorityQueue<>((o1, o2) -> Integer.compare(o1.cost, o2.cost));\n        pq.offer(new Node(s, 0));\n        boolean[] visited = new boolean[n + 1];\n        int[] dist = new int[n + 1];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[s] = 0;\n\n        while (!pq.isEmpty()) {\n            Node node = pq.poll();\n            visited[node.idx] = true;\n            // 1-4-1 해당 노드로부터 인접 노드 구하고 비용 갱신 (미방문 && 최적값 존재) 가능 시, pq에 offer한다.\n            for (int j = 1; j < n + 1; j++) {\n                if (imap[node.idx][j] != 0) {\n                    if (!visited[j] && ((imap[node.idx][j] + dist[node.idx]) <= dist[j])) {\n                        // 갱신\n                        // 1-4-1-1 비용 갱신 시, 경로를 기록한다.\n                        dist[j] = imap[node.idx][j] + dist[node.idx];\n                        pq.offer(new Node(j, dist[j]));\n                    }\n                }\n            }\n        }\n        return dist;\n    }\n\n    public int solution(int n, int s, int a, int b, int[][] fares) {\n        int answer = 0;\n        // 1. 다익스트라 구성\n        int[][] imap = new int[n + 1][n + 1];\n\n        for (int[] f : fares) {\n            imap[f[0]][f[1]] = f[2];\n            imap[f[1]][f[0]] = f[2];\n        }\n\n        int[] dist = djikstra(n, s, imap);\n        int[] distA = djikstra(n, a, imap);\n        int[] distB = djikstra(n, b, imap);\n\n        // 2. s에서 dest1,dest2 까지 가는 최저비용 구하기\n        answer = Integer.MAX_VALUE;\n        for (int k = 1; k <= n; k++) {\n            // 공유 노드 후보\n            if ((dist[k] != Integer.MAX_VALUE) && (distA[k] != Integer.MAX_VALUE) && (distB[k] != Integer.MAX_VALUE))\n                answer = Math.min(answer, distA[k] + distB[k] + dist[k]);\n        }\n        // 3. 두 경로 사이에 시작부터 중복 경로 구하고 해당 경로 비용 빼기\n        return answer;\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/합동택시요금.java","lines":70,"code":"import java.util.*;\n\nclass Solution {\n    static ArrayList<Edge>[] graph;\n    \n    static class Edge {\n        int to;\n        int cost;\n        \n        Edge(int to, int cost){\n            this.to = to;\n            this.cost = cost;\n        }\n    }\n    \n    public int solution(int n, int s, int a, int b, int[][] fares) {\n        int answer = Integer.MAX_VALUE;\n        graph = new ArrayList[n + 1];\n        \n        for(int i = 0; i <= n; i++){\n            graph[i] = new ArrayList<>();\n        }\n        \n        for(int i = 0; i < fares.length; i++){\n            int start = fares[i][0];\n            int end = fares[i][1];\n            int cost = fares[i][2];\n            \n            graph[start].add(new Edge(end, cost));\n            graph[end].add(new Edge(start, cost));\n        }\n        \n        int[] costS = dijkstra(s, n);\n        int[] costA = dijkstra(a, n);\n        int[] costB = dijkstra(b, n);\n        \n        for(int i = 1; i <= n; i++) {\n            answer = Math.min(answer, costS[i] + costA[i] + costB[i]);\n        }\n        \n        return answer;\n    }\n    \n    static int[] dijkstra(int start, int n) {\n        int[] dist = new int[n + 1];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        \n        PriorityQueue<Edge> pq = new PriorityQueue<>((o1, o2) -> Integer.compare(o1.cost, o2.cost));\n        \n        dist[start] = 0;\n        pq.offer(new Edge(start, 0));\n        \n        while(!pq.isEmpty()) {\n            Edge current = pq.poll();\n            \n            if(dist[current.to] < current.cost) continue;\n            \n            for(Edge next : graph[current.to]) {\n                if(dist[next.to] > dist[current.to] + next.cost) {\n                    \n                    dist[next.to] = dist[current.to] + next.cost;\n                    pq.offer(new Edge(next.to, dist[next.to]));\n                }\n            }\n        }\n        \n        return dist;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/77486","platform":"programmers","problemId":"77486","title":"다단계 칫솔 판매","url":"https://school.programmers.co.kr/learn/courses/30/lessons/77486","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/다단계 칫솔 판매.java","lines":92,"code":"/*\n전략\n- 시뮬레이션\n- 각 매출이 발생할 때마다 배분금을 정산\n    - 매출을 전체 정산한 후 배분금을 정산하면 절삭 오류 발생\n\n시행착오\n- 매출을 전체 정산한 후 배분금을 정산하도록 했는데 절삭 오류로 많이 틀림. \n  반례를 못찾아서 AI의 도움을 받음\n- ex) 한 사람에게 500 500이 들어오면 정산금이 0.5, 0.5가 되어 절삭되어야 하는데\n  이전 코드로 하면 총 매출이 1000이므로 정산금이 1이 되어 절삭되지 않음\n*/\n\nimport java.util.*;\n\nclass Solution {\n    class Seller{\n        String name;\n        int parent;\n        int money;\n        int plus;\n        \n        Seller(String name){\n            this.name = name;\n            this.parent = 0;\n            this.money = 0;\n            this.plus = 0;\n        }\n    }\n    \n    public int[] solution(String[] enroll, String[] referral, String[] seller, int[] amount) {   \n        // 판매원 초기화\n        List<Seller> sellers = new ArrayList<>();\n        // center 초기화 먼저\n        sellers.add(new Seller(\"center\"));\n        sellers.get(0).parent = -1;\n        \n        for(String e : enroll){\n            sellers.add(new Seller(e));\n        }\n        \n        // 추천인 초기화\n        for(int i = 0; i < referral.length; i++){\n            for(int j = 0; j < sellers.size(); j++){\n                if(sellers.get(j).name.equals(referral[i])){\n                    sellers.get(i + 1).parent = j;\n                }\n            }\n        }\n    \n        // 매출 초기화\n        for(int i = 0; i < seller.length; i++){\n            for(Seller s : sellers){\n                if(s.name.equals(seller[i])){\n                    // 배분금 정산\n                    // 매출 다 초기화 한 후 배분금 정산하면 절삭 오류 발생\n                    // ex) 1명에게 매출 500 500 가는 경우 0.5 0.5라 절삭 필요\n                    int money = amount[i] * 100;\n                    int give = money / 10;\n                    s.money += money - give;\n                    Seller parent = sellers.get(s.parent);\n                    \n                    // center의 자식까지만 반복\n                    while(parent.parent != -1){\n                        int nextGive = give / 10;\n                        give -= nextGive;\n                \n                        parent.plus += give;\n                        parent = sellers.get(parent.parent);\n                \n                        give = nextGive;\n                \n                        if(give == 0){\n                            break;\n                        }\n                    }\n            \n                    // center에게 배분금 정산\n                    parent.plus += give;\n                }\n            }\n        }\n        \n        int[] answer = new int[sellers.size() - 1];\n        for(int i = 1; i < sellers.size(); i++){\n            answer[i - 1] = sellers.get(i).money + sellers.get(i).plus;\n        }\n        \n        return answer;\n    }\n}","review":{"platform":"programmers","problemId":"77486","author":"junsoo","source":"김준수/week2/다단계 칫솔 판매.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["time-complexity","redundant-loop","nonstatic-inner-class","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(S · N + N²)","space":"O(N)"},"body":"# 다단계 칫솔 판매 (programmers/77486) — junsoo\n\n## 접근\n\n`Seller` 객체 리스트를 만들고 0번에 `center` 를 넣어 트리 루트로 삼는다.\n매출이 발생할 때마다 그 자리에서 추천인 체인을 따라 올라가며 정산한다.\n\n**분배 계산은 정확하다.** 특히 상단 주석의 이 통찰이 이 문제의 핵심이다.\n\n> 매출을 전체 정산한 후 배분금을 정산하면 절삭 오류 발생\n> ex) 한 사람에게 500 500이 들어오면 정산금이 0.5, 0.5가 되어 절삭되어야 하는데\n> 이전 코드로 하면 총 매출이 1000이므로 정산금이 1이 되어 절삭되지 않음\n\n10% 절삭은 **매출 건별로** 일어난다. 합쳐놓고 나중에 나누면 절삭 횟수가 달라진다.\n이걸 반례까지 만들어 정리해둔 건 리뷰 시간에 공유할 만하다.\n\n`center` 를 0번 노드로 두고 `parent == -1` 로 루트를 표시한 것도 깔끔하다.\n덕분에 \"추천인이 없는 경우\"를 따로 분기하지 않고 루프 조건 하나로 처리된다.\n\n## 개선점\n\n### 1. (치명) 이름을 찾을 때마다 전체를 훑는다 — 시간 초과 — `time-complexity`\n\n두 곳에서 선형 탐색을 한다.\n\n```java\n// 추천인 초기화 — N × N\nfor(int i = 0; i < referral.length; i++){\n    for(int j = 0; j < sellers.size(); j++){\n        if(sellers.get(j).name.equals(referral[i])){ ... }\n    }\n}\n\n// 매출 정산 — S × N\nfor(int i = 0; i < seller.length; i++){\n    for(Seller s : sellers){\n        if(s.name.equals(seller[i])){ ... }\n    }\n}\n```\n\n문제 제약은 `enroll` 최대 **10,000**, `seller` 최대 **100,000** 이다.\n\n| 위치 | 연산 수 |\n|---|---|\n| 추천인 초기화 | 10,000 × 10,001 ≈ **1억** |\n| 매출 정산 | 100,000 × 10,001 ≈ **10억** |\n\n두 번째가 특히 치명적이다. 문자열 `equals` 10억 번은 자바에서 확실히 시간 초과다.\n정답 로직인데 채점에서 떨어진다.\n\n이름 → 인덱스 맵을 한 번만 만들면 둘 다 O(1) 조회가 된다.\n\n```java\nMap<String, Integer> idx = new HashMap<>();\nfor (int i = 0; i < enroll.length; i++) idx.put(enroll[i], i + 1);  // 0번은 center\nidx.put(\"-\", 0);\n\n// 추천인 초기화 — N\nfor (int i = 0; i < referral.length; i++) sellers.get(i + 1).parent = idx.get(referral[i]);\n\n// 매출 정산 — S\nfor (int i = 0; i < seller.length; i++) {\n    Seller s = sellers.get(idx.get(seller[i]));\n    ...\n}\n```\n\n`\"-\"` 를 0번(center)으로 매핑해두면 기존 `parent == -1` 루트 표시와도 그대로 맞물린다.\n\n같은 문제를 푼 나머지 세 명은 전부 `HashMap<String, Integer>` 를 썼다. 비교해보면 좋다.\n\n### 2. (중요) 찾은 뒤에도 루프를 계속 돈다 — `redundant-loop`\n\n```java\nfor(Seller s : sellers){\n    if(s.name.equals(seller[i])){\n        ... // 정산\n    }\n}   // 찾았는데도 끝까지 돈다\n```\n\n이름은 유일하므로 정산 후 `break` 해야 한다. 1번을 적용하면 이 루프 자체가 사라지지만,\n선형 탐색을 유지하더라도 평균 절반의 비용은 줄어든다.\n\n### 3. (사소) `Seller` 는 `static` 중첩 클래스여야 한다 — `nonstatic-inner-class`\n\n```java\nclass Solution {\n    class Seller{ ... }   // 내부 클래스\n```\n\n지금은 `Seller` 인스턴스마다 바깥 `Solution` 참조를 숨겨서 들고 다닌다.\n`Seller` 는 `Solution` 의 상태를 전혀 쓰지 않으므로 `static class Seller` 가 맞다.\n판매원이 1만 명이면 그만큼의 불필요한 참조가 생긴다.\n\n### 4. (사소) `money` 와 `plus` 를 나눠 들 이유가 없다\n\n```java\ns.money += money - give;    // 본인 판매 몫\nparent.plus += give;        // 추천으로 받은 몫\n...\nanswer[i - 1] = sellers.get(i).money + sellers.get(i).plus;   // 결국 합친다\n```\n\n마지막에 더할 거라면 필드 하나면 된다. 둘로 나눠두면 \"어느 쪽에 더해야 하지?\" 를\n매번 판단해야 해서 실수 여지만 생긴다.\n\n## 복잡도\n\n- 시간: `O(S · N + N²)` — 1번을 고치면 `O((S + N) · D)`. D는 추천 체인 깊이로,\n  10% 절삭 때문에 금액이 빠르게 0이 되어 실질적으로 매우 얕다.\n- 공간: `O(N)` — 판매원 수만큼. 적정하다.\n\n## 요약\n\n절삭 오류를 스스로 찾아내고 반례까지 정리한 게 이 코드의 가장 큰 강점이다. 분배 로직은 맞다.\n문제는 이름 조회를 매번 선형 탐색으로 한다는 것 하나뿐이고, `HashMap` 한 줄이면 10억 연산이 10만으로 줄어든다."}},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/다단계 칫솔 판매.java","lines":76,"code":"/*\n    이익의 10% -> 추천인\n    \n    예외\n    : if (이익의 10%가 1원미만) -> x\n    : else 이익의 10% -> 추천인은\n    \n    알고리즘: DFS\n    \n    1. seller의 판매량을 hash로 만든다 Hash<seller, amount * 100>\n    2. roop\n     2.1 enroll[i]의 사람이 hash에 있으면\n      2.1.1 판매자의 추천인 있으면 판매량의 10%를 추천인으로 저장\n      2.1.2 판매자의 추천이 없으면 판매량 저장\n     2.2 enroll[i]의 사람이 hash에 없으면 continue\n*/\nclass Solution { // 판매원이름, 다른 판매원이름, 판매량 집계 데이터의 판매원 이름\n    static int[] result;\n    static Map<String, Integer> totalMoney; \n    static Map<String, Integer> sellMoney;\n    static int center = 0;\n    public int[] solution(String[] enroll, String[] referral, String[] seller, int[] amount) {\n        totalMoney = new HashMap<>();\n        sellMoney = new HashMap<>();\n        result = new int[enroll.length];\n\n        // seller의 판매량 <seller, amount * 100>\n        for(int i=0; i<seller.length; i++) {\n            sellMoney.put(seller[i], amount[i] * 100);\n        }\n        \n        for(int i=0; i<enroll.length; i++) {\n            if(!totalMoney.containsKey(enroll[i])) {\n               totalMoney.put(enroll[i], 0);\n            }\n        }\n        \n        for(int i=0; i<enroll.length; i++) {\n            if(sellMoney.containsKey(enroll[i])) {\n                recommend(referral[i], sellMoney.get(enroll[i]), enroll, referral);\n            }\n        }\n        System.out.println(\"최종답: \" + totalMoney);\n        return result;\n    }\n    /* \n        refferal의 추천인을 result에서 찾아 저장해주는 함수\n        referralName: 추천인\n        money: 판매자의 판매량\n    */\n    static void recommend(String referralName, int money, String[] enroll, String[] referral) {\n        System.out.println(\"referralName: \" + referralName + \" money: \" + money);\n        if(referralName.equals(\"-\")) {\n            // 이익의 10%가 1원이상 저장\n            // if(money * 0.1 >= 1) { \n            //     center += money * 0.1; \n            // }\n            // 판매량의 90%는 본인에게 저장\n            if(totalMoney.containsKey(referralName)) {\n                totalMoney.put(referralName, totalMoney.get(referralName) + money - money / 10);\n            }\n            return;\n        } else {\n            for(int i=0; i<enroll.length; i++) {\n                //System.out.println(\"referralName: \" + referralName);\n                if(enroll[i].equals(referralName)) {\n                    recommend(referral[i], money - money / 10, enroll, referral);\n                    if(sellMoney.containsKey(referralName)) {\n                        totalMoney.put(enroll[i], totalMoney.get(referralName) + money - money / 10);\n                    }\n                }\n            }\n        }\n    }\n}","review":{"platform":"programmers","problemId":"77486","author":"chanung","source":"안찬웅/week2/다단계 칫솔 판매.java","week":"2","compiles":"false","verdict":"wrong","tags":["missing-return","uninitialized-state","logic-edge-case","dead-code"],"generatedBy":"claude-code-local","generatedAt":"2026-08-16","complexity":{"time":"O(S · D · N)","space":"O(N)"},"body":"# 다단계 칫솔 판매 (programmers/77486) — chanung\n\n## 접근\n\n판매원별 판매액을 `sellMoney` 에 모으고, 판매가 있는 사람마다 추천인 체인을 따라 올라가며\n`totalMoney` 에 금액을 누적하는 재귀(`recommend`)로 풀었다.\n\n문제를 재귀로 본 것 자체는 맞다 — 추천인 관계는 트리고, 이익은 루트 방향으로만 흐른다.\n주석에 규칙과 단계를 먼저 적어두고 시작한 것도 좋다.\n\n다만 아래 이유로 현재는 **어떤 입력에도 0만 반환**한다.\n\n## 개선점\n\n### 1. (치명) 컴파일이 안 된다 — import 누락 — `missing-return`\n\n```\n안찬웅/week2/다단계 칫솔 판매.java:19: error: cannot find symbol\n    static Map<String, Integer> totalMoney;\n           ^  symbol: class Map\n```\n\n1행에 `import java.util.*;` 가 없다. 다른 파일(`베스트앨범.java`)에는 있으니 습관 문제는 아니고,\n이 파일만 빠진 것으로 보인다. 프로그래머스 채점기에서도 동일하게 막힌다.\n\n### 2. (치명) `result` 에 아무것도 넣지 않는다 — `uninitialized-state`\n\n`result` 는 세 곳에만 등장한다.\n\n```java\nstatic int[] result;                        // 18행 선언\nresult = new int[enroll.length];            // 25행 0으로 초기화\nreturn result;                              // 44행 그대로 반환\n```\n\n계산 결과는 전부 `totalMoney`(이름 → 금액)에 들어가는데, 그걸 `result`(인덱스 → 금액)로\n옮기는 코드가 없다. 그래서 `import` 를 고쳐 컴파일이 되더라도 **반환값은 항상 전부 0**이다.\n\n`enroll` 순서대로 옮겨주면 된다.\n\n```java\nfor (int i = 0; i < enroll.length; i++) {\n    result[i] = totalMoney.getOrDefault(enroll[i], 0);\n}\nreturn result;\n```\n\n### 3. (치명) 위로 올려보내는 금액과 본인 몫이 뒤바뀌었다 — `logic-edge-case`\n\n문제 규칙은 **본인이 90%를 갖고, 추천인에게 10%를 올려보낸다**. 그런데 67·69행은 반대다.\n\n```java\nrecommend(referral[i], money - money / 10, enroll, referral);   // 90%를 위로 올림\ntotalMoney.put(enroll[i], totalMoney.get(referralName) + money - money / 10);  // 추천인에게 90%를 줌\n```\n\n`money - money/10` 은 90%다. 이걸 추천인에게 주고, 90%를 다시 위로 올리고 있다.\n게다가 **판매 당사자는 한 번도 적립되지 않는다** — 최초 호출이 `recommend(referral[i], ...)`,\n즉 추천인 이름으로 시작하기 때문에 본인 몫을 넣을 자리가 없다.\n\n사람 기준으로 다시 쓰면 규칙이 그대로 드러난다.\n\n```java\n// person 이 money 를 벌었을 때의 분배\nstatic void distribute(String person, int money) {\n    int up = money / 10;                                 // 추천인 몫 10%\n    if (up < 1) {                                        // 1원 미만이면 분배 없음\n        totalMoney.merge(person, money, Integer::sum);   // 전액 본인\n        return;\n    }\n    totalMoney.merge(person, money - up, Integer::sum);  // 90% 본인\n    // 추천인이 없으면 up 은 본사 몫이라 그냥 버린다 (본인이 갖는 게 아니다)\n    if (!parent.get(person).equals(\"-\")) distribute(parent.get(person), up);\n}\n```\n\n> **`up < 1` 과 `추천인이 \"-\"` 를 한 조건으로 묶으면 안 된다.**\n> 추천인이 없어도 10%는 본사가 가져가므로 본인은 90%만 갖는다. 두 경우의 본인 몫이 다르다.\n> (이 리뷰의 초안이 그렇게 묶었다가, 무작위 2만 건 대조에서 19,842건이 어긋나 바로잡았다.)\n\n### 4. (중요) \"10%가 1원 미만이면 분배 중단\" 규칙이 빠졌다 — `logic-edge-case`\n\n54~57행에 주석으로 남아는 있는데 실제 코드에는 없다.\n\n```java\n// if(money * 0.1 >= 1) {\n//     center += money * 0.1;\n// }\n```\n\n이 조건이 없으면 금액이 작아져도 계속 위로 전파돼서 상위 판매원 금액이 과대 계상된다.\n위 3번 코드의 `if (up < 1)` 이 그 역할을 한다. 참고로 `money * 0.1` 은 `double` 이라\n부동소수점이 섞인다 — `money / 10` 정수 나눗셈으로 두는 편이 안전하다.\n\n### 5. (중요) 같은 판매원이 여러 번 팔면 마지막 것만 남는다 — `logic-edge-case`\n\n```java\nsellMoney.put(seller[i], amount[i] * 100);   // 29행\n```\n\n`seller` 배열에는 같은 이름이 여러 번 나올 수 있다. `put` 은 덮어쓰므로 앞의 판매가 사라진다.\n\n```java\nsellMoney.merge(seller[i], amount[i] * 100, Integer::sum);\n```\n\n### 6. (중요) 추천인을 찾을 때마다 `enroll` 전체를 훑는다\n\n```java\nfor(int i=0; i<enroll.length; i++) {\n    if(enroll[i].equals(referralName)) { ... }\n}\n```\n\n체인을 한 칸 올라갈 때마다 O(N) 선형 탐색이라 전체가 O(S · D · N)이 된다.\n이름 → 추천인 맵을 미리 만들어두면 한 칸 이동이 O(1)이다.\n\n```java\nMap<String, String> parent = new HashMap<>();\nfor (int i = 0; i < enroll.length; i++) parent.put(enroll[i], referral[i]);\n```\n\n이러면 `enroll`/`referral` 배열을 재귀 인자로 넘길 필요도 없어진다.\n\n### 7. (사소) 디버그 출력과 주석 처리된 코드가 남아 있다 — `dead-code`\n\n43행 `System.out.println(\"최종답: \" + totalMoney)`, 52행의 호출별 출력이 그대로 있다.\n재귀 호출마다 문자열을 만들어 찍기 때문에 시간 초과의 직접적인 원인이 될 수 있다.\n54~57행, 65행의 주석 처리된 코드도 함께 지우는 게 좋다.\n\n## 복잡도\n\n- 시간: `O(S · D · N)` — 판매 건수 S × 추천 체인 깊이 D × 이름 선형 탐색 N.\n  6번을 적용하면 `O(S · D)` 로 줄어든다.\n- 공간: `O(N)` — 맵 두 개. 적정하다.\n\n## 요약\n\n추천 관계를 재귀로 올라가는 뼈대는 맞다. 다만 `result` 를 채우지 않아 항상 0을 반환하고,\n본인 몫과 추천인 몫이 뒤바뀌어 있어 현재는 동작하지 않는다.\n\"사람이 돈을 벌면 90%를 갖고 10%를 위로 넘긴다\"는 한 문장을 그대로 함수 하나로 옮기면\n3·4번이 같이 해결되고, 추천인 맵(6번)까지 만들면 인자도 깔끔해진다."}},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/다단계칫솔판매.java","lines":51,"code":"package codetest;\n\nimport java.util.Map;\nimport java.util.HashMap;\nimport java.util.Map.Entry;\n\nclass Solution {\n    public int[] solution(String[] enroll, String[] referral, String[] seller, int[] amount) {\n        // 1. enroll 입력받고 이름별로 직원번호 mapping\n        Map<String, Integer> empNo = new HashMap<>();\n        for (int i = 0; i < enroll.length; i++){\n            empNo.put(enroll[i], i);\n        }\n        empNo.put(\"-\", enroll.length);\n        int[] account = new int[enroll.length];\n            // 1-1. referrel에 직원번호를 인덱스로 활용하여 추천인 확인\n        // 2. seller와 amount를 읽으며 center까지 이익 분배하기\n        for (int i = 0; i < seller.length; i++){\n            int publisherN = empNo.get(seller[i]);\n            int money = amount[i] * 100;\n            int pay = money / 10;\n\n            account[publisherN] += (money - pay);\n            \n            String recommender = referral[publisherN];\n            int recommenderN = empNo.get(recommender);\n            \n            if (pay < 1) {\n                account[recommenderN] += money;\n                continue;\n            }\n            \n            while (!recommender.equals(\"-\")) {\n                money = pay;\n                pay = money / 10;\n                if (pay < 1) {\n                    account[recommenderN] += money;\n                    break;\n                }\n                account[recommenderN] += (money - pay);\n                recommender = referral[recommenderN];\n                recommenderN = empNo.get(recommender);\n            \n            }\n            \n        }\n        \n        \n        return account;\n    }\n}","review":{"platform":"programmers","problemId":"77486","author":"seongil","source":"이성일/week2/다단계칫솔판매.java","week":"2","compiles":"true","verdict":"good","tags":["dead-code","logic-edge-case","good-complexity","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N + S · D)","space":"O(N)"},"body":"# 다단계 칫솔 판매 (programmers/77486) — seongil\n\n## 접근\n\n이름 → 인덱스 맵을 먼저 만들고, 매출 건마다 `while` 로 추천인 체인을 올라가며 정산한다.\n**네 명 중 가장 짧고(51줄) 복잡도도 가장 좋다.** 답도 맞다.\n\n핵심은 루프 안에서 두 변수를 굴리는 방식이다.\n\n```java\nwhile (!recommender.equals(\"-\")) {\n    money = pay;              // 아래에서 올라온 금액\n    pay = money / 10;         // 그중 위로 보낼 몫\n    if (pay < 1) {            // 10%가 1원 미만 -> 전액 본인\n        account[recommenderN] += money;\n        break;\n    }\n    account[recommenderN] += (money - pay);   // 90% 본인\n    recommender = referral[recommenderN];     // 한 칸 위로\n    recommenderN = empNo.get(recommender);\n}\n```\n\n`money` 는 \"이 사람이 받은 돈\", `pay` 는 \"위로 넘길 돈\". 이 두 줄만 보면 문제 규칙이 그대로 읽힌다.\n재귀 없이 반복문으로 끝낸 것도 스택 걱정이 없어 좋다.\n\n## 개선점\n\n### 1. (중요) 도달할 수 없는 분기인데, 도달하면 터진다 — `dead-code` · `logic-edge-case`\n\n```java\nif (pay < 1) {\n    account[recommenderN] += money;\n    continue;\n}\n```\n\n`while` 루프 **바깥**, 첫 정산 직후의 이 블록이다. 두 가지 문제가 겹쳐 있다.\n\n**(a) 지금은 절대 실행되지 않는다.** 문제 제약상 `amount` 는 1 이상 100 이하이므로\n`money = amount * 100 ≥ 100`, `pay = money / 10 ≥ 10` 이다. `pay < 1` 은 성립할 수 없다.\n\n**(b) 만약 실행되면 두 가지가 동시에 깨진다.**\n\n```java\naccount[publisherN] += (money - pay);   // pay=0 이므로 판매자가 전액 받음 (여기까지 맞음)\n...\naccount[recommenderN] += money;         // 추천인에게 '또' 전액을 준다 -> 이중 계산\n```\n\n게다가 판매자의 추천인이 `\"-\"` 이면 `recommenderN` 은 `enroll.length` 인데,\n`account` 의 크기가 정확히 `enroll.length` 라서 `ArrayIndexOutOfBoundsException` 이 난다.\n\n이 블록은 지우는 게 맞다. 루프 안의 `if (pay < 1)` 이 이미 그 역할을 정확히 하고 있다.\n\n### 2. (중요) `\"-\"` 를 배열 밖 인덱스로 매핑해둔 게 위태롭다 — `logic-edge-case`\n\n```java\nempNo.put(\"-\", enroll.length);      // account 의 유효 인덱스는 0 .. enroll.length-1\nint[] account = new int[enroll.length];\n```\n\n`\"-\"` 를 \"없는 사람\"의 표식으로 쓰면서 하필 **배열 바로 바깥**을 가리키게 했다.\n지금은 `while` 조건이 `\"-\"` 를 먼저 걸러내서 안전하지만, 1번 같은 분기가 하나만 더 생기면 바로 터진다.\n\n두 가지 중 하나를 권한다.\n\n- `-1` 로 두어 실수로 인덱싱하면 즉시 예외가 나게 한다 (조용히 넘어가지 않음)\n- 또는 김준수처럼 `account` 를 한 칸 크게 잡고 그 칸을 본사 몫으로 실제 사용한다\n\n### 3. (사소) `package codetest;` 가 남아 있다 — `dead-code`\n\n`SWEA1249.java` 와 같은 문제다. IDE 패키지가 딸려왔고, 제출본에는 들어갈 이유가 없다.\n저장소 경로(`이성일/week2/`)와도 맞지 않는다.\n\n### 4. (사소) 주석 번호와 코드 위치가 어긋난다 — `comment-noise`\n\n```java\n    // 1-1. referrel에 직원번호를 인덱스로 활용하여 추천인 확인\n// 2. seller와 amount를 읽으며 center까지 이익 분배하기\n```\n\n`1-1` 주석이 실제로 하는 일(`account` 배열 선언) 아래에 떠 있고 들여쓰기도 어긋나 있다.\n`referrel` 은 `referral` 오타다. 계획 단계 주석이 그대로 남은 것으로 보인다.\n\n## 복잡도\n\n- 시간: `O(N + S · D)` — 맵 생성 N, 매출마다 체인 깊이 D만큼. 10% 절삭 때문에 D는 매우 얕다.\n  네 명 중 가장 좋다.\n- 공간: `O(N)` — 맵 + 결과 배열. 적정하다.\n\n## 요약\n\n가장 짧고 가장 빠르다. `money`/`pay` 두 변수로 규칙을 그대로 표현한 게 좋다.\n고칠 것은 실행되지 않는 분기 하나를 지우는 것뿐이고, 그게 사라지면 `\"-\"` 인덱스 문제도 같이 안전해진다."}},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/다단계 칫솔 판매.java","lines":64,"code":"import java.util.*;\nclass Solution {\n    \n    static HashMap<String, Integer> map;\n    static String[] parent;\n    static int[] profit;\n    static int[] result;\n    public int[] solution(String[] enroll, String[] referral, String[] seller, int[] amount) {\n        this.parent = referral;\n        result = new int[enroll.length];\n        \n        profit = new int[amount.length];\n        \n        for(int i = 0; i < seller.length; i++){\n            profit[i] = amount[i]*100;\n        }\n        \n        map = new HashMap<>();\n        \n        for(int i = 0; i < enroll.length; i++){\n            map.put(enroll[i], i); // value값으로 인덱스를 저장\n        }\n        \n        for(int i = 0; i < seller.length; i++){\n            int index = map.get(seller[i]);\n            String person = parent[index];\n            if(person.equals(\"-\")){\n                result[index] += profit[i] - profit[i]/10;\n            }else{\n                dfs(seller[i],person,profit[i]); //금액을 나눠주는 사람, 금액을 받아야하는 사람, 전체 금액\n            }\n        }\n        \n        return result;\n        \n        \n    }\n    \n    static void dfs(String from, String to, int cost){\n        \n        int money = cost / 10;\n        if(money < 1){\n            int index = map.get(from);\n            result[index] += cost;\n            return;\n        }else{\n            int fromIndex = map.get(from);\n            result[fromIndex] += cost - money;\n            \n             int toIndex = map.get(to);\n            \n            if(!(parent[toIndex].equals(\"-\"))){\n                dfs(to,parent[toIndex],money);\n            }else{\n                result[toIndex] += money - money/10;\n                return;\n            }\n        }\n        return;\n        \n        \n    }\n}","review":{"platform":"programmers","problemId":"77486","author":"seungjoo","source":"이승주/week2/다단계 칫솔 판매.java","week":"2","compiles":"true","verdict":"needs-fix","tags":["uninitialized-state","duplicate-code","dead-code","good-complexity"],"generatedBy":"claude-code-local","generatedAt":"2026-08-17","complexity":{"time":"O(N + S · D)","space":"O(N + S)"},"body":"# 다단계 칫솔 판매 (programmers/77486) — seungjoo\n\n## 접근\n\n이름 → 인덱스 맵을 만들고, 매출마다 `dfs(주는 사람, 받는 사람, 금액)` 재귀로 체인을 올라간다.\n답은 맞고 복잡도도 좋다.\n\n인자 이름에 주석으로 역할을 달아둔 게 읽기에 도움이 된다.\n\n```java\ndfs(seller[i], person, profit[i]); //금액을 나눠주는 사람, 금액을 받아야하는 사람, 전체 금액\n```\n\n`parent` 배열(= `referral`)로 한 칸 위를 찾는 구조도 명확하다.\n\n## 개선점\n\n### 1. (중요) 상태를 `static` 으로 들고 있다 — `uninitialized-state`\n\n```java\nstatic HashMap<String, Integer> map;\nstatic String[] parent;\nstatic int[] profit;\nstatic int[] result;\n\npublic int[] solution(...) {\n    this.parent = referral;   // static 필드를 this 로 대입\n```\n\n두 가지가 문제다.\n\n**(a) `this.parent = referral`** — `parent` 는 `static` 인데 인스턴스 참조로 대입하고 있다.\n컴파일은 되지만 \"인스턴스마다 따로\"라는 오해를 부른다. 실제로는 클래스 전체가 공유한다.\n\n**(b) 채점기가 같은 JVM에서 여러 번 호출하면 이전 호출의 값이 남는다.**\n지금은 `solution` 진입 시 네 개 모두 새로 대입해서 우연히 안전하지만,\n필드 하나만 초기화를 빠뜨려도 **앞 테스트케이스의 결과가 다음 케이스에 섞여 들어간다.**\n찾기 매우 어려운 종류의 버그다.\n\n`dfs` 에 필요한 것만 인자로 넘기거나, 필드를 쓰더라도 `static` 을 떼고 인스턴스 필드로 두는 게 안전하다.\n\n### 2. (중요) \"90% 갖고 10% 올려보낸다\"가 세 군데 흩어져 있다 — `duplicate-code`\n\n같은 규칙이 세 곳에 다른 모양으로 적혀 있다.\n\n```java\n// (1) solution — 판매자의 추천인이 \"-\" 인 경우\nresult[index] += profit[i] - profit[i]/10;\n\n// (2) dfs — 10%가 1원 미만인 경우\nresult[map.get(from)] += cost;\n\n// (3) dfs — 받는 사람의 추천인이 \"-\" 인 경우\nresult[toIndex] += money - money/10;\n```\n\n세 개가 다 맞다. 다만 규칙이 바뀌면 세 군데를 모두 고쳐야 하고 하나만 놓쳐도 조용히 틀린다.\n**\"사람\"을 기준으로 한 함수로 통일**하면 분기가 둘로 줄어든다.\n\n```java\n// person 이 money 를 벌었을 때\nstatic void distribute(String person, int money) {\n    int up = money / 10;\n    int idx = map.get(person);\n    if (up < 1) {                      // 10%가 1원 미만 -> 분배 없음, 전액 본인\n        result[idx] += money;\n        return;\n    }\n    result[idx] += money - up;         // 90% 본인\n    // 추천인이 없으면 up 은 본사 몫이라 그냥 버린다\n    if (!parent[idx].equals(\"-\")) distribute(parent[idx], up);\n}\n\n// 호출부\ndistribute(seller[i], amount[i] * 100);\n```\n\n> **주의 — 두 종료 조건을 묶으면 안 된다.**\n> `up < 1` 이면 본인이 **전액**을 갖지만, 추천인이 `\"-\"` 일 때는 본인이 **90%만** 갖고\n> 나머지 10%는 본사로 간다. 지금 코드의 (1)·(3)이 서로 다른 이유가 이것이다.\n> 이 리뷰의 초안은 두 조건을 `||` 로 묶었다가 무작위 2만 건 대조에서 19,842건이 어긋나 바로잡았다.\n> 위 코드는 같은 방식으로 재검증해 이성일·이승주 구현과 **0건 불일치**를 확인했다.\n\n`solution` 쪽 `if/else` 는 사라지고, `dfs` 의 세 갈래는 두 갈래로 준다.\n\n현재 구조가 복잡해진 이유는 `dfs(from, to, cost)` 가 **두 사람을 동시에** 다루기 때문이다.\n한 사람만 다루면 \"받는 사람의 추천인이 `-` 인가\"를 미리 볼 필요가 없어진다.\n\n### 3. (사소) 도달하지 않는 `return` 이 있다 — `dead-code`\n\n```java\n    } else {\n        result[toIndex] += money - money/10;\n        return;              // else 블록 끝 -> 불필요\n    }\n}\nreturn;                       // 메서드 끝 (void) -> 불필요\n```\n\n`void` 메서드의 마지막 `return;` 과 블록 끝 `return;` 은 지워도 동작이 같다.\n\n### 4. (사소) `profit` 배열은 필요 없다\n\n```java\nprofit = new int[amount.length];\nfor(int i = 0; i < seller.length; i++){\n    profit[i] = amount[i]*100;\n}\n```\n\n`amount[i] * 100` 을 쓰는 곳이 한 군데뿐이라 배열로 미리 만들 이유가 없다.\n크기를 `amount.length` 로 잡고 `seller.length` 로 채우는 것도 어긋나 있다\n(제약상 두 값이 같아서 지금은 문제없다).\n\n## 복잡도\n\n- 시간: `O(N + S · D)` — 맵 생성 N, 매출마다 체인 깊이 D. 좋다.\n- 공간: `O(N + S)` — `profit` 을 없애면 `O(N)`.\n\n## 요약\n\n접근과 복잡도는 좋다. 다만 `dfs` 가 \"주는 사람\"과 \"받는 사람\"을 함께 들고 다니면서\n같은 규칙이 세 군데로 갈라졌다. 사람 하나를 기준으로 재귀를 다시 쓰면 세 분기가 둘로 줄고,\n`static` 상태도 같이 줄일 수 있다."}}],"teamFeedback":null},{"key":"programmers/81303","platform":"programmers","problemId":"81303","title":"표 편집","url":"https://school.programmers.co.kr/learn/courses/30/lessons/81303","weeks":[3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/표 편집.java","lines":115,"code":"/*\n전략\n- 링크드 리스트 구현\n    - java의 LinkedList, ArrayList는 각 아이템마다 Node를 생성하고 조작해야 해서 remove, insert 작업이 오래 걸림\n    - 자신의 앞 뒤를 가리키는 더블 링크드 리스트를 배열 2개로 만들어서 더 빠르게 가능\n- 되돌리기는 Stack으로\n    - 되돌리기 하면 Stack을 pop해서 기존의 idx를 하나 뒤로 밀고 들어감\n        - 선택 행이 되돌리기한 행보다 idx가 큰 경우 idx + 1해야 함\n    - 삭제하면 뒤 idx를 자기 쪽으로 당겨오고 Stack에 push함\n        - 선택 행이 삭제 행보다 idx가 큰 경우 idx - 1 해야 함\n\n시행착오\n- Chart 클래스를 구현해서 멤버 변수와 멤버 함수로 모든 로직 구성\njava.util의 클래스를 사용하니 시간초과 발생함\n    - Chart 내부에 ArrayList로 관리. remove나 insert로 로직 구현\n- AI 도움 받음(링크드 리스트 직접 구현하는 아이디어)\n*/\nimport java.util.*;\n\nclass Solution {    \n    static int[] frontPointers;\n    static int[] backPointers;\n    static int current;\n    static Deque<Integer> stack;\n    \n    public String solution(int n, int k, String[] cmd) {\n        current = k;\n        stack = new ArrayDeque<>(); \n        \n        // 각 행의 이전 행, 다음 행의 인덱스를 가리키는 포인터 배열\n        frontPointers = new int[n];\n        backPointers = new int[n];\n        for(int i = 0; i < n; i++){\n            frontPointers[i] = i - 1;\n            backPointers[i] = i + 1;\n        }\n        frontPointers[0] = -1; // 가장 위 행의 위는 없음\n        backPointers[n - 1] = -1; // 가장 아래 행의 아래는 없음\n        \n        for(String s : cmd){\n            StringTokenizer st = new StringTokenizer(s);\n            String curr = st.nextToken();\n            \n            switch(curr){\n                case \"U\":\n                    int uNum = Integer.parseInt(st.nextToken());\n                    while(uNum--  > 0){\n                        current = frontPointers[current];\n                    }\n                    break;\n                case \"D\":\n                    int dNum = Integer.parseInt(st.nextToken());\n                    while(dNum--  > 0){\n                        current = backPointers[current];\n                    }\n                    break;\n                case \"C\":\n                    delete();\n                    break;\n                case \"Z\":\n                    recover();\n                    break;\n            }\n        }\n        \n        // 결과값을 전부 O로 초기화\n        StringBuilder sb = new StringBuilder();\n        for(int i = 0; i < n; i++){\n            sb.append(\"O\");\n        }\n        \n        // stack에 남아있는 idx들은 삭제되어있는 idx이므로 갱신\n        while(!stack.isEmpty()){\n            int del = stack.pop();\n            \n            sb.setCharAt(del, 'X');\n        }\n        \n        return sb.toString();\n    }\n    \n    private void delete(){\n        // 현재 행을 스택에 추가\n        stack.push(current);\n        \n        // current는 건드리지 않고, 앞 뒤 행끼리만 연결\n        if(frontPointers[current] != -1){\n            backPointers[frontPointers[current]] = backPointers[current];\n        }\n        \n        if(backPointers[current] != -1){\n            frontPointers[backPointers[current]] = frontPointers[current];    \n        }\n        \n        // 아래 행이 있으면 아래 행으로 마지막 행이라 아래 행이 없으면 위 행으로 이동\n        if(backPointers[current] != -1){\n            current = backPointers[current];\n        } else {\n            current = frontPointers[current];\n        }\n    }\n    \n    private void recover(){\n        int rec = stack.pop();\n        \n        // 앞 뒤 행을 다시 연결\n        if(frontPointers[rec] != -1){\n            backPointers[frontPointers[rec]] = rec;\n        }\n        \n        if(backPointers[rec] != -1){\n            frontPointers[backPointers[rec]] = rec;\n        }\n    }\n}","review":null},{"author":"junsoo","authorName":"김준수","week":3,"variant":"failed","source":"김준수/week3/표 편집 실패.java","lines":80,"code":"\nimport java.util.*;\n\nclass Solution {\n    class Chart{\n        int curr;\n        List<Integer> names;\n        Deque<int[]> stack;\n        \n        Chart(int n, int curr){\n            this.curr = curr;\n            names = new ArrayList<>();\n            stack = new ArrayDeque<>();\n            \n            for(int i = 0; i < n; i++){\n                names.add(i);\n            }\n        }\n        \n        public void delete(){\n            int del = names.get(curr);\n            names.remove(curr);\n            stack.push(new int[]{curr, del});\n            \n            // 마지막 행이면\n            if(curr == names.size()){\n                curr--;\n            }\n        }\n        \n        public void recover(){\n            int[] item = stack.pop();\n            names.add(item[0], item[1]);\n            \n            // 선택 행이 복구 행보다 뒤에 있으면\n            if(curr >= item[0]){\n                curr++;\n            }\n        }\n    }\n    \n    public String solution(int n, int k, String[] cmd) {\n        Chart chart = new Chart(n, k);\n        \n        for(String c : cmd){\n            StringTokenizer st = new StringTokenizer(c);\n            String curr = st.nextToken();\n            \n            switch(curr){\n                case \"U\":\n                    int uNum = Integer.parseInt(st.nextToken());\n                    chart.curr -= uNum;\n                    break;\n                case \"D\":\n                    int dNum = Integer.parseInt(st.nextToken());\n                    chart.curr += dNum;\n                    break;\n                case \"C\":\n                    chart.delete();\n                    break;\n                case \"Z\":\n                    chart.recover();\n                    break;\n            }\n        }\n        \n        StringBuilder sb = new StringBuilder();\n        \n        for(int i = 0; i < n; i++){\n            if(chart.names.contains(i)){\n                sb.append(\"O\");\n            }\n            else{\n                sb.append(\"X\");\n            }\n        }\n        \n        return sb.toString();\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/표 편집","lines":75,"code":"import java.util.*;\n/*\n    표의 행을 선택,삭제,복구하는 프로그램\n    :처음 표와 비교해서 삭제되었으면 X 아니면 O\n    \n    알고리즘: 시뮬레이션, 배열\n    \n    1. 프로그램\n     1.1 U X : 현재 선택된 행에서 X칸 위에 있는 행 선택\n     1.2 D X : 현재 선택된 행에서 X칸 아래에 있는 행 선택\n     1.3 C   : 현재 선택된 행 삭제 후, 바로 아래 행 선택\n               만약 마지막행이면 삭제된 후 마지막행 선택\n     1.4 z   : 가장 최근에 삭제된 행을 원래대로 복구. 단, 현재 선택된 행은 바뀌지 않습니다.\n\n    n: 표의 행 개수\n    k: 처음에 선택된 행의 위치\n    cmd: 명령어\n*/\nclass Solution {\n    public String solution(int n, int k, String[] cmd) {\n        String answer = \"\";\n        List<Integer> table = new ArrayList<>();\n        Deque<Integer> removeTable = new ArrayDeque<>(); //삭제된 행 저장하는 배열\n        for(int i=0; i<n; i++) table.add(i);\n        \n        int cursor = k;\n        for(int i=0; i<cmd.length; i++) {\n            System.out.println(table);\n            System.out.println(\"cursor: \" + cursor + \" cmd: \" + cmd[i] + \" table: \" + table.size());\n            String[] str = cmd[i].split(\" \");\n            String command = str[0];\n            int move = 0;\n            if(str.length >= 2) { \n                move = Integer.parseInt(str[1]); \n            }\n            \n            if(command.equals(\"U\")) {\n                cursor -= move;\n            } else if(command.equals(\"D\")) {\n                cursor += move;\n            } else if(command.equals(\"C\")) {\n                // 현재 행 삭제\n                table.remove(cursor);\n                if(table.size() <= cursor) {\n                    cursor = table.size()-1;\n                }\n                // 삭제된 행번호(인덱스 저장)\n                removeTable.offer(cursor);\n                // 바로 아래 행 선택\n            } else if(command.equals(\"Z\")) {\n                // 가장 최근에 삭제된 행을 원래대로 복구\n                // 현재 선택된 행은 바뀌지 않습니다\n                int cur = removeTable.pollLast();\n                table.add(cur, cur);\n            }\n        }\n        System.out.println(table);\n        System.out.println(\"table: \" + table.size());\n        \n        // 비교 후, 다르면 X 맞으면 O저장\n        StringBuilder sb = new StringBuilder();\n        for(int j=0; j<n; j++) {\n            if(table.contains(j)) {\n                sb.append(\"0\");\n            } else {\n                sb.append(\"X\");\n            }\n        }\n        \n        answer = sb.toString();\n        \n        return answer;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":null,"source":"이성일/week3/표편집.java","lines":60,"code":"import java.util.ArrayList;\nimport java.util.LinkedList;\nimport java.util.List;\n\nclass Solution {\n\n    static List<Node> ll;\n    static List<Node> deq;\n\n    static class Node {\n        int prev;\n        int val;\n        int next;\n\n        Node(int val) {\n            this.val = val;\n        }\n    }\n\n    public String solution(int n, int k, String[] cmd) {\n        String answer = \"\";\n        ll = new LinkedList<>();\n        deq = new ArrayList<>();\n\n        for (int i = 0; i < n; i++) {\n            ll.add(new Node(i));\n        }\n        for (String c : cmd) {\n            char cc = c.charAt(0);\n            if (cc == 'U') {\n                int x = Integer.parseInt(c.split(\" \")[1]);\n                k = k - x;\n            } else if (cc == 'D') {\n                int x = Integer.parseInt(c.split(\" \")[1]);\n                k = k + x;\n            } else if (cc == 'C') {\n                Node removedNode = ll.remove(k);\n                removedNode.prev = k - 1;\n                deq.add(removedNode);\n            } else {\n                Node restoreNode = deq.removeLast();\n                ll.add(restoreNode.prev + 1, restoreNode);\n            }\n        }\n\n        String x = \"X\";\n        String ox = x.repeat(n);\n        char[] oxArray = ox.toCharArray();\n\n        for (Node node : ll) {\n            oxArray[node.val] = 'O';\n        }\n        for (char chart : oxArray) {\n            answer += chart;\n        }\n\n        return answer;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/87694","platform":"programmers","problemId":"87694","title":"아이템 줍기","url":"https://school.programmers.co.kr/learn/courses/30/lessons/87694","weeks":[2],"entries":[{"author":"junsoo","authorName":"김준수","week":2,"variant":null,"source":"김준수/week2/아이템 줍기.java","lines":91,"code":"/*\n전략\n- 완전탐색 백트래킹\n- 격자 최대 크기는 20 - 20 - 20이니까 60x60으로 만들기\n- 열쇠의 [M-1][M-1]이 자물쇠의 [0][0]에 닿는 시점부터 우측으로 열쇠를 옮김\n    - 열쇠의 [M-1][0]이 자물쇠의 [0][N-1]에 닿는 시점까지 옮김\n    - 그 후 자물쇠의 행을 +1 하여 다시 좌→우 이동 반복\n    - 열쇠가 회전 가능한 4 모양에 대해 모두 시도\n- 만약 각 시도 중 fit한 경우가 생기면 즉시 종료 후 true 반환\n- 전체 시도해도 fit한 경우 없었으면 false 반환\n*/\nclass Solution {\n    static int[][][] keys;\n    static int[][] lock;\n    \n    public boolean solution(int[][] key, int[][] l) {\n        boolean answer = false;\n        \n        lock = l;\n        \n        // 키의 회전 모양 초기화\n        keys = new int[4][key.length][key.length];\n        keys[0] = key; \n        for(int i = 1; i < 4; i++){\n            int[][] newKey = new int[key.length][key.length];\n            for(int j = 0; j < key.length; j++){\n                for(int k = 0; k < key.length; k++){\n                    newKey[j][k] = keys[i - 1][k][key.length - j - 1];\n                }\n            }\n            keys[i] = newKey;\n        }\n        \n        // board 초기화\n        int[][] board = new int[60][60];\n        int[][] keyBoard = new int[60][60];\n        for(int i = 20; i < 20 + lock.length; i++){\n            for(int j = 20; j < 20 + lock.length; j++){\n                board[i][j] = lock[i - 20][j - 20];\n                keyBoard[i][j] = lock[i - 20][j - 20];\n            }\n        }\n        \n        // keyboard에 key 배치\n        for(int i = 0; i < 4; i++){\n            for(int j = 20 - key.length; j <= 20 + lock.length; j++){\n                for(int k = 20 - key.length; k <= 20 + lock.length; k++){\n                    // keyBoard에 key 끼워넣기\n                    makeKeyBoard(keyBoard, i, j, k);\n                    \n                    // keyBoard가 lock의 모든 홈을 채우는지 검사\n                    if(isFull(keyBoard)){\n                        answer = true;\n                    }\n                    \n                    // keyBoard 복구\n                    for(int a = 0; a < 60; a++){\n                        for(int b = 0; b < 60; b++){\n                            keyBoard[a][b] = board[a][b];\n                        }\n                    }\n                }\n            }\n        }\n        \n        return answer;\n    }\n    \n    // lock만 있는 keyBoard에 key를 겹쳐서 리턴\n    private void makeKeyBoard(int[][] board, int keyIndex, int x, int y){\n        for(int i = x; i < x + keys[0][0].length; i++){\n            for(int j = y; j < y + keys[0][0].length; j++){\n                board[i][j] += keys[keyIndex][i - x][j - y];\n            }\n        }\n    }\n    \n    // lock의 모든 홈이 채워졌는지\n    private boolean isFull(int[][] board){\n        for(int i = 20; i < 20 + lock.length; i++){\n            for(int j = 20; j < 20 + lock.length; j++){\n                // 홈이 비어있거나, 돌기가 겹쳤거나\n                if(board[i][j] == 0 || board[i][j] == 2){\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":2,"variant":null,"source":"안찬웅/week2/아이템줍기.java","lines":18,"code":"import java.util.*;\n/*\n    캐릭터가 아이템으로 이동하는 최단거리 구하기\n    :(characterX, characterY) -> (itemX, itemY)\n    \n    알고리즘: BFS\n    \n    1. 직사각형의 모든 점들을 찍는다.\n    2. 지나가는곳이 어딘지 어케알지\n    3. BFS로 돌리면서 최단거리 구하기\n*/\nclass Solution {\n    public int solution(int[][] rectangle, int characterX, int characterY, int itemX, int itemY) {\n      System.out.println(\"모르겠습니다..\");\n      System.out.println(\"나중에 다시 도전하겠습니다.\");\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":2,"variant":null,"source":"이성일/week2/아이템줍기.java","lines":84,"code":"import java.util.ArrayDeque;\n\nclass Solution {\n\n    public static int[][] board = new int[51][51];\n    // BFS용 4방향\n    static int[] dx = {-1, 0, 1, 0};\n    static int[] dy = {0, 1, 0, -1};\n\n// 테두리 판별용 8방향\n    static int[] checkDx = {-1,-1,0,1,1,1,0,-1};\n    static int[] checkDy = {0,1,1,1,0,-1,-1,-1};\n\n    static class Point {\n        int r;\n        int c;\n        int moving;\n        Point(int r, int c, int moving) {\n            this.r = r;\n            this.c = c;\n            this.moving = moving;\n        }\n    }\n    public static boolean inRange(int n, int x, int y) {\n        return ((x >= 0 && x < n) && (y >= 0 && y < n)) ? true : false;\n    }\n\n    public int solution(int[][] rectangle, int characterX, int characterY, int itemX, int itemY) {\n        int answer = Integer.MAX_VALUE;\n        // 1. rectangles 기준으로 테두리 제외 모두 색칠하기\n        for (int[] rec: rectangle){\n            for (int i = (rec[0] + 1); i < rec[2]; i++ ){\n                for (int j = (rec[1] + 1); j < rec[3]; j++){\n                    board[i][j] = -1;\n                }\n            }\n        }\n        // 2. 전체 순회 4방향에 칠한 부분(테두리)있으면 제외, 칠해진 부분 제외, 모든 영역 칠하기\n        for (int i = 0; i < board.length; i++){\n            for (int j = 0; j < board[0].length; j++) {\n                if (board[i][j] == -1) continue;\n                boolean flag = true;\n                for (int d = 0; d < checkDx.length; d++) {\n                    int x = i + checkDx[d], y = j + checkDy[d];\n                    if (!inRange(board.length, x, y)) continue;\n                    if (board[x][y] == -1) {\n                        flag = false;\n                        break;\n                        // 칠하면 안되는 부분 (테두리임)\n                    }\n                }\n                if (flag) board[i][j] = -2;\n            }\n        }\n        // 3. 이후, 시작점에서 4방향 bfs로 안칠해진 부분 기준으로 순회 시작\n        ArrayDeque<Point> deq = new ArrayDeque<>();\n        deq.add(new Point(characterX, characterY,0));\n        board[characterX][characterY] = 1;\n        while (!deq.isEmpty()) {\n            Point p = deq.poll();\n            int r = p.r;\n            int c = p.c;\n            int move = p.moving; // 시작지점부터 이 포인트까지 몇번 움직였는 지를 나타내는 변수\n            if ((r==itemX) && (c==itemY)) {\n                // 도착했다면 값 갱신\n                answer = Math.min(answer, move);\n                break;\n            } \n            for (int i = 0; i < dx.length; i++) {\n                int x = r + dx[i], y = c + dy[i];\n                if (!inRange(board.length, x, y)) continue;\n                if (board[x][y] !=  0) continue; // 칠해져 있거나 방문했거나\n                // if (board[x][y] == 1) continue; // 방문노드\n                deq.add(new Point(x,y,move+1));\n                board[x][y] = 1;\n            }\n        }\n            \n        \n        return answer;\n\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":2,"variant":null,"source":"이승주/week2/아이템 줍기.java","lines":89,"code":"import java.util.*;\n\nclass Solution {\n\n    static int[][] map = new int[102][102];\n    static int[][] dist = new int[102][102];\n\n    static int[] dx = {1, -1, 0, 0};\n    static int[] dy = {0, 0, 1, -1};\n\n    public int solution(int[][] rectangle,\n                        int characterX, int characterY,\n                        int itemX, int itemY) {\n\n        for (int[] r : rectangle) {\n\n            int x1 = r[0] * 2;\n            int y1 = r[1] * 2;\n            int x2 = r[2] * 2;\n            int y2 = r[3] * 2;\n\n            for (int x = x1; x <= x2; x++) {\n                for (int y = y1; y <= y2; y++) {\n                    map[x][y] = 1;\n                }\n            }\n        }\n\n        // 2. 사각형 내부를 0으로 지움, 테두리만 1로 남김\n        for (int[] r : rectangle) {\n\n            int x1 = r[0] * 2;\n            int y1 = r[1] * 2;\n            int x2 = r[2] * 2;\n            int y2 = r[3] * 2;\n\n            for (int x = x1 + 1; x < x2; x++) {\n                for (int y = y1 + 1; y < y2; y++) {\n                    map[x][y] = 0;\n                }\n            }\n        }\n\n    \n        characterX *= 2;\n        characterY *= 2;\n        itemX *= 2;\n        itemY *= 2;\n\n        return bfs(characterX, characterY, itemX, itemY) / 2;\n    }\n\n    static int bfs(int startX, int startY, int itemX, int itemY) {\n\n        ArrayDeque<int[]> q = new ArrayDeque<>();\n\n        q.offer(new int[]{startX, startY});\n        dist[startX][startY] = 1;\n\n        while (!q.isEmpty()) {\n\n            int[] cur = q.poll();\n            int x = cur[0];\n            int y = cur[1];\n\n            if (x == itemX && y == itemY) {\n                return dist[x][y] - 1;\n            }\n\n            for (int d = 0; d < 4; d++) {\n\n                int nx = x + dx[d];\n                int ny = y + dy[d];\n\n                // 테두리가 아니면 못 감\n                if (map[nx][ny] != 1) continue;\n\n                // 이미 방문했다면 못 감\n                if (dist[nx][ny] != 0) continue;\n\n                dist[nx][ny] = dist[x][y] + 1;\n                q.offer(new int[]{nx, ny});\n            }\n        }\n\n        return -1;\n    }\n}","review":null}],"teamFeedback":null},{"key":"programmers/92343","platform":"programmers","problemId":"92343","title":"양과 늑대","url":"https://school.programmers.co.kr/learn/courses/30/lessons/92343","weeks":[3],"entries":[{"author":"junsoo","authorName":"김준수","week":3,"variant":null,"source":"김준수/week3/양과 늑대.java","lines":102,"code":"/*\n전략\n- 완전탐색 백트래킹\n- Node 클래스 구현. 연결된 Node의 인덱스와 자신의 타입(양=1, 늑대=0)을 저장\n    - 각 간선은 [부모, 자식]으로 입력이 주어짐. 따라서 부모 → 자식만 저장하면 역주행 불가\n- “현재 접근 가능한 노드 목록”을 파라미터로 넘겨주면서 모든 가능한 탐색을 진행\n    - 늑대의 수가 양과 같거나 많아지면 종료(프루닝)\n    - 늑대의 수와 양의 수의 합이 전체 노드의 길이과 같으면 종료(종료조건)\n    - 다음 노드로 진행할 때마다 현재의 양의 수를 갱신\n\n시행착오\n- 모든 간선에 대해 양방향으로 연결했었는데, 방문 처리 및 재방문에 대한 로직이 꼬여서 틀림\n    - 부모 → 자식만 연결함으로써 역주행 불가능하게 하여 문제 해결\n- 초기에는 sheep, wolf를 Set으로 구현했는데 Set의 deepCopy가 너무 어려웠음\n    - sheep, wolf는 숫자로 관리하고, 현재 상태에서 접근 가능한 노드 List를 deepCopy하여 매 재귀 호출마다 새로운 객체를 넘기도록 하여 해결\n*/\n\nimport java.util.*;\n\nclass Solution {\n    List<Node> nodes;\n    static int answer;\n    static boolean[] visited;\n    \n    class Node{\n        boolean isWolf;\n        List<Integer> child;\n        \n        Node(int type){\n            isWolf = (type == 1) ? true : false;\n            child = new ArrayList<>();\n        }\n    }\n    \n    public int solution(int[] info, int[][] edges) {\n        answer = 0;\n        visited = new boolean[info.length];\n        // Node 배열 초기화\n        nodes = new ArrayList<>();\n        for(int i = 0; i < info.length; i++){\n            nodes.add(new Node(info[i]));\n        }\n        // 모든 간선이 [부모, 자식] 형태로 되어있음\n        // 따라서 부모 -> 자식만 connect에 저장\n        for(int[] edge : edges){\n            int u = edge[0];\n            int v = edge[1];\n            \n            nodes.get(u).child.add(v);\n        }\n        \n        List<Integer> canGo = new ArrayList<>();\n        for(int next : nodes.get(0).child){\n            canGo.add(next);\n        }\n        \n        dfs(1, 0, canGo);\n        \n        return answer;\n    }\n    \n    private void dfs(int sheep, int wolf, List<Integer> canGo){\n        // 결과 갱신\n        answer = Math.max(answer, sheep);\n        \n        // 종료 조건\n        // 양 + 늑대 = 전체면 모두 순회 완료\n        // 양 == 늑대면 잡아먹혀서 종료\n        if(sheep + wolf == nodes.size() || sheep == wolf){\n            return;\n        }\n        \n        // 백트래킹\n        for(int next : canGo){\n            // nextCanGo에 canGo를 deepCopy\n            List<Integer> nextCanGo = new ArrayList<>();\n            for(int idx : canGo){\n                if(idx == next){\n                    continue;\n                }\n                nextCanGo.add(idx);\n            }\n            // nextCanGo에 next의 child를 추가\n            for(int idx : nodes.get(next).child){\n                nextCanGo.add(idx);\n            }\n            \n            // 동물 추가 후 재귀\n            // nextCanGo가 매 next마다 새로 할당\n            if(nodes.get(next).isWolf){\n                wolf++;\n                dfs(sheep, wolf, nextCanGo);\n                wolf--;\n            }\n            else{\n                sheep++;\n                dfs(sheep, wolf, nextCanGo);\n                sheep--;\n            }\n        }\n    }\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":3,"variant":null,"source":"안찬웅/week3/양과 늑대.java","lines":79,"code":"import java.util.*;\n/* \n    이동할때마다 누적해서 양을 최대로 모을 수 있는 최대의 수\n    조건: 내가 모은 양의 수 <= 늑대의 수 \n    -> 모든양을 잡아먹어버림 안됨\n    \n    알고리즘: 그래프, 단방향 인접리스트\n    \n    1. edges 정보로 단방향 그래프 생성\n    2. 0번노드 방문시작. 0번 노드의 자식을 candidates에 넣음\n    3. dfs\n     3.1 candidates에 있는 노드들을 하나씩 순회 다음 방문 후보 선택\n     3.2 next를 방문했을때 양과 늑대 계산\n     3.3 다음늑대수 >= 다음양의수이면 continue\n     3.4 next방문 처리후 candidates에서 next를 제거하고 next의 안가본 자식을 candidates에 추가\n     3.5 최대양의수 갱신\n     3.6 추가했던 자식 제거, next를 원래 위치로 복구 후 방문취소\n    4. 최대야의 수 출력\n*/\nclass Solution {\n    static List<Integer>[] graph;\n    static int[] info;\n    static int maxSheep;\n    public int solution(int[] info, int[][] edges) {\n        this.info = info;\n        maxSheep = 1;\n        int nodeLen = info.length;\n        \n        graph = new List[nodeLen];\n        for(int i=0; i<nodeLen; i++) {\n            graph[i] = new ArrayList<>();\n        }\n        \n        for(int i=0; i<edges.length; i++) {\n            int parent = edges[i][0];\n            int child = edges[i][1];\n            graph[parent].add(child);\n        }\n        \n        List<Integer> candidates = new ArrayList<>();\n        \n        for(int child : graph[0]) {\n            candidates.add(child);\n        }\n        \n        dfs(candidates, 0, 1);\n        \n        return maxSheep;\n    }\n    \n    static void dfs(List<Integer> candidates, int sumWolf, int sumSheep) {\n        for(int i=0; i<candidates.size(); i++) {\n            int next = candidates.get(i);\n            \n            int nextSheep = sumSheep;\n            int nextWolf = sumWolf;\n\n            if (info[next] == 0) {\n                nextSheep++;\n            } else {\n                nextWolf++;\n            }\n            \n            if (nextWolf >= nextSheep) continue;\n            \n            maxSheep = Math.max(maxSheep, nextSheep);\n            \n            List<Integer> nextCandidates = new ArrayList<>(candidates);\n            nextCandidates.remove(i);\n\n            for(int child : graph[next]) {\n                nextCandidates.add(child);\n            }\n            \n            dfs(nextCandidates, nextWolf, nextSheep);\n        }\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":null,"source":"이성일/week3/양과늑대.java","lines":74,"code":"import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    static List<Integer>[] graph;\n    static int[] staticInfo;\n    static int[] lambState;\n\n    // dfs -> 현재 노드에서 다음 노드 탐색작업, 종료 조건 = 더이상 탐색할 노드 없을 떄\n    // 부채는 늑대를 만나면 +1, 양을 만나면 현재 부채값이 양배열 인덱스가 됨\n    static void dfs(int node, int cost) {\n        if (staticInfo[node] == 0) {\n            // 현재 노드가 양이면\n            lambState[cost] += 1;\n            // 양 발견 시, 필요한 양의 수 배열 인덱스에 값 추가, 리턴 없음\n            // 양 만나면 cost변동 없음\n        } else {\n            // 늑대면\n            // cost정보가 관리가 잘되나? -> 인자로 관리하니까 호출 스테이지는 해당 스테이지의 cost를 활용한다.\n            if (cost == 0) // 처음 만난 늑대는 2마리는 필요함\n                cost = 2;\n            else\n                cost += 1;\n        }\n        for (int childNode : graph[node]) {\n            dfs(childNode, cost);\n        }\n    }\n\n    public int solution(int[] info, int[][] edges) {\n        int answer = 0;\n        // 전체 노드 탐색하면서 양을 발견하면 해당 양을 얻기 위해 필요한 양의 수를 기록\n        // int[][] graph info.length, 2\n        int n = info.length;\n        graph = new ArrayList[n];\n        for (List<Integer> g : graph)\n            g = new ArrayList<>();\n\n        staticInfo = info;\n        lambState = new int[n];\n\n        // edge돌면서 graph 완성\n        for (int[] edge : edges) {\n            graph[edge[0]].add(edge[1]);\n        }\n\n        // dfs호출하고 lambState완성하기\n        dfs(0, 0);\n\n        // 양이 0마리 필요한 양\n        // ... 양이 n마리 필요한 양\n        // 0마리 양부터 빌드해서 순차적으로 가질 수 있는 양을 늘리기\n        // 0 - 3 (3, 0) -> 3 - 3 -> (4, 2) -> (5, 4) -> (6, 6)\n        int[] state = new int[2];\n        for (int i = 0; i < n; i++) {\n            if (lambState[i] > 0) {\n                // i cost의 양의 수가 있을 때\n                // 해당 양을 데려올 수 있을 때\n                if (state[0] >= i) {\n                    while (state[0] - i > 0) {\n                        state[0] += 1;\n                        state[1] += (i - 1);\n                        // 데려왔더니 늑대, 양이 동률일 때, 양 한마리 빼기\n                        if (state[1] >= state[0])\n                            return state[0] - 1;\n                        lambState[i] -= 1;\n                    }\n                }\n            }\n        }\n        return answer;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":3,"variant":"alt","source":"이성일/week3/양과늑대2.java","lines":44,"code":"import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    static List<Integer>[] graph;\n    static int answer;\n\n    static void dfs(int sheep, int wolf, List<Integer> candidates, int[] info) {\n        if (sheep > answer)\n            answer = sheep;\n        for (int candidate : candidates) {\n            List<Integer> newCandidates = new ArrayList<>(candidates);\n            newCandidates.remove(Integer.valueOf(candidate));\n            newCandidates.addAll(graph[candidate]);\n            if (info[candidate] == 0) {\n                dfs(sheep + 1, wolf, newCandidates, info);\n\n            } else {\n                if (wolf + 1 >= sheep)\n                    continue;\n                dfs(sheep, wolf + 1, newCandidates, info);\n            }\n        }\n    }\n\n    public int solution(int[] info, int[][] edges) {\n        int n = info.length;\n        answer = 0;\n        graph = new ArrayList[n];\n\n        for (int i = 0; i < n; i++) {\n            graph[i] = new ArrayList<>();\n        }\n        // edge돌면서 graph 완성\n        for (int[] edge : edges) {\n            graph[edge[0]].add(edge[1]);\n        }\n\n        dfs(1, 0, graph[0], info);\n\n        return answer;\n    }\n}","review":null}],"teamFeedback":null},{"key":"swea/1249","platform":"swea","problemId":"1249","title":"보급로","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA1249.java","lines":107,"code":"/*\n전략\n- 다익스트라\n- 그래프에 적용하는 다익스트라를 그리드 상에 적용하는 문제\n- 각 셀은 상하좌우 셀과 연결되어 있고, 각각의 소요 시간을 갖는다.\n- 월요일에 승주 코드를 보며 익힌 inRange 적용해봄\n * \n * \n시행착오\n- 처음에는 visited 배열을 썼었으나, dist가 visited 배열의 역할을 대처 가능했음\n */\n\nimport java.util.*;\nimport java.io.*;\n\n// board의 각 칸. compareTo 오버라이딩을 위해 Comparable 구현.\nclass Cell implements Comparable<Cell>{\n\tint time;\n\tint x;\n\tint y;\n\t\n\tpublic Cell(int time, int x, int y){\n\t\tthis.time = time;\n\t\tthis.x = x;\n\t\tthis.y = y;\n\t}\n\t\n\t@Override\n\tpublic int compareTo(Cell c) {\n\t\treturn Integer.compare(this.time, c.time);\n\t}\n}\n\npublic class SWEA1249 {\n\tstatic int[] dx = {-1, 1, 0, 0};\n\tstatic int[] dy = {0, 0, -1, 1};\n\tstatic Cell[][] board;\n\tstatic int[][] dist; // 각 칸의 최단거리 결과값 저장\n\t\n\tpublic static void main(String[] args) throws Exception{\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int t = 1; t <= T; t++) {\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tboard = new Cell[N][N];\n\t\t\tdist = new int[N][N];\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tString line = br.readLine();\n\t\t\t\tfor(int j = 0; j < N; j++) {\n\t\t\t\t\tboard[i][j] = new Cell(line.charAt(j) - '0', i, j);\n\t\t\t\t\tdist[i][j] = Integer.MAX_VALUE;\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t// 시작점(0, 0)에서 다익스트라 시작\n\t\t\tdijkstra(0, 0);\n\t\t\t\n\t\t\t// 종료 지점 (N - 1, N - 1)의 dist값 출력\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(dist[N - 1][N - 1]).append(\"\\n\");\n\t\t}\t\n\t\t\n\t\tSystem.out.print(sb);\n\t}\n\t\n\tprivate static void dijkstra(int x, int y) {\n\t\tPriorityQueue<Cell> pq = new PriorityQueue<>();\n\t\t\n\t\t// 시작점 방문처리\n\t\tpq.offer(new Cell(0, x, y));\n\t\tdist[x][y] = 0;\n\t\t\n\t\twhile(!pq.isEmpty()) {\n\t\t\t// pq에서 Cell을 하나 꺼내서 4방향 델타 탐색\n\t\t\tCell cell = pq.poll();\n\t\t\tint currTime = cell.time;\n\t\t\t\n\t\t\tfor(int i = 0; i < 4; i++) {\n\t\t\t\tint nx = cell.x + dx[i];\n\t\t\t\tint ny = cell.y + dy[i];\n\t\t\t\n\t\t\t\tif(!inRange(nx, ny)) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\tCell next = board[nx][ny];\n\t\t\t\tint nextTime = currTime + next.time;\n\t\t\t\t\n\t\t\t\t// 다음 Cell의 dist  VS  현재 Cell까지의 거리 + 다음 Cell의 time을 비교\n\t\t\t\t// 후자가 작으면 후자가 더 짧은 거리이므로 방문처리\n\t\t\t\tif(nextTime < dist[nx][ny]) {\n\t\t\t\t\tpq.offer(new Cell(nextTime, nx, ny));\n\t\t\t\t\tdist[nx][ny] = nextTime;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\t\n\t// board 범위 내 여부 리턴\n\tprivate static boolean inRange(int x, int y) {\n\t\treturn x >= 0 && x < board.length && y >= 0 && y < board.length;\n\t}\n}","review":{"platform":"swea","problemId":"1249","author":"junsoo","source":"김준수/week1/SWEA1249.java","week":"1","compiles":"true","verdict":"good","tags":["redundant-collection","space-complexity","good-readability"],"generatedBy":"claude-code-local","generatedAt":"2026-08-16","complexity":{"time":"O(N² log N)","space":"O(N²)"},"body":"# 보급로 (swea/1249) — junsoo\n\n## 접근\n\n`Cell(time, x, y)` 클래스를 만들고 `Comparable` 을 구현해 우선순위 큐에 넣는 다익스트라.\n답은 맞고, 파일 맨 위의 전략·시행착오 주석이 특히 좋다.\n\n> 처음에는 visited 배열을 썼었으나, dist가 visited 배열의 역할을 대처 가능했음\n\n이건 다익스트라를 제대로 이해했다는 신호다. `dist` 가 `INF` 인지 여부가 곧 미방문 표시이고,\n완화 조건이 재방문을 걸러내므로 `visited` 는 없어도 된다. 리뷰 시간에 공유할 만한 내용이다.\n\n## 개선점\n\n### 1. (중요) `Cell[][] board` 는 `int[][]` 면 충분하다 — `redundant-collection`\n\n```java\nboard = new Cell[N][N];\n...\nboard[i][j] = new Cell(line.charAt(j) - '0', i, j);\n```\n\n칸마다 객체를 하나씩 만든다. N=100이면 **1만 개의 객체**가 생기는데, 실제로 쓰는 건 `.time` 뿐이다.\n`Cell.x` / `Cell.y` 에는 자기 좌표가 들어가지만 알고리즘은 그 값을 읽지 않는다 — 이웃 좌표는\n`nx`/`ny` 로 따로 계산한다.\n\n```java\nstatic int[][] board;\n...\nboard[i][j] = line.charAt(j) - '0';\n```\n\n`Cell` 은 우선순위 큐에 넣을 때만 필요하다. 격자 저장까지 객체로 할 이유는 없다.\n테스트케이스가 반복되면 GC 부담도 그만큼 늘어난다.\n\n### 2. (중요) 죽은 큐 항목을 건너뛰지 않는다\n\n```java\nCell cell = pq.poll();\nint currTime = cell.time;\n// 바로 4방향 탐색\n```\n\n큐에는 같은 칸이 여러 번 들어간다. 나중에 더 짧은 경로를 찾으면 새 항목을 넣지만 옛 항목은\n남아 있기 때문이다. 완화 조건(`nextTime < dist[nx][ny]`) 덕에 **답은 맞지만**, 이미 확정된 칸을\n꺼내서 4방향을 또 도는 낭비가 있다.\n\n```java\nCell cell = pq.poll();\nif (cell.time > dist[cell.x][cell.y]) continue;   // 이 한 줄\n```\n\n같은 회차 안찬웅 코드에 이 처리가 들어가 있으니 비교해보면 좋다.\n\n### 3. (사소) `dist` 초기화가 입력 루프에 섞여 있다\n\n```java\nboard[i][j] = new Cell(line.charAt(j) - '0', i, j);\ndist[i][j] = Integer.MAX_VALUE;\n```\n\n한 루프에서 두 가지 일을 한다. `Arrays.fill` 로 분리하면 각 줄이 뭘 하는지 바로 보인다.\n\n```java\nfor (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);\n```\n\n## 복잡도\n\n- 시간: `O(N² log N)` — 적정하다.\n- 공간: `O(N²)` — 다만 상수가 크다. `Cell[][]` 을 `int[][]` 로 바꾸면 칸당 객체 헤더(16바이트 이상)가\n  사라지고 int 4바이트만 남는다.\n\n## 요약\n\n알고리즘 선택과 이해도는 좋고 주석이 팀에서 제일 친절하다.\n격자를 객체 배열로 들고 있는 것과 죽은 큐 항목 처리 두 가지만 손보면 된다.\n둘 다 답이 아니라 낭비의 문제다."}},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA1249.java","lines":73,"code":"import java.util.*;\nimport java.lang.*;\nimport java.io.*;\n/*\n    출발지(S)에서 도착지(G)로 이동하는데 복구 시간이 가장 짧은 경로 구하기\n    -깊이가 3이면 복구에 드는 시간3\n    -0인 곳은 복구작업 불필요\n\n    알고리즘: 가중치 BFS\n    시간: 20초 O(n^2)\n\n    1. 입력\n    1.1 테스트케이스 수 입력받기\n    1.2 지도의 크기 입력 받기\n    1.3 지도 입력받기 (0100)\n    2. 다익스트라\n*/\nclass SWEA1249 {\n    static int[] dx = {-1, 0, 1, 0};\n    static int[] dy = {0, -1, 0, 1};\n    static int[][] board;\n    static int[][] dist;\n    static int n;\n    public static void main(String[] args) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        StringBuilder sb = new StringBuilder();\n        int t = Integer.parseInt(br.readLine());\n\n        for(int tc=1; tc<=t; tc++) {\n            sb.append(\"#\").append(tc).append(\" \");\n            n = Integer.parseInt(br.readLine());\n\n            board = new int[n][n];\n            for(int i=0; i<n; i++) { // 0100\n                String str = br.readLine();\n                for(int j=0; j<str.length(); j++) {\n                    board[i][j] = str.charAt(j) - '0';\n                }\n            }\n            dijkstra(0, 0);\n            \n            sb.append(dist[n-1][n-1]).append(\"\\n\");\n        }\n        System.out.print(sb.toString());\n    }\n    \n    static void dijkstra(int x, int y) {\n        dist = new int[n][n];\n        for(int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);\n        PriorityQueue<int[]> pq = new PriorityQueue<>((o1, o2) -> Integer.compare(o1[2], o2[2]));\n        \n        dist[x][y] = 0;\n        pq.add(new int[]{x, y, 0});\n        while(!pq.isEmpty()) {\n            int[] cur = pq.poll();\n            int cx = cur[0];\n            int cy = cur[1];\n            int cost = cur[2];\n            if(cost > dist[cx][cy]) continue;\n\n            for(int dir=0; dir<4; dir++) {\n                int nx = cx + dx[dir];\n                int ny = cy + dy[dir];\n                if(nx < 0 || nx >= n || ny < 0 || ny >= n) continue;\n                int nCost = cost + board[nx][ny];\n                if(nCost < dist[nx][ny]) {\n                    dist[nx][ny] = nCost;\n                    pq.add(new int[]{nx, ny, nCost});\n                }\n            }\n        }\n    }\n}","review":{"platform":"swea","problemId":"1249","author":"chanung","source":"안찬웅/week1/SWEA1249.java","week":"1","compiles":"true","verdict":"good","tags":["good-complexity","good-readability","dead-code"],"generatedBy":"claude-code-local","generatedAt":"2026-08-16","complexity":{"time":"O(N² log N)","space":"O(N²)"},"body":"# 보급로 (swea/1249) — chanung\n\n## 접근\n\n격자를 그래프로 보고 다익스트라. 우선순위 큐에 `int[]{x, y, cost}` 를 넣고 `dist` 로 최단 복구시간을 관리한다.\n\n**4명 중 유일하게 `if(cost > dist[cx][cy]) continue;` 가 있다.** 이 한 줄이 교과서적으로 맞는 처리다.\n\n```java\nint[] cur = pq.poll();\n...\nif(cost > dist[cx][cy]) continue;   // 이미 더 좋은 값으로 확정된 칸\n```\n\n우선순위 큐에는 같은 칸이 여러 번 들어간다. 나중에 더 짧은 경로를 찾으면 새 항목을 넣지만\n큐에 있던 옛 항목은 지워지지 않기 때문이다. 이 줄이 없어도 아래 완화 조건(`nCost < dist[nx][ny]`)\n덕분에 답은 맞지만, 죽은 항목의 4방향 탐색을 매번 다시 돈다. 이걸 짚고 넘어간 건 잘한 판단이다.\n\n클래스를 만들지 않고 `int[]` + 람다 비교자로 끝낸 것도 이 문제 규모에서는 적절하다.\n객체 생성 비용이 없고 코드도 짧다.\n\n## 개선점\n\n### 1. (사소) `import java.lang.*;` 는 필요 없다 — `dead-code`\n\n`java.lang` 은 컴파일러가 항상 자동으로 넣는다. 지워도 동작이 같다.\n\n### 2. (사소) 입력 파싱이 행 길이에 의존한다\n\n```java\nString str = br.readLine();\nfor(int j=0; j<str.length(); j++) {\n```\n\n`n` 대신 `str.length()` 를 쓰고 있다. 지금은 같지만, 줄 끝에 공백이나 `\\r` 이 섞여 들어오면\n`board` 범위를 넘어 `ArrayIndexOutOfBoundsException` 이 난다. Windows에서 만든 입력 파일로\n로컬 테스트할 때 실제로 겪을 수 있다. `j < n` 으로 두거나 `readLine().trim()` 을 쓰면 안전하다.\n\n## 복잡도\n\n- 시간: `O(N² log N)` — 칸 N²개, 큐 연산이 각 log. N ≤ 100이라 충분하다.\n- 공간: `O(N²)` — `board` + `dist`. 적정하다.\n\n## 요약\n\n네 명 중 가장 짧고(72줄) 가장 정확하다. 죽은 큐 항목을 건너뛰는 처리가 들어간 유일한 코드다.\n고칠 건 없고, 입력 파싱만 `n` 기준으로 바꾸면 더 단단해진다."}},{"author":"seongil","authorName":"이성일","week":1,"variant":null,"source":"이성일/week1/SWEA1249.java","lines":97,"code":"package com.ssafy.swb;\n\nimport java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.util.Arrays;\nimport java.util.PriorityQueue;\n\nclass Node implements Comparable<Node>{\n\tint r;\n\tint c;\n\tint cost;\n\t\n\tNode(int r, int c, int cost){\n\t\tthis.r = r;\n\t\tthis.c = c;\n\t\tthis.cost = cost;\n\t}\n\t@Override\n\tpublic int compareTo(Node o) {\n\t\treturn Integer.compare(this.cost, o.cost);\n\t}\n\t\n}\n\npublic class SWEA1249 {\n\t\n\tpublic static int[] dx = {-1, 0, 1, 0};\n\tpublic static int[] dy = {0, 1, 0, -1};\n\t\n\tpublic static boolean inRange(int i,int j,int n) {\n\t\treturn (i >= 0 && i < n && j >= 0 && j < n);\n\t}\n\t\n\tpublic static int dijkstra(PriorityQueue<Node> pq,\n\t\t\tint[][] dist, boolean[][] visited, int[][] board) {\n\t\t\n\t\twhile (!pq.isEmpty()) {\n\t\t\t\n\t\t\tNode v = pq.poll();\n\t\t\t\n\t\t\tint r = v.r, c = v.c;\n\t\t\tvisited[r][c] = true;\n\t\t\t\n\t\t\tfor (int d = 0; d < 4; d++) {\n\t\t\t\tint ar = r + dx[d]; int ac = c + dy[d];\n\t\t\t\tif (inRange(ar, ac, dist.length) && !visited[ar][ac]) {\n\t\t\t\t\tif (dist[ar][ac] > v.cost + board[ar][ac]) {\t\n\t\t\t\t\t\tdist[ar][ac] = v.cost + board[ar][ac];\n\t\t\t\t\t\tpq.offer(new Node(ar,ac,dist[ar][ac]));\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t}\n\t\treturn dist[dist.length - 1][dist.length - 1];\n\t}\n\t\n\tpublic static void main(String[] args) throws Exception {\n\t\t// T 입력받고 테케별로 size, board 입력 받기\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint t = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tint n = Integer.parseInt(br.readLine());\n\t\t\tint[][] board = new int[n][n];\n\t\t\t\n\t\t\tboolean[][] visited = new boolean[n][n];\n\t\t\tint[][] dist = new int[n][n];\n\t\t\tfor (int[] arr: dist) {\n\t\t\t\tArrays.fill(arr, Integer.MAX_VALUE);\n\t\t\t}\n\t\t\tdist[0][0] = 0;\n\t\t\t\n\t\t\tfor (int r = 0; r < n; r++) {\n\t\t\t\tchar[] row = br.readLine().trim().toCharArray();\n\t\t\t\tfor (int c = 0; c < n; c++) {\n\t\t\t\t\tboard[r][c] = row[c] - '0';\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tPriorityQueue<Node> pq = new PriorityQueue<>();\n\t\t\tpq.offer(new Node(0,0,0));\n\t\t\t\n\t\t\tint val = dijkstra(pq, dist, visited, board);\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(i).append(\" \").append(val).append(\"\\n\");\n\t\t\tSystem.out.print(sb);\n\t\t}\n\t\t// 2차원배열 visited관리, dist관리, 노드는 r,c,cost로 구분\n\t\t\t// priorityqueue에서 활용하기 위해 comaparable 구현하기 (compareTo함수)\n\t\t// proirityQueue로 (offer/poll) 로 갱신지점 찾기\n\t\t// 인접노드 기준으로 dist갱신하기\n\t\t\n\t}\n}","review":{"platform":"swea","problemId":"1249","author":"seongil","source":"이성일/week1/SWEA1249.java","week":"1","compiles":"true","verdict":"needs-fix","tags":["io-performance","long-method","dead-code","good-decomposition"],"generatedBy":"claude-code-local","generatedAt":"2026-08-16","complexity":{"time":"O(N² log N)","space":"O(N²)"},"body":"# 보급로 (swea/1249) — seongil\n\n## 접근\n\n`Node(r, c, cost)` + `Comparable` 로 우선순위 큐를 쓰고, `visited` 로 확정된 칸을 표시하는 다익스트라.\n답은 맞다.\n\n`inRange` 를 별도 메서드로 뽑은 건 좋다 — 4방향 탐색에서 조건식이 네 개씩 늘어지는 걸 막아준다.\n`visited` 를 꺼낼 때 찍고(`visited[r][c] = true`) 이웃에서 확인하는 구조도 다익스트라의\n\"확정 집합\" 개념을 그대로 옮긴 정석이다.\n\n## 개선점\n\n### 1. (중요) 테스트케이스마다 출력한다 — `io-performance`\n\n```java\nfor (int i = 1; i <= t; i++) {\n    ...\n    StringBuilder sb = new StringBuilder();   // 매번 새로 만들고\n    sb.append(\"#\").append(i).append(\" \").append(val).append(\"\\n\");\n    System.out.print(sb);                      // 매번 출력\n}\n```\n\n`System.out` 은 호출마다 flush 가 걸린다. 테스트케이스가 많은 SWEA 문제에서 이것만으로\n시간 초과가 나는 경우가 실제로 있다. `StringBuilder` 를 루프 **밖에** 하나 두고 마지막에 한 번만 출력하면 된다.\n\n```java\nStringBuilder sb = new StringBuilder();          // 루프 밖\nfor (int i = 1; i <= t; i++) {\n    ...\n    sb.append(\"#\").append(i).append(\" \").append(val).append(\"\\n\");\n}\nSystem.out.print(sb);                            // 한 번만\n```\n\n같은 회차 김준수·안찬웅 코드가 이 형태다.\n\n### 2. (중요) `package com.ssafy.swb;` 가 남아 있다 — `dead-code`\n\nIDE 패키지 구조가 그대로 딸려왔다. 이 파일은 `com/ssafy/swb/` 디렉터리 안에 있어야만 실행되고,\n저장소에서는 `이성일/week1/` 에 있어서 경로가 맞지 않는다. 제출본에도 들어갈 이유가 없다.\n\n같은 이유로 파일 끝의 설계 메모(`// T 입력받고...`, `// 2차원배열 visited관리...`)도 정리 대상이다.\n코드를 다 쓴 뒤 남은 계획 메모라 지금은 본문과 중복된다.\n\n### 3. (중요) 죽은 큐 항목을 꺼낼 때 걸러내지 않는다\n\n```java\nNode v = pq.poll();\nint r = v.r, c = v.c;\nvisited[r][c] = true;      // 이미 true 일 수 있다\n```\n\n같은 칸이 큐에 여러 번 들어가므로 확정된 칸을 또 꺼내게 된다. `!visited[ar][ac]` 가 있어서\n**답은 맞지만**, 이미 처리한 칸의 4방향을 다시 도는 낭비가 남는다.\n\n```java\nNode v = pq.poll();\nif (visited[v.r][v.c]) continue;   // 이 한 줄\nvisited[v.r][v.c] = true;\n```\n\n### 4. (사소) `dijkstra` 인자가 4개다 — `long-method`\n\n```java\npublic static int dijkstra(PriorityQueue<Node> pq, int[][] dist, boolean[][] visited, int[][] board)\n```\n\n호출부에서 `pq` 를 만들어 시작 노드까지 넣어서 넘기고 있어서, 다익스트라의 시작점이 어디인지\n메서드 안에서는 보이지 않는다. `board` 와 `n` 을 필드로 두고 `dijkstra(0, 0)` 형태로 바꾸면\n\"어디서 출발하는가\"가 시그니처에 드러난다.\n\n## 복잡도\n\n- 시간: `O(N² log N)` — 적정하다.\n- 공간: `O(N²)` — `dist` + `visited` + `board`. 적정하다.\n\n## 요약\n\n알고리즘은 정석이고 `inRange` 분리와 `visited` 운용은 오히려 모범에 가깝다.\n다만 테스트케이스마다 출력하는 부분은 SWEA에서 실제로 시간 초과를 부를 수 있으니 먼저 고치는 게 좋다.\n`package` 선언과 하단 계획 메모는 제출 전에 지우는 습관을 들이면 된다."}},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA1249.java","lines":111,"code":"import java.util.*;\nimport java.io.*;\n\n//처음에는 dfs 백트래킹으로 푸는 문제인줄 알고 시도하였지만 시간 초과, 이후 각 위치에 비용이 존재한다는 것을 깨닫고 다익스트라 진행\n//우선순위큐이기때문에 (N-1,N-1)을 도칙했을때 최단 경로임\npublic class SWEA1249 {\n\tstatic int[][] board;\n\tstatic int N;\n\tstatic int[] dx = {1,0,-1,0};\n\tstatic int[] dy = {0,1,0,-1};\n\t\n\t\n\tstatic class Node implements Comparable<Node>{\n\t\tint x;\n\t\tint y;\n\t\tint cost;\n\t\t\n\t\tNode(int x, int y, int cost){\n\t\t\tthis.x = x;\n\t\t\tthis.y = y;\n\t\t\tthis.cost = cost;\n\t\t}\n\t\t\n\t\tpublic int compareTo(Node o) {\n\t\t\treturn this.cost - o.cost;\n\t\t}\n\t}\n\tpublic static void main(String[] args) throws IOException {\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tN = Integer.parseInt(br.readLine());\n\t\t\tboard = new int[N][N];\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tString line = br.readLine();\n\t\t\t\tfor(int j = 0; j < N; j++) {\n\t\t\t\t\t\n\t\t\t\t\tboard[i][j] = line.charAt(j) - '0';\n\t\t\t\t\t\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tint minTime = dijkstra(new Node(0,0,0));\n\t\t\t\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(minTime);\n\t\t\tSystem.out.println(sb);\n\t\t\t\n\t\t}\n\t\t\n\t\t\n\t\t\n\t\t\n\t}\n\t\n\tstatic int dijkstra(Node node) {\n\t\t\n\t\tint[][] dist = new int[N][N];\n\t\tint max_value = Integer.MAX_VALUE;\n\t\t\n\t\tfor(int i = 0; i < N; i++) {\n\t\t\tArrays.fill(dist[i], max_value);\n\t\t}\n\t\t\n\t\tPriorityQueue<Node> pq = new PriorityQueue<>();\n\t\tdist[0][0] = 0;\n\t\t\n\t\tpq.offer(new Node(0,0,0));\n\t\t\n\t\twhile(!pq.isEmpty()) {\n\t\t\t\n\t\t\tNode current = pq.poll();\n\t\t\t\n\t\t\n\t\t\t\n\t\t\tif(current.x == N-1 && current.y == N-1) {\n\t\t\t\treturn dist[N-1][N-1]; //목적지에 도착하는 순간 최소를 보장\n\t\t\t}\n\t\t\t\n\t\t\tfor(int dir = 0; dir < 4; dir++) {\n\t\t\t\tint nx = current.x + dx[dir];\n\t\t\t\tint ny = current.y + dy[dir];\n\t\t\t\t\n\t\t\t\t\n\t\t\t\tif(!inRange(nx,ny)) continue;\n\t\t\t\t\n\t\t\t\tif(current.cost + board[nx][ny] < dist[nx][ny]) {\n\t\t\t\t\tdist[nx][ny] = current.cost + board[nx][ny];\n\t\t\t\t\tpq.offer(new Node(nx,ny,dist[nx][ny]));\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t}\n\t\treturn dist[N-1][N-1];\n\t\t\n\t\t\n\t\t\n\t}\n\t\n\tstatic boolean inRange(int x, int y) {\n\t\treturn x>= 0 && x < N && y >= 0 && y < N;\n\t}\n}","review":{"platform":"swea","problemId":"1249","author":"seungjoo","source":"이승주/1주차/SWEA1249.java","week":"1","compiles":"true","verdict":"needs-fix","tags":["overflow","io-performance","good-complexity"],"generatedBy":"claude-code-local","generatedAt":"2026-08-16","complexity":{"time":"O(N² log N)","space":"O(N²)"},"body":"# 보급로 (swea/1249) — seungjoo\n\n## 접근\n\n`Node(x, y, cost)` + 우선순위 큐 다익스트라. 답은 맞다.\n\n**네 명 중 유일하게 도착점을 꺼내는 순간 조기 종료한다.**\n\n```java\nif(current.x == N-1 && current.y == N-1) {\n    return dist[N-1][N-1];   // 목적지에 도착했을때 최단 경로임\n}\n```\n\n주석에 근거까지 적어놨는데 정확하다. 우선순위 큐에서 꺼낸 시점의 비용은 그 칸의 확정 최단값이므로,\n도착점이 나오면 나머지 칸을 볼 이유가 없다. 격자 전체를 끝까지 훑는 다른 세 명보다 평균적으로 빠르다.\n\n파일 상단의 시행착오 기록도 좋다.\n\n> 처음에는 dfs 백트래킹으로 푸는 문제인줄 알고 시도하였지만 시간 초과, 이후 각 위치에 비용이 존재한다는 것을 깨닫고 다익스트라 진행\n\n\"칸마다 비용이 있으면 최단경로 문제\"라는 인식이 이 문제의 핵심이다.\n\n## 개선점\n\n### 1. (중요) `compareTo` 를 뺄셈으로 구현했다 — `overflow`\n\n```java\npublic int compareTo(Node o) {\n    return this.cost - o.cost;\n}\n```\n\n이 문제에서는 최대 비용이 `100 × 100 × 9 = 90,000` 이라 **터지지 않는다.** 답도 맞다.\n문제는 습관이다. 두 값이 `Integer.MAX_VALUE` 와 음수처럼 벌어지면 뺄셈이 오버플로해서\n부호가 뒤집히고, 정렬 순서가 조용히 깨진다. 우선순위 큐가 잘못된 순서로 돌아도 예외가 안 나서\n찾기 아주 어려운 버그가 된다.\n\n```java\npublic int compareTo(Node o) {\n    return Integer.compare(this.cost, o.cost);\n}\n```\n\n같은 회차에서 김준수·이성일은 `Integer.compare` 를 썼다. 비용을 누적하는 문제(다익스트라, 배낭 등)에서는\n이쪽으로 통일하는 게 안전하다.\n\n### 2. (중요) 테스트케이스마다 출력한다 — `io-performance`\n\n```java\nStringBuilder sb = new StringBuilder();   // 루프 안에서 매번 생성\nsb.append(\"#\").append(tc).append(\" \").append(minTime);\nSystem.out.println(sb);                    // 매번 출력\n```\n\n`System.out` 은 호출마다 flush 된다. 테스트케이스가 많으면 이것만으로 시간 초과가 날 수 있다.\n`StringBuilder` 를 루프 밖에 하나 두고 `\\n` 을 붙여 쌓은 뒤 마지막에 한 번만 출력하면 된다.\n\n### 3. (사소) `max_value` 지역 변수는 없어도 된다\n\n```java\nint max_value = Integer.MAX_VALUE;\nfor(int i = 0; i < N; i++) Arrays.fill(dist[i], max_value);\n```\n\n`Arrays.fill(dist[i], Integer.MAX_VALUE)` 로 바로 쓰면 된다. 자바 관례상 지역 변수는\n`snake_case` 가 아니라 `camelCase` 이기도 하다.\n\n### 4. (사소) 조기 종료가 있어서 마지막 `return` 은 도달 조건이 특이하다\n\n```java\nreturn dist[N-1][N-1];   // 큐가 빌 때까지 도착점을 못 꺼낸 경우\n```\n\n이 문제는 모든 칸이 통행 가능해서 항상 도달하므로 실제로는 위쪽 `return` 에서 끝난다.\n남겨두는 게 안전하지만, 왜 있는지 한 줄 주석이 있으면 읽는 사람이 덜 헷갈린다.\n\n## 복잡도\n\n- 시간: `O(N² log N)` — 조기 종료 덕에 평균은 이보다 빠르다.\n- 공간: `O(N²)` — `dist` + `board`. 적정하다.\n\n## 요약\n\n조기 종료를 넣은 건 네 명 중 유일하고, 그 근거를 정확히 이해하고 있다.\n`compareTo` 뺄셈과 테스트케이스별 출력 두 가지만 습관으로 고치면 된다.\n둘 다 이 문제에서는 통과하지만, 더 큰 입력에서 조용히 터지는 종류다."}}],"teamFeedback":null},{"key":"swea/1251","platform":"swea","problemId":"1251","title":"하나로","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA1251.java","lines":143,"code":"/*\n전략\n\n- 최소 신장 트리 - 크루스칼\n    - 최소 비용의 간선부터 그리디하게 병합 시도\n- 모든 섬에 대해 교차하여 간선을 만든다\n- 간선을 최소 비용으로 정렬한다\n- 간선을 앞에서부터 순회하며 간선의 두 정점을 병합\n    - 두 섬의 루트 노드가 같으면 병합 시 사이클이 만들어질 수 있으므로 스킵\n    - 이 사이클 찾기 및 병합 과정을 유니온 파인드로 진행\n    - 현재 사용한 간선의 개수가 N - 1개면 조기 종료\n        - N개의 노드를 연결하는 최소한의 간선은 N - 1개이기 때문\n\n시행착오\n\n- 크루스칼 알고리즘의 개념이 부족하여 크루스칼 알고리즘 기초부터 학습한 후 단계별로 풀이법을 정리함\n- 크루스칼 알고리즘의 구현을 위해서는 유니온 파인드를 사용해야 하는데 \n  개념이 부족하여 유니온 파인드 자료구조의 기초부터 학습한 후 단계별로 구현 방법을 정리함\n */\n\nimport java.util.*;\nimport java.io.*;\n\n\npublic class SWEA1251 {\n\tstatic int[] parent; // 유니온 파인드 Make-set\n\t\n\tpublic static void main(String[] args) throws Exception{\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int t = 1; t <= T; t++) {\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tList<List<Integer>> islands = new ArrayList<>();\n\t\t\tList<Edge> edges = new ArrayList<>();\n\t\t\tparent = new int[N + 1];\n\t\t\t\n\t\t\t// X 좌표 입력\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\tint[] xList = new int[N];\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\txList[i] = Integer.parseInt(st.nextToken());\n\t\t\t}\n\t\t\t\n\t\t\t// Y 좌표 입력\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\tint[] yList = new int[N];\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tyList[i] = Integer.parseInt(st.nextToken());\n\t\t\t}\n\t\t\t\n\t\t\t// 섬 초기화\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tislands.add(new ArrayList<>());\n\t\t\t\tislands.get(i).add(xList[i]);\n\t\t\t\tislands.get(i).add(yList[i]);\n\t\t\t\t\n\t\t\t\tparent[i] = i; // Make-set 초기화\n\t\t\t}\n\t\t\t\n\t\t\t// 세금 입력\n\t\t\tdouble tax = Double.parseDouble(br.readLine());\n\t\t\t\n\t\t\t// 간선 추가(모든 섬에 대해 교차해서)\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tfor(int j = i + 1; j < N; j++) {\n\t\t\t\t\tdouble length = Math.pow(islands.get(i).get(0) - islands.get(j).get(0), 2);\n\t\t\t\t\tlength += Math.pow(islands.get(i).get(1) - islands.get(j).get(1), 2);\n\t\t\t\t\tlength = Math.sqrt(length);\n\t\t\t\t\t\n\t\t\t\t\tedges.add(new Edge(i, j, length * length * tax));\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t// 최소 비용으로 간선 정렬\n\t\t\tCollections.sort(edges);\n\t\t\t\n\t\t\tdouble totalCost = 0;\n\t\t\tint edgeCnt = 0;\n\t\t\t\n\t\t\t// 간선 순회\n\t\t\tfor(Edge edge : edges) {\n\t\t\t\tint rootU = find(edge.u);\n\t\t\t\tint rootV = find(edge.v);\n\t\t\t\t\n\t\t\t\t// 두 섬의 루트 노드가 같지 않다 = 유니온 해도 사이클이 안만들어진다\n\t\t\t\tif(rootU != rootV) {\n\t\t\t\t\tunion(edge.u, edge.v);\n\t\t\t\t\ttotalCost += edge.cost;\n\t\t\t\t\tedgeCnt++;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\t// 간선이 N - 1개면 모든 섬이 연결되었으므로 조기 종료\n\t\t\t\tif(edgeCnt == N - 1) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t// 결과에 소수 첫째 자리에서 반올림 \n\t\t\tsb.append(\"#\").append(t).append(\" \").append(Math.round(totalCost)).append(\"\\n\");\n\t\t}\n\t\tSystem.out.print(sb);\n\t}\n\t\n\t// 유니온 파인드 find\n\tstatic int find(int x) {\n\t\tif(parent[x] == x) {\n\t\t\treturn x;\n\t\t}\n\t\t\n\t\treturn parent[x] = find(parent[x]); // 경로 압축\n\t}\n\t\n\t// 유니온 파인드 union\n\tstatic void union(int u, int v) {\n\t\tint rootU = find(u);\n\t\tint rootV = find(v);\n\t\t\n\t\tif(rootU != rootV) {\n\t\t\tparent[rootU] = rootV;\n\t\t}\n\t}\n}\n\nclass Edge implements Comparable<Edge>{\n\tpublic int u;\n\tpublic int v;\n\tpublic double cost;\n\t\n\tpublic Edge(int u, int v, double cost) {\n\t\tthis.u = u;\n\t\tthis.v = v;\n\t\tthis.cost = cost;\n\t}\n\t\n\t@Override\n\tpublic int compareTo(Edge e) {\n\t\treturn Double.compare(this.cost, e.cost);\n\t}\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA1251.java","lines":90,"code":"import java.util.*;\nimport java.io.*;\n/*\n    모든 섬을 최소 비용으로 연결 -> MST (크루스칼)\n    비용 = E * (거리의 제곱) -> 제곱 그대로 쓰면 되므로 sqrt 불필요\n    \n    알고리즘: 크루스칼 + Union-Find\n    시간: O(N^2 log N^2)  (N=1000 -> 간선 약 50만개)\n    \n    1. 입력\n    1.1 N, x좌표 N개, y좌표 N개, 세율 E\n    2. 완전그래프 간선 생성 (i < j)\n    3. 비용 오름차순 정렬\n    4. Union-Find로 사이클 체크하며 N-1개 채택\n    5. 총합 * E -> 반올림 출력\n*/\nclass SWEA1251 {\n    static int[] parent;\n    static int n;\n    public static void main(String[] args) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        StringBuilder sb = new StringBuilder();\n        int t = Integer.parseInt(br.readLine());\n\n        for (int tc = 1; tc <= t; tc++) {\n            n = Integer.parseInt(br.readLine());\n\n            long[] x = new long[n];\n            long[] y = new long[n];\n\n            StringTokenizer st = new StringTokenizer(br.readLine());\n            for (int i = 0; i < n; i++) x[i] = Long.parseLong(st.nextToken());\n\n            st = new StringTokenizer(br.readLine());\n            for (int i = 0; i < n; i++) y[i] = Long.parseLong(st.nextToken());\n\n            double e = Double.parseDouble(br.readLine().trim());\n\n            // 2. 간선 생성 (cost, from, to)\n            long[][] edges = new long[n * (n - 1) / 2][3];\n            int idx = 0;\n            for (int i = 0; i < n; i++) {\n                for (int j = i + 1; j < n; j++) {\n                    long dx = x[i] - x[j];\n                    long dy = y[i] - y[j];\n                    edges[idx][0] = dx * dx + dy * dy;\n                    edges[idx][1] = i;\n                    edges[idx][2] = j;\n                    idx++;\n                }\n            }\n\n            // 3. 비용 오름차순 정렬\n            Arrays.sort(edges, (o1, o2) -> Long.compare(o1[0], o2[0]));\n\n            // 4. 크루스칼\n            parent = new int[n];\n            for (int i = 0; i < n; i++) parent[i] = i;\n\n            long total = 0;\n            int cnt = 0;\n            for (long[] edge : edges) {\n                int a = (int) edge[1];\n                int b = (int) edge[2];\n\n                if (find(a) == find(b)) continue;   // 사이클이면 버림\n\n                union(a, b);\n                total += edge[0];\n                cnt++;\n                if (cnt == n - 1) break;\n            }\n\n            sb.append(\"#\").append(tc).append(\" \")\n              .append(Math.round(total * e)).append(\"\\n\");\n        }\n        System.out.print(sb.toString());\n    }\n\n    static int find(int a) {\n        if (parent[a] == a) return a;\n        return parent[a] = find(parent[a]);\n    }\n\n    static void union(int a, int b) {\n        int rootA = find(a);\n        int rootB = find(b);\n        if (rootA != rootB) parent[rootA] = rootB;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":1,"variant":null,"source":"이성일/week1/SWEA1251.java","lines":95,"code":"package com.ssafy.swb;\n\nimport java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\npublic class SWEA1251{\n\t// 1. 입력 요소 Tc, 좌표 개수, x좌표 들, y좌표들, 상수 E\n\t// 2. kruskal\n\t\t// 2-1 노드별 간선 정보 계산, 2차원 배열에 저장 [v,e, cost]\n\t\t// 2-2 cost 기준 정렬\n\t\t// 2-3 가장 작은 cost부터 union find 진횅하기\n\t\t\t// 2-3-1 union 시 작은 트리를 큰 트리에 병합하여 depth 낮추기, find 횟수를 인자로 관리하여 횟수 비교\n\t\t// 2-4 union count값이 노드개수에 도달하면 탐색 종료\n\tpublic static double[][] graph;\n\tpublic static int[] parent;\n\tpublic static double ans = 0.0;\n\t\n\tpublic static int find(double d) {\n\t\tif (parent[(int) d] == (int) d) {\n\t\t\treturn (int) d;\n\t\t} \n\t\treturn parent[(int) d] = find(parent[(int) d]);\n\t}\n\t\n\tpublic static void union(int a, int b) {\n\t\tif (a < b) {\n\t\t\tparent[a] = b;\n\t\t} else {\n\t\t\tparent[b] = a;\n\t\t}\n\t}\n\t\n\tpublic static void main(String[] args) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringTokenizer st;\n\t\tint tc = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor (int t = 1; t <= tc; t++) {\n\t\t\tint n = Integer.parseInt(br.readLine());\n\t\t\tint[] xs = new int[n], ys = new int[n];\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\txs[i] = Integer.parseInt(st.nextToken());\n\t\t\t}\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tys[i] = Integer.parseInt(st.nextToken());\n\t\t\t}\n\t\t\tdouble E = Double.parseDouble(br.readLine());\n\t\t\t\n\t\t\t\n\t\t\tgraph = new double[(n*n - n)/2][3];\n\t\t\tparent = new int[n];\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tparent[i] = i;\n\t\t\t}\n\t\t\t\n\t\t\tint cnt = 0;\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tint x = xs[i], y = ys[i];\n\t\t\t\tfor (int j = i+1; j < n; j++) {\n\t\t\t\t\tint cx = xs[j], cy = ys[j];\n\t\t\t\t\tgraph[cnt][0] = i;\n\t\t\t\t\tgraph[cnt][1] = j;\n\t\t\t\t\tgraph[cnt][2] = E * (Math.pow(x-cx, 2) + Math.pow(y - cy, 2));\n\t\t\t\t\tcnt++;\n\t\t\t\t}\n\t\t\t}\n\t\t\tArrays.sort(graph, (o1,o2) -> Double.compare(o1[2], o2[2]));\n\t\t\t\n\t\t\tint edgeCnt = 0;\n\t\t\tfor (double[] d : graph) {\n\t\t\t\tif (edgeCnt == n-1) break;\n\t\t\t\tint x = find(d[0]), y = find(d[1]);\n\t\t\t\tif (x != y) {\n\t\t\t\t\tunion(x,y);\n\t\t\t\t\tans += d[2];\n\t\t\t\t\tedgeCnt++;\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(Math.round(ans));\n\t\t\tSystem.out.println(sb);\n\t\t\tans = 0.0;\n\t\t}\n\t\t\n\t}\n\t\n\t\n\t\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA1251.java","lines":146,"code":"import java.util.*;\nimport java.io.*;\n\n\n/*\n * 시행착오: 문제를 보고 오토에버에서 본 크루스칼 알고리즘인 것 같아서 관련 내용 및 기본 코드를 공부 후 풀이 진행\n * Edge 클래스에서 compareTo를 this.cost - e.cost로 작성했다가 반환형이 맞지 않아 Long.compare(this.cost, e.cost);로 변경\n * 이후에 세율을 간선 비용 구할떄 넣어놨는데 리턴타입이 맞지 않아 에러 발생 \n * -> 간선 비용에서는 계산하지 않고 마지막에 구한 값에 * 세율을 곱하고 Math.round() 적용\n */\npublic class SWEA1251 {\n\tstatic int N;\n\tstatic ArrayList<Edge> edgeList;\n\tstatic int[] parent;\n\t\n\tstatic class Edge implements Comparable<Edge>{\n\t\t\n\t\tint from;\n\t\tint to;\n\t\tlong cost; // 간선의 비용\n\t\t\n\t\tEdge(int from, int to, long cost){\n\t\t\tthis.from = from;\n\t\t\tthis.to = to;\n\t\t\tthis.cost = cost;\n\t\t}\n\t\t\n\t\t@Override\n\t\tpublic int compareTo(Edge e) {\n\t\t\treturn Long.compare(this.cost, e.cost);\n\t\t}\n\t}\n\t\n\tpublic static void main(String[] args) throws IOException {\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint T = Integer.parseInt(br.readLine());\n\t\tStringTokenizer st;\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tedgeList = new ArrayList<>();\n\t\t\t\n\t\t\tN = Integer.parseInt(br.readLine());\n\t\t\t\n\t\t\tint[][] node = new int[N + 1][2];\n\t\t\t\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\n\t\t\tfor(int i = 1; i <= N; i++) {\n\t\t\t\tnode[i][0] = Integer.parseInt(st.nextToken()); // i번 노드의 x좌표\n\t\t\t}\n\t\t\t\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\n\t\t\tfor(int i = 1; i <= N; i++) {\n\t\t\t\tnode[i][1] = Integer.parseInt(st.nextToken()); // i번 노드의 y좌표\n\t\t\t}\n\t\t\t\n\t\t\tdouble rate = Double.parseDouble(br.readLine());\n\t\t\t\n\t\t\tfor(int i = 1; i < N; i++) {\n\t\t\t\tfor(int j = i + 1; j <= N; j++) {\n\t\t\t\t\tcalculateCost(node, i, j);\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tCollections.sort(edgeList);\n\t\t\t\n\t\t\tparent = new int[N + 1];\n\t\t\t\n\t\t\tfor(int i = 1; i <= N; i++) {\n\t\t\t\tparent[i] = i; // 부모를 자기 자신으로 초기화\n\t\t\t}\n\t\t\t\n\t\t\tlong totalDistance = kruskal(parent);\n\t\t\t\n\t\t\tlong result = Math.round(totalDistance * rate);\n\t\t\t\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(result).append(\"\\n\");\n\t\t}\n\t\t\n\t\tSystem.out.print(sb);\n\t}\n\t\n\tstatic void calculateCost(int[][] node, int i, int j) {\n\t\t\n\t\tlong distanceX = (long)node[i][0] - node[j][0];\n\t\tlong distanceY = (long)node[i][1] - node[j][1];\n\t\t\n\t\tlong cost = distanceX * distanceX + distanceY * distanceY;\n\t\t\n\t\tedgeList.add(new Edge(i, j, cost));\n\t}\n\t\n\tstatic long kruskal(int[] parent) {\n\t\t\n\t\tlong cost = 0;\n\t\tint edgeCnt = 0;\n\t\t\n\t\tfor(int i = 0; i < edgeList.size(); i++) {\n\t\t\t\n\t\t\tEdge edge = edgeList.get(i);\n\t\t\t\n\t\t\tint from = edge.from;\n\t\t\tint to = edge.to;\n\t\t\tlong weight = edge.cost;\n\t\t\t\n\t\t\tif(find(parent, from) != find(parent, to)) {\n\t\t\t\t\n\t\t\t\tunion(parent, from, to);\n\t\t\t\t\n\t\t\t\tcost += weight;\n\t\t\t\tedgeCnt++;\n\t\t\t\t\n\t\t\t\tif(edgeCnt == N - 1) {\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t\n\t\treturn cost;\n\t}\n\t\n\tstatic int find(int[] parent, int x) {\n\t\t\n\t\tif(parent[x] == x) {\n\t\t\treturn x;\n\t\t}\n\t\t\n\t\treturn parent[x] = find(parent, parent[x]);\n\t}\n\t\n\tstatic void union(int[] parent, int x, int y) {\n\t\t\n\t\tx = find(parent, x);\n\t\ty = find(parent, y);\n\t\t\n\t\tif(x < y) {\n\t\t\tparent[y] = x;\n\t\t}else {\n\t\t\tparent[x] = y;\n\t\t}\n\t}\n}","review":null}],"teamFeedback":null},{"key":"swea/1767","platform":"swea","problemId":"1767","title":"프로세서 연결하기","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA1767.java","lines":170,"code":"/*\n\n프로세서 연결하기 7/27\n40,452kb 284ms\n\n전략\n- 완전탐색 백트래킹\n    - 각 코어의 모든 선택지를 모든 코어에 대해 백트래킹하여 탐색한다\n- 그리드의 가장자리에 있는 코어는 결과값에 영향을 주지 못하기 때문에 백트래킹 목록에서 제외한다\n- 풀이 로직\n    - 백트래킹 인자로 인덱스, 코어 배열, 전원이 연결된 코어 개수를 넘긴다\n    - 코어 배열에서 현재 인덱스의 코어를 꺼내서 상하좌우 4방향에 대해 전원 연결이 가능한지 검사(canConnect 함수)\n    - 전원 연결이 가능하다면 해당 경로의 board를 2로 업데이트(connect 함수)\n    - 인덱스 1 추가해서 재귀 호출\n    - board에서 연결했던 전선을 다시 빈칸으로 초기화(unconnect 함수)\n    - 상하좌우 4방향을 다 돌았으면, 아예 연결하지 않고 넘어가는 재귀 호출 진행\n    - 만약 인덱스를 끝까지 다 돌았다면 종료 조건 검사\n        - 전원이 연결된 코어 개수가 기존 답변보다 많으면 무조건 갱신\n        - 전원이 연결된 코어 개수가 기존 답변과 같으면 더 전선 수가 적은 쪽으로 갱신\n        - 전원이 연결된 코어 개수가 기존 답변보다 적으면 결과 버림\n\n시행착오\n- 처음에는 상하좌우만 탐색했는데 최적의 답을 절대 얻을 수가 없었음. 이후 “코어에 연결을 아예 하지 않는다”라는 선택지를 상하좌우에 더해 추가해서 총 5번의 탐색을 진행해서 해결\n- 기존에는 코어가 가장자리에 위치하면 해당 코어는 탐색 스킵하고 백트래킹 깊이 하나 더 들어가는 식으로 구현했는데, 상하좌우무 문제 시행착오하는 과정에서 가장자리 코어는 아예 cores 배열에 추가를 안해버려도 답변에 차이가 없다는 사실을 깨닫고 수행 시간을 약간 줄일 수 있었음\n\n*/\n\nimport java.io.*;\nimport java.util.*;\n\npublic class SWEA1767 {\n\tstatic int[] dx = {-1, 1, 0, 0};\n\tstatic int[] dy = {0, 0, -1, 1};\n\tstatic int[][] board;\n\tstatic int result;\n\tstatic int lineCnt;\n\tstatic int completeResult;\n\t\n\tpublic static void main(String[] args) throws Exception{\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int t = 1; t <= T; t++) {\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tboard = new int[N][N];\n\t\t\tresult = Integer.MAX_VALUE;\n\t\t\tcompleteResult = 0; // 전선 수가 result였을 때 연결 완료된 코어의 개수\n\t\t\tlineCnt = 0; // 현재 전선 수\n\t\t\tList<int[]> cores = new ArrayList<>();\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\t\tfor(int j = 0; j < N; j++) {\n\t\t\t\t\tboard[i][j] = Integer.parseInt(st.nextToken());\n\t\t\t\t\t\n\t\t\t\t\tif(board[i][j] == 1) {\n\t\t\t\t\t\t// 코어가 가장자리에 있으면 cores에 아예 추가하지 않음\n\t\t\t\t\t\t// 가장자리의 코어는 장애물 역할 말고는 아예 영향 없기 때문\n\t\t\t\t\t\tif(i == 0 && i == N - 1 && j == 0 && j == N - 1) continue;\n\t\t\t\t\t\tcores.add(new int[] {i, j});\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tbacktrack(0, cores, 0);\n\t\t\t\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(result).append(\"\\n\");\n\t\t}\n\t\t\n\t\tSystem.out.print(sb);\n\t}\n\t\n\t// 현재 {x, y} 에서 direction 방향으로 뻗었을 때 전력이 연결될 수 있는지 여부를 반환\n\tprivate static boolean canConnect(int x, int y, int direction) {\n\t\tboolean result = true;\n\t\t\n\t\tfor(int i = 1; i < board.length; i++) {\n\t\t\tint nx = x + dx[direction] * i;\n\t\t\tint ny = y + dy[direction] * i;\n\t\t\t\n\t\t\tif(nx < 0 || nx >= board.length || ny < 0 || ny >= board.length) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\t\n\t\t\tif(board[nx][ny] != 0) {\n\t\t\t\tresult = false;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\t\n\t\treturn result;\n\t}\n\t\n\t// canConnect가 true면 해당 입력대로 실제로 board를 수정\n\tprivate static int connect(int x, int y, int direction) {\n\t\tint count = 0;\n\t\t\n\t\tfor(int i = 1; i < board.length; i++) {\n\t\t\tint nx = x + dx[direction] * i;\n\t\t\tint ny = y + dy[direction] * i;\n\t\t\t\n\t\t\tif(nx < 0 || nx >= board.length || ny < 0 || ny >= board.length) {\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\t\n\t\t\tboard[nx][ny] = 2;\n\t\t\tcount++;\n\t\t}\n\t\t\n\t\treturn count;\n\t}\n\t\n\t// 백트래킹 depth 1 추가 이후 원상태로 되돌리기\n\tprivate static void unconnect(int x, int y, int direction, int length) {\n\t\tfor(int i = 1; i <= length; i++) {\n\t\t\tint nx = x + dx[direction] * i;\n\t\t\tint ny = y + dy[direction] * i;\n\t\t\t\n\t\t\tboard[nx][ny] = 0;\n\t\t}\n\t}\n\t\n\tprivate static void backtrack(int i, List<int[]> cores, int completeCnt) {\n\t\t// 종료 조건 : 마지막 코어까지 다 방문 완료\n\t\tif(i == cores.size()) {\n\t\t\t// 전원 연결된 코어 개수가 더 많으면 전선 수와 상관없이 갱신\n\t\t\tif(completeResult < completeCnt) {\n\t\t\t\tcompleteResult = completeCnt;\n\t\t\t\tresult = lineCnt;\n\t\t\t}\n\t\t\t// 전원 연결된 코어 개수가 같으면 전선 수가 더 작은 쪽으로 갱신\n\t\t\telse if(completeResult == completeCnt) {\n\t\t\t\tresult = Math.min(result, lineCnt);\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t\n\t\tint[] core = cores.get(i);\n\t\tint x = core[0];\n\t\tint y = core[1];\n\t\t\n\t\tif(x == 0 || y == 0 || x == board.length - 1 || y == board.length - 1) {\n\t\t\tbacktrack(i + 1, cores, completeCnt + 1);\n\t\t\treturn;\n\t\t}\n\t\t\n\t\t// 현재 코어에서 4방향 탐사\n\t\tfor(int j = 0; j < 4; j++) {\n\t\t\t// 만약 해당 방향으로 전선 뻗었을 때 전원 연결이 가능하면\n\t\t\tif(canConnect(x, y, j)) {\n\t\t\t\t// 전원 연결하고 전선 개수만큼 lineCnt 증가\n\t\t\t\tint len = connect(x, y, j);\n\t\t\t\tlineCnt += len;\n\t\t\t\t\n\t\t\t\t// 백트래킹 깊이 1 더 들어가기\n\t\t\t\tbacktrack(i + 1, cores, completeCnt + 1);\n\t\t\t\t\n\t\t\t\t// 연결했던 전선을 다시 0으로 돌리고 lineCnt 감소\n\t\t\t\tlineCnt -= len;\n\t\t\t\tunconnect(x, y, j, len);\n\t\t\t}\n\t\t}\n\t\t\n\t\t// * 연결하지 않고 넘어가기 로직 추가\n\t\tbacktrack(i + 1, cores, completeCnt);\n\t}\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA1767.java","lines":127,"code":"import java.util.*;\nimport java.io.*;\n\n/*\n * 각 Core의 위치에 상하좌우중에 가장 가까운 곳 길이의 합\n * \n * 멕시노스: n * n\n * 빈 cell: 0, core: 1\n * \n * 알고리즘: 백트래킹\n * \n * 1. \n */\nimport java.util.*;\nimport java.io.*;\n/*\n * 각 Core를 상하좌우 중 한 방향으로 격자 밖까지 연결 (전선끼리 교차 불가)\n * 1순위: 연결한 코어 개수 최대 / 2순위: 전선 길이 합 최소\n * \n * 멕시노스: n * n\n * 빈 cell: 0, core: 1, 전선: 2\n * \n * 알고리즘: 백트래킹\n * \n * 1. 가장자리 코어는 전선 0으로 이미 연결 → 탐색 대상에서 제외\n * 2. 내부 코어마다 4방향 + 포기 = 5지선다 완전탐색\n * 3. 경로 칠하기 → 재귀 → 되돌리기\n */\npublic class SWEA1767 {\n\tstatic int[] dx = {-1, 0, 1, 0};\n\tstatic int[] dy = {0, -1, 0, 1};\n\tstatic int[][] arr; // 격자판\n\tstatic List<int[]> cores; // 탐색 대상 코어 좌표\n\tstatic int maxCore; // 연결한 코어 개수 최대값\n\tstatic int minLen; // maxCore개 연결 시 최소 전선 길이\n\tstatic int n;\n\tpublic static void main(String args[]) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\tStringTokenizer st;\n\t\t\n\t\tint t = Integer.parseInt(br.readLine());\n\t\tfor(int tc=1; tc<=t; tc++) {\n\t\t\tn = Integer.parseInt(br.readLine());\n\t\t\t\n\t\t\tarr = new int[n][n];\n\t\t\tcores = new ArrayList<>();\n\t\t\tmaxCore = 0;\n\t\t\tminLen = Integer.MAX_VALUE;\n\t\t\t\n\t\t\tfor(int i=0; i<n; i++) {\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\tfor(int j=0; j<n; j++) {\n\t\t\t\t\tarr[i][j] = Integer.parseInt(st.nextToken()); \n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t// 가장자리 제외한 내부 코어만 수집\n\t\t\tfor(int i=1; i<n-1; i++) {\n\t\t\t\tfor(int j=1; j<n-1; j++) {\n\t\t\t\t\tif(arr[i][j] == 1) {\n\t\t\t\t\t\tcores.add(new int[]{i, j});\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tdfs(0, 0, 0);\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(minLen).append(\"\\n\");\n\t\t}\n\t\tSystem.out.print(sb);\n\t}\n\t\n\tstatic void dfs(int idx, int cnt, int sum) {\n\t\tif(idx == cores.size()) {\n\t\t\tif(cnt > maxCore) {\n\t\t\t\tmaxCore = cnt;\n\t\t\t\tminLen = sum;\n\t\t\t} else if(cnt == maxCore) {\n\t\t\t\tminLen = Math.min(minLen, sum);\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t\n\t\t// 남은 코어 다 연결해도 최대치 못 넘으면 컷\n\t\tif(cnt + (cores.size() - idx) < maxCore) return;\n\t\t\n\t\tint x = cores.get(idx)[0];\n\t\tint y = cores.get(idx)[1];\n\t\t\n\t\tfor(int d=0; d<4; d++) {\n\t\t\tint len = check(x, y, d);\n\t\t\tif(len == -1) continue;\n\t\t\t\n\t\t\tfill(x, y, d, 2);\n\t\t\tdfs(idx+1, cnt+1, sum+len);\n\t\t\tfill(x, y, d, 0);\n\t\t}\n\t\t\n\t\tdfs(idx+1, cnt, sum); // 이 코어는 연결 포기\n\t}\n\t\n\t// d방향으로 밖까지 뚫려있으면 길이, 막히면 -1\n\tstatic int check(int x, int y, int d) {\n\t\tint len = 0;\n\t\tint nx = x + dx[d];\n\t\tint ny = y + dy[d];\n\t\t\n\t\twhile(nx >= 0 && nx < n && ny >= 0 && ny < n) {\n\t\t\tif(arr[nx][ny] != 0) return -1;\n\t\t\tlen++;\n\t\t\tnx += dx[d];\n\t\t\tny += dy[d];\n\t\t}\n\t\treturn len;\n\t}\n\t\n\tstatic void fill(int x, int y, int d, int val) {\n\t\tint nx = x + dx[d];\n\t\tint ny = y + dy[d];\n\t\t\n\t\twhile(nx >= 0 && nx < n && ny >= 0 && ny < n) {\n\t\t\tarr[nx][ny] = val;\n\t\t\tnx += dx[d];\n\t\t\tny += dy[d];\n\t\t}\n\t}\n}","review":null},{"author":"seongil","authorName":"이성일","week":1,"variant":null,"source":"이성일/week1/SWEA1767.java","lines":133,"code":"package swtb;\n\nimport java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.util.Arrays;\nimport java.util.StringTokenizer;\n\n/*\n어려웠거나 몰랐던 점:\n1.자바로 짜는 알고리즘에 익숙하지 않아 최적화 된 설계에 확신이 없다\n2. 성급하게 코드나 논리를 짜려는 경향, 확실하게 검증된 논리와 코드만 사용하기\n3. 엣지케이스 -> 엣지로직 (전체 범위를 아우르는 로직) */\n\npublic class SWEA1767 {\n\t\n\tpublic static int[] ans = {0,144};\n\t\n\tpublic static int[] dx = {-1, 0, 1, 0};\n\tpublic static int[] dy = {0, 1, 0,  -1};\n\t\n\tpublic static boolean isSearchable(int[][] board, int x, int y, int vx, int vy) {\n\t\tx += vx; y += vy;\n\t\twhile (x >= 0 && x < board.length && y >= 0 && y < board.length) {\n\t\t\tif (board[x][y] != 0) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tx += vx;\n\t\t\ty += vy;\n\t\t}\n\t\treturn true;\n\t\t\n\t}\n\t\n\tpublic static int draw(int[][] board, int x, int y, int vx, int vy, int draw) {\n\t\tx += vx; y += vy;\n\t\tint wires = 0;\n\t\twhile (x >= 0 && x < board.length && y >= 0 && y < board.length) {\n\t\t\tboard[x][y] = draw;\n\t\t\twires+=1;\n\t\t\tx += vx; y += vy;\n\t\t}\n\t\treturn wires;\n\t\t\n\t}\n\t\n\t\n\t// 3. 노드인덱스 리스트 기준 DFS 진행하기\n\t\t\t// 3-1. 각 노드 기준 4방향 탐색\n\t\t\t\t// 3-1-2. 방향 인덱스 별로 탐색 후, 0일 경우 -1로 표기 후 다음 탐색 진행\n\t\t\t\t// 3-1-3. 탐색 불가 방향일 경우, 미 탐색으로 상태 진행\n\t\t\t\t// 3-1-4. 롤백, 미탐색 스테이지는 함수 인자값만\n\t\t\t// 3-2. 모든 노드 탐색 완료 시 최대노드 수와 비교 후 (동일 시 전선길이 최소값으로) 탐색 종료\n\tpublic static void dfs(int nIdx, int searchCnt, int totalWires,\n\t\t\tint[][] board, int[] nodes) {\n\t\t\n\t\tint nodeLength = nodes.length / 2;\n\t\tif (nIdx == nodeLength) {\n\t\t\tif (ans[0] < searchCnt) {\n\t\t\t\tans[0] = searchCnt;\n\t\t\t\tans[1] = totalWires;\n\t\t\t} else if (ans[0] == searchCnt) {\n\t\t\t\tans[1] = Math.min(ans[1], totalWires);\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\t\n\t\tboolean flag = false;\n\t\tfor (int i = 0; i < dx.length; i++) {\n\t\t\tint x = nodes[nIdx * 2], y = nodes[nIdx * 2 + 1];\n\t\t\tint vx = dx[i], vy = dy[i];\n\t\t\tif (isSearchable(board, x, y, vx, vy)) {\n\t\t\t\tflag = true;\n\t\t\t\tint wires = draw(board, x,y,vx,vy,-1);\n\t\t\t\tdfs(nIdx+1, searchCnt+1, totalWires+wires, board, nodes);\n\t\t\t\tdraw(board,x,y,vx,vy,0);\n\t\t\t} else {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t}\n\t\tif (!flag) dfs(nIdx+1, searchCnt, totalWires, board, nodes);\n\t\t// *연결가능함에도 미연결하는 탐색이 필요할 수 있다.*\n\t\telse dfs(nIdx+1, searchCnt, totalWires, board, nodes);\n\t}\n\t\n\tpublic static void main(String[] args) throws Exception {\n\t\t// 1. 입출력 정의 (tc 입력 받기, 출력 양식은 #tc ans)\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint tc = Integer.parseInt(br.readLine());\n\t\t\n\t\t\n\t\t\n\t\t// 2. 보드 입력 받고, 노드 인덱스 관리 , 엣지 노드는 관리 x\n\t\tfor(int i = 1; i <=tc; i++) {\n\t\t\tint n = Integer.parseInt(br.readLine());\n\t\t\tint[][] board = new int[n][n];\n\t\t\tint[] nodes = new int[24];\n\t\t\tint nodeCnt = 0;\n\t\t\tint idx = 0;\n\t\t\tStringTokenizer st;\n\t\t\tfor (int r = 0; r < n; r++) {\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\tfor (int c = 0; c < n; c++) {\n\t\t\t\t\tint val = Integer.parseInt(st.nextToken());\n\t\t\t\t\tboard[r][c] = val;\n\t\t\t\t\tif ((val > 0) && (r > 0) && (r < (n -1)) &&\n\t\t\t\t\t\t\t(c > 0) && (c < (n - 1))) {\n\t\t\t\t\t\tnodes[idx++] = r;\n\t\t\t\t\t\tnodes[idx++] = c;\n\t\t\t\t\t\tnodeCnt++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t\tint[] rNodes = new int[nodeCnt*2];\n\t\t\tfor (int a = 0, b = 0; a < nodeCnt*2; a++) {\n\t\t\t\trNodes[b++] = nodes[a];\n\t\t\t}\n\t\t\t\n\n\t\t\tdfs(0,0,0,board,rNodes);\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(i).append(\" \").append(ans[1]).append(\"\\n\");\n\t\t\tSystem.out.print(sb);\n\t\t\t// static 변수 초기화로 테스트케이스별로 독립적인 실행\n\t\t\tans[0] = 0;\n\t\t\tans[1] = 0;\n\t\t}\n\t\t\t\n\t}\n\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA1767.java","lines":141,"code":"import java.io.*;\nimport java.util.*;\n\n/*\n * 어려웠던 점: 처음에 백트래킹하는 과정에서 초기화를 안해서 값이 꼬임, 이후에 리팩토링 하는 과정에서 탐색할 필요가 없는 경우에만 리턴하게 해야하는 데 미처 생각하지 못함\n * 함수 네이밍을 보통 내가 보기 편한대로 작성하였는데 스터디를 진행하면서 좀 더 와닿는 네이밍 명을 작성해될 것 같\n */\n\npublic class SWEA1767 {\n\n\tstatic int[][] map;\n\tstatic int N;\n\tstatic ArrayList<int[]> cores;\n\tstatic int result;\n\tstatic int maxConnected;\n\n\tstatic int[] dx = {-1, 1, 0, 0};\n\tstatic int[] dy = {0, 0, -1, 1};\n\n\tpublic static void main(String[] args) throws Exception {\n\n\t\tBufferedReader br = new BufferedReader(\n\t\t\t\tnew InputStreamReader(System.in)\n\t\t);\n\n\t\tint T = Integer.parseInt(br.readLine());\n\n\t\tfor (int tc = 1; tc <= T; tc++) {\n\n\t\t\tN = Integer.parseInt(br.readLine());\n\t\t\tmap = new int[N][N];\n\n\t\t\tfor (int i = 0; i < N; i++) {\n\t\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\n\t\t\t\tfor (int j = 0; j < N; j++) {\n\t\t\t\t\tmap[i][j] = Integer.parseInt(st.nextToken());\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tsimulate();\n\n\t\t\tSystem.out.println(\"#\" + tc + \" \" + result);\n\t\t}\n\t}\n\n\tstatic void simulate() {\n\n\t\tcores = new ArrayList<>();\n\n\t\tfor (int i = 1; i < N - 1; i++) {\n\t\t\tfor (int j = 1; j < N - 1; j++) {\n\t\t\t\tif (map[i][j] == 1) {\n\t\t\t\t\tcores.add(new int[]{i, j});\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tmaxConnected = 0;\n\t\tresult = Integer.MAX_VALUE;\n\n\t\tdfs(0, 0, 0);\n\t}\n\n\tstatic void dfs(int index, int connectedCnt, int wireLength) {\n\n\t\tint remain = cores.size() - index;\n\n\t\tif (connectedCnt + remain < maxConnected) {\n\t\t\treturn;\n\t\t}\n\n\t\tif (index == cores.size()) {\n\n\t\t\tif (connectedCnt > maxConnected) {\n\t\t\t\tmaxConnected = connectedCnt;\n\t\t\t\tresult = wireLength;\n\t\t\t} else if (connectedCnt == maxConnected) {\n\t\t\t\tresult = Math.min(result, wireLength);\n\t\t\t}\n\n\t\t\treturn;\n\t\t}\n\n\t\tint x = cores.get(index)[0];\n\t\tint y = cores.get(index)[1];\n\n\t\tfor (int dir = 0; dir < 4; dir++) {\n\n\t\t\tint length = check(x, y, dir);\n\n\t\t\tif (length > 0) {\n\n\t\t\t\tsetWire(x, y, dir, 2);\n\n\t\t\t\tdfs(index + 1,connectedCnt + 1,wireLength + length);\n\n\t\t\t\tsetWire(x, y, dir, 0);\n\t\t\t}\n\t\t}\n\n\t\tdfs(index + 1, connectedCnt, wireLength);\n\t}\n\n\tstatic int check(int x, int y, int dir) {\n\n\t\tint nx = x + dx[dir];\n\t\tint ny = y + dy[dir];\n\t\tint length = 0;\n\n\t\twhile (inRange(nx, ny)) {\n\n\t\t\tif (map[nx][ny] != 0) {\n\t\t\t\treturn 0;\n\t\t\t}\n\n\t\t\tlength++;\n\t\t\t\n\t\t\tnx += dx[dir];\n\t\t\tny += dy[dir];\n\t\t}\n\n\t\treturn length;\n\t}\n\n\tstatic void setWire(int x, int y, int dir, int value) {\n\n\t\tint nx = x + dx[dir];\n\t\tint ny = y + dy[dir];\n\n\t\twhile (inRange(nx, ny)) {\n\t\t\tmap[nx][ny] = value;\n\t\t\tnx += dx[dir];\n\t\t\tny += dy[dir];\n\t\t}\n\t}\n\n\tstatic boolean inRange(int x, int y) {\n\t\treturn x >= 0 && x < N && y >= 0 && y < N;\n\t}\n}","review":null}],"teamFeedback":null},{"key":"swea/5643","platform":"swea","problemId":"5643","title":"키 순서","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA5643.java","lines":92,"code":"/*\n전략\n- 모든 정점에 대해, 나보다 큰 사람의 수 찾기\n- 모든 정점에 대해, 나보다 작은 사람의 수 찾기\n- 큰 사람 + 작은 사람 == N - 1이면 자신을 제외한 모든 사람의 상대 위치를 알기 때문에 자신의 순위를 알 수 있다.\n*/\n\nimport java.util.*;\nimport java.io.*;\n\npublic class SWEA5643 {\n\tstatic List<List<Integer>> bigGraph;\n\tstatic List<List<Integer>> smallGraph;\n\tstatic boolean[] visited;\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\n\t\tint T = Integer.parseInt(br.readLine());\n\n\t\tfor (int t = 1; t <= T; t++) {\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tint M = Integer.parseInt(br.readLine());\n\t\t\tint result = 0;\n\n\t\t\tvisited = new boolean[N + 1];\n\t\t\tbigGraph = new ArrayList<>(); // 자신보다 큰 사람을 저장\n\t\t\tsmallGraph = new ArrayList<>(); // 자신보다 작은 사람을 저장\n\t\t\tfor (int i = 0; i <= N; i++) {\n\t\t\t\tbigGraph.add(new ArrayList<>());\n\t\t\t\tsmallGraph.add(new ArrayList<>());\n\t\t\t}\n\n\t\t\tfor (int i = 0; i < M; i++) {\n\t\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\t\tint u = Integer.parseInt(st.nextToken());\n\t\t\t\tint v = Integer.parseInt(st.nextToken());\n\n\t\t\t\tbigGraph.get(u).add(v);\n\t\t\t\tsmallGraph.get(v).add(u);\n\t\t\t}\n\n\t\t\tfor (int i = 1; i <= N; i++) {\n\t\t\t\tvisited[i] = true;\n\t\t\t\tint cnt = findBigCnt(i); // 자기보다 큰 사람 수 찾기\n\t\t\t\tcnt += findSmallCnt(i); // 자기보다 작은 사람 수 찾기\n\n\t\t\t\t// 자기보다 작은사람, 큰 사람 수가 N - 1이면 자신의 순위를 알 수 있음\n\t\t\t\tif (cnt == N - 1) { \n\t\t\t\t\tresult++;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\tvisited = new boolean[N + 1];\n\t\t\t}\n\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(result).append(\"\\n\");\n\t\t}\n\t\tSystem.out.print(sb);\n\t}\n\n\tstatic int findBigCnt(int i) {\n\t\tint cnt = 0;\n\n\t\tfor (int next : bigGraph.get(i)) {\n\t\t\t// 중복 세기 방지\n\t\t\tif(!visited[next]) {\n\t\t\t\tvisited[next] = true;\n\t\t\t\tcnt++;\n\t\t\t\tcnt += findBigCnt(next);\n\t\t\t}\n\t\t}\n\n\t\treturn cnt;\n\t}\n\n\tstatic int findSmallCnt(int i) {\n\t\tint cnt = 0;\n\n\t\tfor (int next : smallGraph.get(i)) {\n\t\t\t// 중복 세기 방지\n\t\t\tif(!visited[next]) {\n\t\t\t\tvisited[next] = true;\n\t\t\t\tcnt++;\n\t\t\t\tcnt += findSmallCnt(next);\n\t\t\t}\n\t\t}\n\n\t\treturn cnt;\n\t}\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA5643.java","lines":73,"code":"import java.util.*;\nimport java.lang.*;\nimport java.io.*;\n/*\n    *자신의 키가 몇 번째 인지 알 수 있는 학생이 모두 몇명인지\n\n    *알고리즘: DFS, 인접리스트\n*/\nclass SWEA5643 {\n    static List<Integer>[] up;\n    static List<Integer>[] down;\n    static boolean[] vis;\n    static int n, m;\n    static int cnt;\n    public static void main(String[] args) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        StringBuilder sb = new StringBuilder();\n        StringTokenizer st;\n        int t = Integer.parseInt(br.readLine());\n\n        for(int tc=1; tc<=t; tc++) {\n            n = Integer.parseInt(br.readLine()); // 학생 수\n            m = Integer.parseInt(br.readLine()); // 학생 키 비교 횟수\n\n            up = new List[n+1];\n            down = new List[n+1];\n            for(int i=1; i<=n; i++) {\n                up[i] = new ArrayList<>();\n                down[i] = new ArrayList<>();\n            }\n            \n            for(int i=0; i<m; i++) {\n                st = new StringTokenizer(br.readLine());\n                \n                int a = Integer.parseInt(st.nextToken());\n                int b = Integer.parseInt(st.nextToken());\n                up[a].add(b);\n                down[b].add(a);\n            }\n        \n            int answer = 0;\n            int total;\n            \n            for(int i=1; i<=n; i++) {\n                vis = new boolean[n+1];\n                cnt = 0;\n                vis[i] = true;\n                dfs(i, up);\n                total = cnt;\n                \n                vis = new boolean[n+1];\n                cnt = 0;\n                vis[i] = true;\n                dfs(i, down);\n                total += cnt;\n                \n                if(total == n-1) answer++;\n            }\n            sb.append(\"#\").append(tc).append(\" \").append(answer).append(\"\\n\");\n        }\n        System.out.println(sb.toString());\n    }\n    static void dfs(int node, List<Integer>[] graph) {\n        for(int next : graph[node]) {\n            if(!vis[next]) {\n                vis[next] = true;\n                cnt++;\n                dfs(next, graph);\n            }\n        }\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":1,"variant":null,"source":"이성일/week1/SWEA5643.java","lines":75,"code":"package com.ssafy.swb;\n\nimport java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Collections;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.StringTokenizer;\n\npublic class SWEA5643 {\n\n\tpublic static List<Set<Integer>> bigger = new ArrayList<>();\n\tpublic static List<Set<Integer>> smaller = new ArrayList<>();\n\tpublic static int ans = 0;\n\t\n\tpublic static void process(int small, int big) {\n\t\tbigger.get(small-1).add(big);\n\t\tfor (int s : smaller.get(small - 1)) {\n\t\t\tbigger.get(s-1).add(big);\n\t\t}\n\t\tfor (int b : bigger.get(big-1)) {\n\t\t\tbigger.get(small -1).add(b);\n\t\t\tfor (int s : smaller.get(small-1)) {\n\t\t\t\tbigger.get(s-1).add(b);\n\t\t\t}\n\t\t}\n\t\tsmaller.get(big-1).add(small);\n\t\tfor (int s : smaller.get(small -1)) {\n\t\t\tsmaller.get(big-1).add(s);\n\t\t}\n\t\tfor (int b : bigger.get(big-1)) {\n\t\t\tsmaller.get(b-1).add(small);\n\t\t\tfor (int s : smaller.get(small - 1)) {\n\t\t\t\tsmaller.get(b-1).add(s);\n\t\t\t}\n\t\t}\n\t}\n\tpublic static void main(String[] args) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringTokenizer st;\n\t\tint T = Integer.parseInt(br.readLine());\n\t\tfor (int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tint n = Integer.parseInt(br.readLine());\n\t\t\tint m = Integer.parseInt(br.readLine());\n\t\t\t\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tbigger.add(new HashSet<>());\n\t\t\t\tsmaller.add(new HashSet<>());\n\t\t\t}\n\t\t\t\n\t\t\tfor (int i = 0; i < m; i++) {\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\tint a = Integer.parseInt(st.nextToken()), b= Integer.parseInt(st.nextToken());\n\t\t\t\tprocess(a,b);\n\t\t\t}\n\t\t\t\n\t\t\tfor (int i = 0; i < n; i++) {\n\t\t\t\tif ((bigger.get(i).size() + smaller.get(i).size()) == (n - 1)) {\n\t\t\t\t\tans++;\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(ans);\n\t\t\tSystem.out.println(sb);\n\t\t\tans = 0;\n\t\t}\n\t}\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA5643.java","lines":87,"code":"import java.util.*;\nimport java.io.*;\n\n//연결요소 찾는 문제이므로 dfs or bfs로 둘다 풀이가능\n\npublic class SWEA5643 {\n\tstatic int N;\n\tstatic int M;\n\tstatic ArrayList<Integer>[] tallGraph;\n\tstatic ArrayList<Integer>[] shortGraph;\n\t\n\tpublic static void main(String[] args) throws IOException {\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint T = Integer.parseInt(br.readLine());\n\t\tStringTokenizer st;\n\t\t\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tN = Integer.parseInt(br.readLine());\n\t\t\tM = Integer.parseInt(br.readLine());\n\t\t\t\n\t\t\ttallGraph = new ArrayList[N + 1];\n\t\t\tshortGraph = new ArrayList[N + 1];\n\t\t\t\n\t\t\tfor(int i = 1; i <= N; i++) {\n\t\t\t\ttallGraph[i] = new ArrayList<>();\n\t\t\t\tshortGraph[i] = new ArrayList<>();\n\t\t\t}\n\t\t\t\n\t\t\tfor(int i = 0; i < M; i++) {\n\t\t\t\t\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\t\n\t\t\t\tint shorter = Integer.parseInt(st.nextToken());\n\t\t\t\tint taller = Integer.parseInt(st.nextToken());\n\t\t\t\t\n\t\t\t\t// shorter보다 키가 큰 학생\n\t\t\t\ttallGraph[shorter].add(taller);\n\t\t\t\t\n\t\t\t\t// taller보다 키가 작은 학생\n\t\t\t\tshortGraph[taller].add(shorter);\n\t\t\t}\n\t\t\t\n\t\t\tint result = 0;\n\t\t\t\n\t\t\tfor(int i = 1; i <= N; i++) {\n\t\t\t\t\n\t\t\t\tboolean[] visited = new boolean[N + 1];\n\t\t\t\tint tallerCnt = dfs(i, tallGraph, visited);\n\t\t\t\t\n\t\t\t\tvisited = new boolean[N + 1];\n\t\t\t\tint shorterCnt = dfs(i, shortGraph, visited);\n\t\t\t\t\n\t\t\t\tif(tallerCnt + shorterCnt == N - 1) {\n\t\t\t\t\tresult++;\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(result);\n\t\t\tSystem.out.println(sb);\n\t\t\t  \n\t\t}\n\t\t\n\t\t\n\t}\n\t\n\tstatic int dfs(int current, ArrayList<Integer>[] currentGraph,\n\t\t\tboolean[] visited) {\n\t\t\n\t\tvisited[current] = true;\n\t\tint count = 0;\n\t\t\n\t\tfor(Integer next : currentGraph[current]) {\n\t\t\t\n\t\t\tif(!visited[next]) {\n\t\t\t\tcount++;\n\t\t\t\tcount += dfs(next, currentGraph, visited);\n\t\t\t}\n\t\t}\n\t\t\n\t\treturn count;\n\t}\n}","review":null}],"teamFeedback":null},{"key":"swea/5653","platform":"swea","problemId":"5653","title":"줄기세포배양","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA5653.java","lines":169,"code":"/*\n전략\n- 시뮬레이션 구현, 우선순위 큐\n- 격자의 범위 제한 [351][351]\n    - 최대 초기 영역이 50 x 50, 최대 시간이 300\n    - 150 - 50 - 150 만큼 50 영역에서 양쪽으로 뻗을 수 있다\n    - 따라서 최대 격자 크기는 350 x 350\n    - 시작 범위는 [151, 151] ~ [200, 200] ⇒ [150 + x][150 + y]\n- 비활성 상태 노드 큐, 활성 상태 노드 우선순위 큐, 사망 예정 큐로 총 큐 3개를 사용\n    - 우선순위 큐로 최대 생명력 수치가 높은 세포에 우선권을 부여\n- 비활성 만들어질 때 세포 수를 세고, 사망할 때 세포 수를 세서 비활성 - 사망을 하면 결과\n\n자료구조\n- Cell\n    - x, y\n    - hp = 해당 세포의 생명력 수치\n    - currHp = 해당 세포의 현재 생명력 수치(매턴 1 감소, 0 되면 다음 상태로 전환)\n    - Comparable<Cell> 구현 → compareTo(Cell c) 오버라이드\n- 비활성 상태 노드 큐, 활성 상태 노드 우선순위 큐, 사망 예정 노드 큐\n    - 생명력 수치 높은게 우선 점거할 수 있도록 활성 큐는 우선순위 큐로 구현\n*/\n\nimport java.io.;\nimport java.util.;\n\nclass Cell implements Comparable<Cell>{\npublic int x;\npublic int y;\npublic int hp;\npublic int currHp;\n\nCell(int x, int y, int hp){\nthis.x = x;\nthis.y = y;\nthis.hp = hp;\nthis.currHp = hp;\n}\n\n@Override\npublic int compareTo(Cell c) {\n// hp가 더 큰 쪽이 앞으로 오게 정렬\n// 같은 턴이면 hp가 더 큰 쪽이 셀 점유에 우선권이 있음\nreturn -1 * Integer.compare(hp, c.hp);\n}\n}\n\npublic class SWEA5653 {\t\nstatic int[] dx = new int[] {-1, 1, 0, 0};\nstatic int[] dy = new int[] {0, 0, -1, 1};\n\npublic static void main(String[] args) throws Exception{\nBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\nStringBuilder sb = new StringBuilder();\n\nint T = Integer.parseInt(br.readLine());\n\nfor(int t = 1; t <= T; t++) {\nStringTokenizer st = new StringTokenizer(br.readLine());\nint N = Integer.parseInt(st.nextToken());\nint M = Integer.parseInt(st.nextToken());\nint K = Integer.parseInt(st.nextToken());\n\nboolean[][] visited = new boolean[351][351];\nQueue<Cell> sleeps = new ArrayDeque<>();\nQueue<Cell> unactives = new ArrayDeque<>();\nPriorityQueue<Cell> actives = new PriorityQueue<>();\n\nint dead = 0;\nint live = 0;\n\n// 초기 상태 입력\nfor(int i = 0; i < N; i++) {\nst = new StringTokenizer(br.readLine());\nfor(int j = 0; j < M; j++) {\nint curr = Integer.parseInt(st.nextToken());\n\nif(curr != 0) {\nvisited[i + 150][j + 150] = true;\nunactives.add(new Cell(i + 150, j + 150, curr));\nlive++;\n}\n}\n}\n\n// K만큼 턴 진행\nint turn = 0;\nwhile(turn < K) {\nturn++;\n\n// 사망 예정 큐 처리\n// 사망 예정 = 더이상 번식이 불가능한 활성 세포\nint len = sleeps.size();\nfor(int l = 0; l < len; l++) {\nCell c = sleeps.poll();\nc.currHp--;\n\nif(c.currHp > 0) {\nsleeps.offer(c);\n}\n// 생명력이 0이 됐으면 사망 처리\nelse {\ndead++;\n}\n}\n\n\n// 활성 큐 처리\nlen = actives.size();\nfor(int l = 0; l < len; l++) {\nCell c = actives.poll();\nc.currHp--;\n\n// 상하좌우 4방향에 번식\nfor(int i = 0; i < 4; i++) {\nint nx = c.x + dx[i];\nint ny = c.y + dy[i];\n\n// 비어있는 곳에 번식\nif(!visited[nx][ny]) {\nvisited[nx][ny] = true;\nlive++;\n\n// 아래 비활성 큐 로직 처리에서 같은 턴에 처리되는 거 방지용 -1 처리\nCell next = new Cell(nx, ny, c.hp);\nnext.currHp = -1;\nunactives.offer(next);\n}\n}\n\n// 활성 세포의 현재 생명력이 0이면 바로 사망\nif(c.currHp == 0) {\ndead++;\n}\n// 아닌 경우 번식 완료했으므로 사망 예정으로 이동\nelse {\nsleeps.offer(c);\n}\n}\n\n// 비활성 큐 처리\nlen = unactives.size();\nfor(int l = 0; l < len; l++) {\nCell c = unactives.poll();\n\n// 이번 턴에 추가된 세포면 처리하지 않음\nif(c.currHp == -1) {\nc.currHp = c.hp;\nunactives.offer(c);\ncontinue;\n}\n\nc.currHp--;\n\n// 현재 생명력이 0이면 비활성->활성 전환\nif(c.currHp == 0) {\nc.currHp = c.hp;\nactives.offer(c);\n}\nelse {\nunactives.offer(c);\n}\n}\t\n}\nsb.append(\"#\").append(t).append(\" \").append(live - dead).append(\"\\n\");\n}\nSystem.out.print(sb);\n}\n}","review":null}],"teamFeedback":null},{"key":"swea/5656","platform":"swea","problemId":"5656","title":"벽돌 깨기","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA5656.java","lines":186,"code":"/*\n전략\n- 완전탐색 백트래킹\n- 구슬이 갈 수 있는 모든 열의 경우의 수를 완전탐색\n- board의 상태를 저장해두었다가 백트래킹할 때 복구하기\n\n시행착오\n- System.arraycopy로 바로 2차원 배열을 복사했었는데 실제로 배열 내의 배열까지 깊은 복사가 안되고 있었다.\n  이를 해결하기 위해 2차원 배열의 각 1차원 배열을 for문으로 순회하며 깊은 복사를 진행해서 해결했다.\n- 구현 과정과 디버깅이 많이 복잡해서 변수나 조건문의 수치를 조정하는 데에 많은 시간을 썼다.\n*/\n\nimport java.io.*;\nimport java.util.*;\n\npublic class SWEA5656 {\n\tstatic int[] dx = new int[] { -1, 1, 0, 0 };\n\tstatic int[] dy = new int[] { 0, 0, -1, 1 };\n\tstatic int N, W, H;\n\tstatic int[][] board;\n\tstatic int result;\n\tstatic int total;\n\n\tpublic static void main(String[] args) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\n\t\tint T = Integer.parseInt(br.readLine());\n\n\t\tfor (int t = 1; t <= T; t++) {\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\tN = Integer.parseInt(st.nextToken());\n\t\t\tW = Integer.parseInt(st.nextToken());\n\t\t\tH = Integer.parseInt(st.nextToken());\n\n\t\t\tboard = new int[H][W];\n\t\t\tresult = Integer.MAX_VALUE;\n\t\t\ttotal = 0;\n\n\t\t\tfor (int i = 0; i < H; i++) {\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\tfor (int j = 0; j < W; j++) {\n\t\t\t\t\tboard[i][j] = Integer.parseInt(st.nextToken());\n\t\t\t\t\n\t\t\t\t\tif(board[i][j] > 0) {\n\t\t\t\t\t\ttotal++;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\n\t\t\t// 2차원 배열이라 각 배열 요소에 깊은 복사 필요\n\t\t\tint[][] prevBoard = new int[H][W];\n\t\t\tfor(int i = 0; i < H; i++) {\n\t\t\t\tSystem.arraycopy(board[i], 0, prevBoard[i], 0, W);\n\t\t\t}\n\n\t\t\tfor (int w = 0; w < W; w++) {\n\t\t\t\t// 백트래킹 깊이, 어느 열에 던질지, 현재까지 파괴한 벽돌 수\n\t\t\t\tbacktrack(0, w, 0); \n\t\t\t\t\n\t\t\t\t// board 복구\n\t\t\t\tfor(int i = 0; i < H; i++) {\n\t\t\t\t\tSystem.arraycopy(prevBoard[i], 0, board[i], 0, W);\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(result).append(\"\\n\");\n\t\t}\n\t\tSystem.out.print(sb);\n\t}\n\n\tprivate static void backtrack(int depth, int index, int brick) {\n\t\tif(depth == N) {\n\t\t\tresult = Math.min(result, (total - brick));\n\t\t\treturn;\n\t\t}\n\t\t\n\t\t// index 열의 가장 위의 벽돌 찾기\n\t\tint[] top = null;\n\t\tfor(int i = 0; i < H; i++) {\n\t\t\tif(board[i][index] >= 1) {\n\t\t\t\ttop = new int[3];\n\t\t\t\ttop[0] = i;\n\t\t\t\ttop[1] = index;\n\t\t\t\ttop[2] = board[i][index];\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\t\n\t\t// 만약 빈 열이면 현재를 기준으로 결과 갱신\n\t\t// ex) 0 0 0 1인 문제인데 공 3개 던져야 하면 이런 경우 필요함\n\t\tif(top == null) {\n\t\t\tresult = Math.min(result, (total - brick));\n\t\t\treturn;\n\t\t}\n\t\t\n\t\tQueue<int[]> queue = new ArrayDeque<>();\n\t\tqueue.offer(top);\n\t\tbrick++;\n\t\tboard[top[0]][top[1]] = 0;\n\t\t\n\t\t// 벽돌 제거\n\t\twhile(!queue.isEmpty()) {\n\t\t\tint[] curr = queue.poll();\n\t\t\t\n\t\t\t// 벽돌 숫자가 1이면 해당 벽돌만 제거하고 종료\n\t\t\tif(curr[2] == 1) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\t\n\t\t\t// 벽돌 숫자가 2 이상이면 십자로 벽돌을 제거하고\n\t\t\t// 터트린 벽돌을 queue에 추가해서 연쇄 제거 구현\n\t\t\tfor(int i = 0; i < 4; i++) {\n\t\t\t\tfor(int j = 1; j < curr[2]; j++) {\n\t\t\t\t\tint nx = curr[0] + dx[i] * j;\n\t\t\t\t\tint ny = curr[1] + dy[i] * j;\n\t\t\t\t\t\n\t\t\t\t\tif(!inRange(nx, ny)) {\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t\t\n\t\t\t\t\tif(board[nx][ny] > 0) {\n\t\t\t\t\t\tqueue.offer(new int[] {nx, ny, board[nx][ny]});\n\t\t\t\t\t\tbrick++;\n\t\t\t\t\t\tboard[nx][ny] = 0;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t\n\t\tgravity();\n\t\t\n\t\t// 현재 board를 백업\n\t\tint[][] prevBoard = new int[H][W];\n\t\tfor(int i = 0; i < H; i++) {\n\t\t\tSystem.arraycopy(board[i], 0, prevBoard[i], 0, W);\n\t\t}\n\t\t\n\t\t// 모든 열에 다음 구슬 던지기\n\t\tfor(int w = 0; w < W; w++) {\n\t\t\t\n\t\t\tbacktrack(depth + 1, w, brick);\n\t\t\t\n\t\t\t// board 복구하기\n\t\t\tfor(int i = 0; i < H; i++) {\n\t\t\t\tSystem.arraycopy(prevBoard[i], 0, board[i], 0, W);\n\t\t\t}\n\t\t}\n\t}\n\n\tprivate static void gravity() {\n\t\t// board의 모든 칸을 역순으로 돌며\n\t\tfor (int i = H - 1; i >= 0; i--) {\n\t\t\tfor (int j = W - 1; j >= 0; j--) {\n\t\t\t\t// 현재 칸이 맨 밑이면 스킵\n\t\t\t\tif(i == H - 1) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\t// 만약 현재 칸이 벽돌이면서 밑이 비어있으면 아래로 이동\n\t\t\t\tif (board[i][j] >= 1 && board[i + 1][j] == 0) {\n\t\t\t\t\tfor(int k = 1; k < H; k++) {\n\t\t\t\t\t\t// 비어있는 맨 밑까지 도달했으면\n\t\t\t\t\t\tif(i + k == H - 1 && board[i + k][j] == 0) {\n\t\t\t\t\t\t\tboard[i + k][j] = board[i][j];\n\t\t\t\t\t\t\tboard[i][j] = 0;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t\t// 다음 벽돌까지 도달했으면\n\t\t\t\t\t\telse if(board[i + k][j] >= 1) {\n\t\t\t\t\t\t\tboard[i + k - 1][j] = board[i][j];\n\t\t\t\t\t\t\tboard[i][j] = 0;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tprivate static boolean inRange(int nx, int ny) {\n\t\treturn nx >= 0 && nx < H && ny >= 0 && ny < W;\n\t}\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA5656.java","lines":172,"code":"import java.util.*;\nimport java.io.*;\npublic class SWEA5656 {\n\tstatic int[][] board;\n\tstatic int min;\n\tstatic int H;\n\tstatic int W;\n\tstatic int N;\n\tstatic int[] dx = {1,0,-1,0};\n\tstatic int[] dy = {0,1,0,-1};\n\t\n\tpublic static void main(String[] args) throws IOException {\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\tN = Integer.parseInt(st.nextToken());\n\t\t\tW = Integer.parseInt(st.nextToken());\n\t\t\tH = Integer.parseInt(st.nextToken());\n\t\t\t\n\t\t\tboard = new int[H][W];\n\t\t\t\n\t\t\tfor(int i = 0; i < H; i++) {\n\t\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\t\tfor(int j = 0; j < W; j++) {\n\t\t\t\t\tboard[i][j] = Integer.parseInt(st.nextToken());\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tmin = Integer.MAX_VALUE;\n\t\t\t\n\t\t\tdfs(0,board);\n\t\t\t\n\t\t\tSystem.out.println(\"#\" + tc + \" \" + min);\n\t\t\t\n\t\t}\n\t\t\n\t\t\n\t}\n\t// 구슬을 떨어뜨릴 열을 선택하는 완전탐색\n\tstatic void dfs(int depth, int[][] board) {\n\t\t\n\t\tif(depth == N) {\n\t\t\tint temp = countBrick(board);\n\t\t\t\n\t\t\tmin = Math.min(min, temp);\n\t\t\treturn;\n\t\t\t\n\t\t}\n\t\t\n\t\tfor(int i = 0; i < W; i++) {\n\t\t\t\n\t\t\tint[][] copy = copyMap(board);\n\t\t\tsearchBrick(i, copy,depth);\n\t\t}\n\t\t\n\t}\n\t\n\t\n\t\n\t\n\t//구슬을 떨어뜨릴 열을완전탐색\n\tstatic void searchBrick(int col, int[][] board,int depth) {\n\t\t\n\t\tfor(int i = 0; i < H; i++) {\n\t\t\tif(board[i][col] !=0) {\n\n\t\t\t\tbreakBrick(i,col,board); // 부숴진 맵, 이제 떨궈야함\n\t\t\t\tdropBrick(board);\n\t\t\t\t\n\t\t\t\tdfs(depth+1, board);\n\t\t\t\treturn; //해당 메서드는 첫번째 벽돌만 찾고 종료 시켜야함.\n\t\t\t\t\n\t\t\t}\n\t\t}\n\t\t\n\t\tdfs(depth+1, board); //!!!!!!!!!해당열에 벽돌이 없는 경우\n\t}\n\t\n\t\n\tstatic void breakBrick(int x, int y, int[][] board) {\n\n\t    ArrayDeque<int[]> q = new ArrayDeque<>();\n\t    q.offer(new int[] {x, y});\n\n\t    while (!q.isEmpty()) {\n\n\t        int[] current = q.poll();\n\t        int a = current[0];\n\t        int b = current[1];\n\n\t        if (board[a][b] == 0) {\n\t            continue;\n\t        }\n\n\t        int power = board[a][b];\n\t        board[a][b] = 0;\n\n\t        for (int dir = 0; dir < 4; dir++) {\n\n\t            for (int distance = 1; distance < power; distance++) {\n\n\t                int nx = a + dx[dir] * distance;\n\t                int ny = b + dy[dir] * distance;\n\n\t                if (!inRange(nx, ny)) {\n\t                    continue;\n\t                }\n\n\t                if (board[nx][ny] != 0) {\n\t                    q.offer(new int[] {nx, ny});\n\t                }\n\t            }\n\t        }\n\t    }\n\t}\n\t\n\t\nstatic void dropBrick(int[][] map) {\n\t\n\tfor(int col = 0; col < W; col++) {\n\t\t\n\t\tint writeRow = H-1;\n\t\t\n\t\tfor(int row = H-1; row >= 0; row--) {\n\t\t\tif(map[row][col] != 0) {\n\t\t\t\t\n\t\t\t\tint value = map[row][col];\n\t\t\t\tmap[row][col] = 0; //0이 아니면 현재 위치 0으로 하고 값 적어야하는 곳으로 이동시킴\n\t\t\t\t\n\t\t\t\tmap[writeRow][col] = value;\n\t\t\t\twriteRow--;\n\t\t\t}\n\t\t}\n\t}\n}\n\t\n\tstatic int countBrick(int[][] map){\n\t\tint cnt = 0;\n\t\tfor(int i = 0; i < H; i++) {\n\t\t\tfor(int j = 0; j < W; j++) {\n\t\t\t\tif(map[i][j] != 0) {\n\t\t\t\t\tcnt++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn cnt;\n\t}\n\t\n\t\n\t//맵 깊은 복사\n\tstatic int[][] copyMap(int[][] map){\n\t\tint[][] copy = new int[H][W];\n\n\t\tfor(int i = 0; i < H; i++) {\n\t\t\tcopy[i] = map[i].clone();\n\t\t}\n\t\t\n\t\treturn copy;\n\t\t\n\t}\n\t\n\tstatic boolean inRange(int x, int y) {\n\t\treturn x>=0 && x  < H &&  y >= 0 && y < W;\n\t}\n\n}","review":null}],"teamFeedback":null},{"key":"swea/5658","platform":"swea","problemId":"5658","title":"보물상자 비밀번호","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA5658.java","lines":68,"code":"/*\n전략\n- 0, 1, 2 … N-1 번째 회전에서 나올 수 있는 숫자 N개 찾기\n    - 중복 제거 필요.\n- 해당 숫자들을 10진수로 변환 후 정렬해서 K번째 수 찾기\n- 한번 회전시킬때마다의 자물쇠의 상태를 String 배열에 저장해서 검사\n\n로직\n- 자물쇠 4변을 저장하는 String[4] 배열 사용\n- 각 변에 대해, 이전 변의 마지막 문자를 내 변의 첫 문자로 추가\n- 문자 하나 추가했으니 현재 변의 길이가 유지되도록 마지막 문자 제거\n    - 위 2 과정을 for문에서 한번에 하려고 하면 마지막 문자를 다음 변에 줄 수 없어서 로직이 꼬임\n- 각 변을 16진수 문자열에서 10진수 long으로 변환해서 중복 체크 후 저장\n    - 한 변의 최대값 FFFFFFF = 16^7 - 1 = 약 27억 > Integer.MAX_VALUE이므로 long 사용\n- 저장한 숫자 배열을 내림차순 정렬 후 K-1 인덱스의 값을 꺼내서 출력\n*/\n\nimport java.io.*;\nimport java.util.*;\n\npublic class SWEA5658 {\n\tpublic static void main(String[] args) throws Exception{\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int t = 1; t <= T; t++) {\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\t\n\t\t\tint N = Integer.parseInt(st.nextToken());\n\t\t\tint K = Integer.parseInt(st.nextToken());\n\t\t\tList<Long> nums = new ArrayList<>();\n\t\t\tString[] locks = new String[4];\n\n      // 초기 locks 4변의 상태 입력\n\t\t\tString line = br.readLine();\n\t\t\tfor(int i = 0; i < N; i += N / 4) {\n\t\t\t\tlocks[i / (N / 4)] = line.substring(i, i + (N / 4));\n\t\t\t}\n\t\t\t\n\t\t\tfor(int i = 0; i < (N / 4); i++) {\n\t\t\t\t// 이전 변의 마지막 문자를 내 변의 가장 앞에 추가\n\t\t\t\tfor(int j = 0; j < 4; j++) {\n\t\t\t\t\tlocks[j] = locks[(j - 1 + 4) % 4].charAt(locks[(j - 1 + 4) % 4].length() - 1) + locks[j];\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\tfor(int j = 0; j < 4; j++) {\n\t\t\t\t\t// 문자 추가한 만큼 길이 쳐내기\n\t\t\t\t\tlocks[j] = locks[j].substring(0, N / 4);\n\t\t\t\t\t\n\t\t\t\t\t// 중복 검사 후 결과 리스트에 추가\n\t\t\t\t\tlong lockNum = Long.parseLong(locks[j], 16);\n\t\t\t\t\tif(!nums.contains(lockNum)) {\n\t\t\t\t\t\tnums.add(lockNum);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\t\n\t\t\tCollections.sort(nums, Collections.reverseOrder());\n\t\t\t\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(nums.get(K - 1)).append(\"\\n\");\n\t\t}\n\t\t\n\t\tSystem.out.print(sb);\n\t}\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA5658.java","lines":74,"code":"import java.util.*;\nimport java.lang.*;\nimport java.io.*;\n/*\n    16진수 수가 K번째 인수를 10진수로 변환하기\n    \n    자료구조: ArrayList\n    시간복잡도: O(n^2)\n\n    1. 큐의 숫자를 앞에서부터 3개씩 합침\n    2. 한바퀴 돌때마다 ArrayList에 있는 숫자가 하나씩 이동함 마지막껀 맨 앞으로옴\n    3. 10진수를 새로운 ArrayList에 저장해서 내림차순함\n      - 중복으로 저장되어선 안됨\n    4. K번째 수를 10진수로 변환해서 출력\n*/\npublic class SWEA5658 {\n    static List<Character> list1;\n    static List<Integer> list2;\n    static int n, k;\n    public static void main(String[] args) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        StringBuilder sb = new StringBuilder();\n        StringTokenizer st;\n        \n        int t = Integer.parseInt(br.readLine());\n\n        for(int tc=1; tc<=t; tc++) {\n            st = new StringTokenizer(br.readLine());\n            n = Integer.parseInt(st.nextToken());\n            k = Integer.parseInt(st.nextToken());\n\n            int section = n / 4;\n            \n            String jinsu = br.readLine(); // 1B3B3B81F75E\n\n            list1 = new ArrayList<>();\n            list2 = new ArrayList<>();\n            \n            for(int i=0; i<jinsu.length(); i++) {\n                char ch = jinsu.charAt(i);\n                list1.add(ch);\n            }\n\n            int answer = 0;\n            for(int k=0; k<section; k++) {      \n                String str = \"\";\n                int cnt = 0;\n                \n                for(int i=0; i<list1.size(); i++) {\n                    str += list1.get(i);\n                    cnt++;\n                    if(cnt == section) {\n                        int x = Integer.parseInt(str, 16);\n                        if(!list2.contains(x)) {\n                            list2.add(x);\n                        }\n                        str = \"\";\n                        cnt = 0;\n                    }\n                }\n\n                // list2 내림차순\n                Collections.sort(list2, Collections.reverseOrder());\n\n                // list1의 마지막 것을 지우고 맨 앞으로 넣기\n                list1.add(0, list1.remove(list1.size()-1));\n            }  \n            answer = list2.get(k-1);\n            sb.append(\"#\").append(tc).append(\" \").append(answer).append(\"\\n\");\n        }\n        System.out.println(sb.toString());\n    }\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA5658.java","lines":65,"code":"import java.util.*;\nimport java.io.*;\n\npublic class SWEA5658 {\n\tstatic TreeSet<Integer> set;\n\tstatic int M;\n\n\t\n\tpublic static void main(String[] args) throws IOException{\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringTokenizer st;\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tset = new TreeSet<>(Collections.reverseOrder());\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\tint N = Integer.parseInt(st.nextToken());\n\t\t\tint K = Integer.parseInt(st.nextToken());\n\t\t\tM = N / 4; //한 변의 문자열의 길이,M번만큼 움직이면 제자리로 돌아\n\t\t\t\n\t\t\tString line = br.readLine();\n\t\t\t\n\t\t\tfor(int j = 0; j < M; j++) {\n\t\t\t\t\n\t\t\t\taddString(line);\n\t\t\t\tline = line.substring(N - 1) + line.substring(0, N - 1);    \n\t\t\t\n\t\t}\n\t\t\t\n\t\t\tint index = 0;\n\t\t\tStringBuilder result = new StringBuilder();\n\t\t\tfor(Integer num : set) {\n\t\t\t\tif(index == K-1) {\n\t\t\t\t\tresult.append(\"#\" + tc + \" \"+ num);\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\tindex++;\n\t\t\t}\n\t\t\tSystem.out.println(result);\n\t\t\n\t}\n}\n\t\t\n\tstatic void addString(String line) {\n\t\t\n\t\t\n\t\tfor(int i = 0; i < 4; i++) {\n\t\t\t\n\t\t\tint start = i*M;\n\t\t\tint end = start+M;\n\t\t\t\n\t\t\tString str = line.substring(start, end);\n\t\t\tint num = Integer.parseInt(str,16); //10진수로 변환\n\t\t\t\n\t\t\tset.add(num);\n\t\t\t\n\t\t}\n\t\treturn;\n\t}\n\n}","review":null}],"teamFeedback":null},{"key":"swea/14510","platform":"swea","problemId":"14510","title":"나무 높이","url":null,"weeks":[1],"entries":[{"author":"junsoo","authorName":"김준수","week":1,"variant":null,"source":"김준수/week1/SWEA14510.java","lines":80,"code":"/*\n * 전략\n\n- 규칙 찾기\n- 나무 높이를 돌며 최대값과 전체 높이의 합을 찾는다.\n- 목표 높이 합에서 전체 높이 합을 빼서 제일 적게 쓸 수 있는 1의 개수와 제일 많이 쓸 수 있는 2의 개수를 찾는다.\n- 1과 2의 개수의 차가 최소가 될 때까지 반복한다(차의 종류는 1, 0, -1이 된다)\n    - 2의 개수 1개를 1의 개수 2개로 바꾼다\n- 1의 개수와 2의 개수의 차를 통해 결과를 계산한다\n    - 1의 개수 > 2의 개수인 경우 1212....121로 끝남.\n        - 따라서 1의 개수 * 2만큼 세되 마지막에 2가 없으니 1만큼 뺌\n    - 1의 개수 == 2의 개수인 경우 1212....1212로 끝남. 1의 개수 < 2의 개수인 경우 1212....12X2로 끝남\n        - 따라서 두 경우의 수 모두 2의 개수 * 2만큼 세면 됨\n\n시행착오\n\n- 처음에는 목표 높이 합 - 전체 높이 합에서 (1+2) 를 2번으로 묶어서 \n  gap / 3 + gap % 3으로 계산했는데, 이 경우 10 9 9 9 반례를 보면 \n  답은 5번이나 저 공식에 따르면 답이 2가 나오는 문제 찾음\n- 이후 각 높이가 최대높이가 될 때까지 필요한 1의 개수와 2의 개수를 각각 구해서 \n  1과 2의 개수가 겹치는 만큼 * 2일을 더하고, 두 횟수 중 남은 일수만큼 *2 -1이나 *2를 해서 계산함.\n  이 경우 1과 2의 개수 차이가 커서 1X1X나 X2X2 처럼 횟수를 낭비하는 경우가 많았음\n * \n */\n\nimport java.util.*;\nimport java.io.*;\n\npublic class SWEA14510 {\n\tpublic static void main(String[] args) throws Exception{\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tStringBuilder sb = new StringBuilder();\n\t\t\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int t = 1; t <= T; t++) {\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tint[] trees = new int[N];\n\t\t\tint maxHeight = 0;\n\t\t\tint day = 0;\n\t\t\tint oneCnt = 0; int twoCnt = 0;\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\ttrees[i] = Integer.parseInt(st.nextToken());\n\t\t\t\tmaxHeight = Math.max(maxHeight, trees[i]);\n\t\t\t}\n\t\t\t\n\t\t\t// 최소한으로 필요한 1의 개수와 최대로 쓸 수 있는 2의 개수 찾기\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t    int diff = maxHeight - trees[i];\n\t\t\t    oneCnt += diff % 2; \n\t\t\t    twoCnt += diff / 2; \n\t\t\t}\n\n\t\t\t// 2 하나를 1 두개로 넘기기\n\t\t\t// 2의 개수와 1의 개수의 차가 최소가 될 떄까지\n\t\t\twhile (twoCnt - oneCnt >= 2) {\n\t\t\t    twoCnt--;\n\t\t\t    oneCnt += 2;\n\t\t\t}\n\n\t\t\t// 1의 개수 > 2의 개수인 경우 1212....121로 끝남 \n\t\t\t// 따라서 1의 개수만큼 세되 마지막에 2가 없으니 1일을 뺌\n\t\t\tif (oneCnt > twoCnt) {\n\t\t\t    day = oneCnt * 2 - 1;\n\t\t\t// 1의 개수 == 2의 개수인 경우 1212...1212로 끝남\n\t\t\t// 1의 개수 < 2의 개수인 경우 1212...12X2로 끝남\n\t\t\t// 두 경우의 수 모두 2의 개수만큼 세면 됨\n\t\t\t} else {\n\t\t\t    day = twoCnt * 2;\n\t\t\t}\n\n\t\t\tsb.append(\"#\").append(t).append(\" \").append(day).append(\"\\n\");\n\t\t}\n\t\t\n\t\tSystem.out.print(sb);\n\t}\n}","review":null},{"author":"chanung","authorName":"안찬웅","week":1,"variant":null,"source":"안찬웅/week1/SWEA14510.java","lines":94,"code":"import java.util.*;\nimport java.io.*;\n/*\n * 모든 나무의 키가 첫날 가장 큰 나무와 같아지는 최소 날\n * \n * 알고리즘: 이분탐색\n *\n * maxHeight 기준 부족한 개수\n * 1. d[i] = maxHeight - arr[i]\n * 2. 물 주는 순서 상관x\n *     +1 a장, +2 b장으로 d[] 변환\n * 3. b = day/2,  a = day-b\n * 4. check(day)\n *    - d[i] 홀수면 +1\n *    - +2는 짝수만\n */\npublic class SWEA14510 {\n    static int[] arr;\n    static int[] d;\n    static int n;\n    static int maxHeight; // 가장 큰 나무 높이\n \n    public static void main(String[] args) throws Exception {\n    \tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n    \t//BufferedReader br = new BufferedReader(new StringReader(input));\n    \tStringBuilder sb = new StringBuilder();\n        StringTokenizer st;\n        int t = Integer.parseInt(br.readLine());\n        \n        for(int tc=1; tc<=t; tc++) {\n        \tsb.append(\"#\").append(tc).append(\" \");\n            n = Integer.parseInt(br.readLine());\n            \n            arr = new int[n];\n            d = new int[n];\n            \n            maxHeight = Integer.MIN_VALUE;\n            \n            st = new StringTokenizer(br.readLine());\n            for(int i=0; i<n; i++) {\n                arr[i] = Integer.parseInt(st.nextToken());\n                maxHeight = Math.max(maxHeight, arr[i]);\n            }\n            \n            for(int i=0; i<n; i++) {\n            \td[i] = maxHeight - arr[i]; \n            }\n            \n            int low = 0;\n            int high = Integer.MAX_VALUE;\n            int result = 0;\n            \n            while(low <= high) {\n            \tint mid = (low + high) / 2;\n            \tif(check(mid)) {\n            \t\tresult = mid;\n            \t\thigh = mid - 1;\n            \t} else {\n            \t\tlow = mid + 1;\n            \t}\n            }\n            \n            sb.append(result).append(\"\\n\");\n        }\n        System.out.println(sb.toString());\n    }\n    static boolean check(int day) {\n    \tint b = day / 2; // 짝수날 개수 = +2카드 장수\n    \tint a = day - b; // 홀수날 개수 = +1카드 장수\n    \t\n    \tint odd = 0;\n    \tint total = 0;\n    \tfor(int i=0; i<n; i++) {\n    \t\ttotal += d[i];\n    \t\tif(d[i] % 2 == 1) {\n    \t\t\todd++;\n    \t\t}\n    \t}\n    \t\n    \tif(odd > a) return false; // +1이 창고보다 많으면 false\n    \t\n    \tint need2 = (total - odd) / 2;\n    \t\n    \tif (need2 <= b) return true; // +2가 창고보다 많으면 true\n    \t\n    \tif((odd + (need2 - b) * 2) <= a) { // +2 -> +1 두 장으로 환산\n    \t\treturn true;\n    \t}\n    \t\n    \treturn false;\n    }\n}","review":null},{"author":"seongil","authorName":"이성일","week":1,"variant":null,"source":"이성일/week1/SWEA14510.java","lines":53,"code":"package swtb;\n\nimport java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.StringTokenizer;\n\npublic class SWEA14510 {\n\t\n\tpublic static void main(String[] args) throws Exception {\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint tc = Integer.parseInt(br.readLine());\n\t\tStringTokenizer st;\n\t\tfor (int i = 1; i <= tc; i++) {\n\t\t\tint n = Integer.parseInt(br.readLine());\n\t\t\tst = new StringTokenizer(br.readLine());\n\t\t\tList<Integer> trees = new ArrayList<>();\n\t\t\tfor (int j = 0; j < n; j++) {\n\t\t\t\ttrees.add(Integer.parseInt(st.nextToken()));\n\t\t\t}\n\t\t\t\n\t\t\tint top = Collections.max(trees);\n\t\t\tint gap, one = 0, two = 0;\n\t\t\n\t\t\tfor(int j = 0; j < n; j++) {\n\t\t\t\tgap = top - trees.get(j);\n\t\t\t\tone += (gap%2);\n\t\t\t\ttwo += (gap / 2);\n\t\t\t}\n\t\t\t\n\t\t\tint ans = Integer.MAX_VALUE;\n\t\t\tfor (int split = 0; split <= two; split++) {\n\t\t\t\tint newone = one + split * 2;\n\t\t\t\tint newtwo = two - split;\n\t\t\t\t\n\t\t\t\tint oddDay = 2 * newone - 1;\n\t\t\t\tint evenDay = 2 * newtwo;\n\t\t\t\t\n\t\t\t\tint day = Math.max(oddDay, evenDay);\n\t\t\t\t\n\t\t\t\tans = Math.min(ans, day);\n\t\t\t\t\n\t\t\t}\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(i).append(\" \" ).append(ans).append(\"\\n\");\n\t\t\tSystem.out.print(sb);\n\t\t}\n\t}\n}","review":null},{"author":"seungjoo","authorName":"이승주","week":1,"variant":null,"source":"이승주/1주차/SWEA14510.java","lines":66,"code":"import java.util.*;\nimport java.io.*;\n\n\n/*\n * 2시간 정도 고민해서 조건을 나눠 시뮬레이션으로 풀려고 했는데 시간 초과나서 도저히 모르겠어 gpt한테 힌트를 받아 필요한 날짜를 구하게 한다는 것을 알게 됌\n * two랑 one+1이 같은 경우에는 while문의 조건이 필요가 없지만 넘어가는 경우엔 two 1개를 one 2개로 바꿀 수 잇음\n */\npublic class SWEA14510{\n\tstatic int answer;\n\tstatic int max;\n\tpublic static void main(String[] args) throws IOException {\n\t\t\n\t\tBufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n\t\tint T = Integer.parseInt(br.readLine());\n\t\t\n\t\tfor(int tc = 1; tc <= T; tc++) {\n\t\t\t\n\t\t\tanswer = 0;\n\t\t\tmax = 0;\n\t\t\tint N = Integer.parseInt(br.readLine());\n\t\t\tStringTokenizer st = new StringTokenizer(br.readLine());\n\t\t\tInteger[] tree = new Integer[N];\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\t\n\t\t\t\ttree[i] = Integer.parseInt(st.nextToken());\n\t\t\t\tmax = Math.max(tree[i], max);\n\t\t\t\t\n\t\t\t}\n\t\t\tfor(int j = 0; j < N; j++) {\n\t\t\t\ttree[j] = max - tree[j];\n\t\t\t}\n\t\t\t//tree[i]는 남은 길이\n\t\t\t\n\t\t\t\n\t\t\tint one = 0;\n\t\t\tint two = 0;\n\t\t\t\n\t\t\tfor(int i = 0; i < N; i++) {\n\t\t\t\tone += tree[i]%2;\n\t\t\t\ttwo += tree[i]/2;\n\t\t\t\t\n\t\t\t}\n\t\t\t\n\t\t\twhile(two > one +1) {\n\t\t\t\ttwo--;\n\t\t\t\tone += 2;\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t\tif(one > two) {\n\t\t\t\tanswer = one * 2 -1;\n\t\t\t\t\n\t\t\t}else {\n\t\t\t\tanswer = two * 2;\n\t\t\t}\n\t\t\t\n\t\t\tStringBuilder sb = new StringBuilder();\n\t\t\tsb.append(\"#\").append(tc).append(\" \").append(answer);\t\n\t\t\tSystem.out.println(sb);\n\t\t\t\n\t\t}\n\t\t\n\t}\n}","review":null}],"teamFeedback":null}]};
